  /**
   * {@inheritDoc}
   */
  @Override
  public String getReportHtml(Long reportCd, Map<String, Object> dataKey, Long targetPrinter, Long userId)
    throws NotExistException {
    //add IES因島）sql性能試験 後で削除 liuc start
    Date beginTime = new Date();
    //add IES因島）sql性能試験 後で削除 liuc end
    // 帳票マスタを取得する
    MstReport mstReport = getMstReport(reportCd);
    // 帳票コードに該当する帳票マスタが取得出来ない場合
    EventLogMessage eventLogMessage = new EventLogMessage();
    if (mstReport == null) {
      eventLogMessage.setLogMessage("レポートコードに該当する帳票マスタの取得に失敗しました。レポートコード：" + reportCd.toString());
      eventLogMessage.setFacilityCd(mstReport.getFacilityCd());
      logService.log(LogLevel.ERROR, eventLogMessage, null, SERVICE_NAME.FNSI, null);
      return "";
    }
    // 帳票種別がnullの場合
    if (Objects.isNull(mstReport.getReportClass())) {
      eventLogMessage.setLogMessage("レポートコードに該当する帳票種別が未登録です。レポートコード：" + reportCd.toString());
      eventLogMessage.setFacilityCd(mstReport.getFacilityCd());
      logService.log(LogLevel.ERROR, eventLogMessage, null, SERVICE_NAME.FNSI, null);
      return "";
    }
    String reportHtml = "";
    if (mstReport.getReportClass().equals(ReportConstant.ReportClass.ONE_PATIENT_REPORT)
        || mstReport.getReportClass().equals(ReportConstant.ReportClass.MULTIPLE_PATIENT_REPORT)) {
      // mod #6346 処方の項目が足りない 王永吉 start
      // 単患者帳票または複数患者帳票
      //reportHtml = createPatientReportHtml(mstReport, dataKey);
      if (mstReport.getReportClass().equals(ReportConstant.ReportClass.ONE_PATIENT_REPORT)
        && (null != mstReport.getReportType() && mstReport.getReportType() == 2)) {

        reportHtml = createDistributionListSyohousen(mstReport, dataKey);
      } else {
        // mod #7840 帳票（単患者）：薬剤にフィルター機能がない 王永吉 start
//        // 単患者帳票または複数患者帳票
//        reportHtml = createPatientReportHtml(mstReport, dataKey);
        if (mstReport.getReportClass().equals(ReportConstant.ReportClass.ONE_PATIENT_REPORT)){
          // 単患者帳票
          reportHtml = createOnePat(mstReport, dataKey);
          // mod #8182 帳票出力時にasposeを経由しないで出力される帳票がある 日本指摘対応 鄭爽 end
          // mod #8182 帳票出力時にasposeを経由しないで出力される帳票がある 鄭爽 end
        } else {
          // 複数患者帳票など
          reportHtml = createPatientReportHtml(mstReport, dataKey);
        }
        // mod #7840 帳票（単患者）：薬剤にフィルター機能がない 王永吉 end
      }
      // mod #6346 処方の項目が足りない 王永吉 end
    } else if (mstReport.getReportClass().equals(ReportConstant.ReportClass.DISTRIBUTION_LIST_BED_REPORT)) {
      // 配布リスト(ベッド)
      reportHtml = createDistributionList(mstReport, dataKey);
      // mod #8182 帳票出力時にasposeを経由しないで出力される帳票がある 日本指摘対応 鄭爽 end
      // mod #8182 帳票出力時にasposeを経由しないで出力される帳票がある 鄭爽 end
    // add FNSI-523 2次元帳票対応 夏 start
      // add 特殊二次元帳票「紹介状」帳票レイアウトの対応 start
    } else if (mstReport.getReportClass().equals(ReportConstant.ReportClass.ONE_TOTAL_REPORT)
              || mstReport.getReportClass().equals(ReportConstant.ReportClass.MULTI_TOTAL_REPORT)
              || (mstReport.getReportClass().equals(ReportConstant.ReportClass.INTRODUCTION_REPORT)
                  && (null != mstReport.getReportType() && mstReport.getReportType() == 1))) {
      // add 特殊二次元帳票「紹介状」帳票レイアウトの対応 end
      // 集計
      // mod by shangkuiwei 2023-02-05 [Variable,CodeOptimization] --start
      // reportHtml = createTotalReportHtml(mstReport, dataKey);
      Map<String, Long> patIdToCMap = new HashMap<>();
      // mod #8305 週間医材集計表の出力処理中にwebappサーバのCPU使用率が100％になる 夏 start
//      reportHtml = createTotalReportHtml(mstReport, dataKey, patIdToCMap);
      Map<String, String> outPutHtml = new HashMap<>();
      // add #5604 帳票表示項目の不足 王占宇 start
      dataKey.put("facilityCd", mstReport.getFacilityCd());
      // add #5604 帳票表示項目の不足 王占宇 end
      // mod #11985 定期点検一覧帳票が正常に出せない limingzhe start
      //reportHtml = createTotalReportHtml(mstReport, dataKey, patIdToCMap, outPutHtml);
      try{
        ByteArrayOutputStream os = new ByteArrayOutputStream();
        byte[] excelBytes = reportForTotalService.getReportExcelFileForMultiTotal(reportCd, dataKey);
        URL url = resourceLoader.getResource(ReportConstant.ReportGraph.LIC).getURL();
        reportHtml = AsposeCellsUtils.excelToSvg(new ByteArrayInputStream(excelBytes),url);
      } catch (Exception e) {
        // エラーメッセージ
        EventLogMessage eventLogMes = new EventLogMessage();
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang start
        eventLogMes.setLogMessage("帳票Excelファイルの出力に失敗しました。：" + ExcetionStackTraceToString(e));
        if (mstReport != null && mstReport.getFacilityCd() != null) {
          eventLogMessage.setFacilityCd(mstReport.getFacilityCd());
        }
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang end
        logService.log(LogLevel.ERROR, eventLogMes, "", LoggingConstant.SERVICE_NAME.FNSI, null);
        throw new NtssException("帳票Excelファイルの読み込みに失敗しました。");
      }
      // mod #11985 定期点検一覧帳票が正常に出せない limingzhe end
      // mod #8305 週間医材集計表の出力処理中にwebappサーバのCPU使用率が100％になる  夏 end
      // mod by shangkuiwei 2023-02-05 [Variable,CodeOptimization] --end
    // add FNSI-523 2次元帳票対応 夏 end
    } else {
      reportHtml = createReportHtml(mstReport, dataKey);
    }
    // add 2021-06-03 #4891："Bitmap"の文字がプレビューの上に表示される wangchen start
    // Bitmap"の文字がプレビューの上に表示される
    ReportZipFile reportZipFileTmp = getReportZip(mstReport);
    List<String> fileList = reportZipFileTmp.getFileToString();
    List<String> fileListPng = new ArrayList<String>();
    for(int i=0;i<fileList.size();i++) {
      if (fileList.get(i).endsWith(".png")) {
        fileListPng.add(fileList.get(i));
      }
    }
    for(int i=0;i<fileListPng.size();i++) {
      String pngFileName = fileListPng.get(i);
      byte[] image = reportZipFileTmp.getFile(pngFileName);
      if(Objects.isNull(image)){
        eventLogMessage.setLogMessage("帳票の中の写真[" + fileListPng.get(i) + "]は空です：reportCd=[" + reportCd.toString() + "]");
        eventLogMessage.setFacilityCd(mstReport.getFacilityCd());
        logService.log(LogLevel.ERROR, eventLogMessage, null, SERVICE_NAME.FNSI, null);
      } else {
        String[] parts = pngFileName.split("_");
        String imagePath = parts[0] + "_" + parts[1] + ".files/" + pngFileName;
        String byteStr = Base64.getEncoder().encodeToString(Objects.isNull(image)?new byte[]{}:image);
        String newSrc = String.format("data:image/png+xml;base64,%s", byteStr);

        // Imageの位置を取得すう
        int indexImage = reportHtml.indexOf(imagePath);
        if (indexImage == -1) {
          // 画像ファイル名が存在しなかった場合、後続処理でエラーとなる為、スキップします。AsposeでSVG変換を行った際に、画像ファイル部がbase64のバイナリ形式のデータが応答され、画像ファイル名ではindexを取得できなくなる為の対応です。
          continue;
        }
        // データ分割
        String reportHtmlBefore = reportHtml.substring(0, indexImage);
        String reportHtmlAfter = reportHtml.substring(indexImage);

        // 「td」層の位置を取得すう
        String seachStr = "<td";
        int indexTd = reportHtmlBefore.lastIndexOf(seachStr);
        // 画像があるの「td」層は「position:relative;」を追加します。
        seachStr = "style=\"";
        int indexStyle = reportHtmlBefore.indexOf(seachStr, indexTd);
        int indexStyleCheck = reportHtmlBefore.indexOf("position:relative;", indexTd);
        if (indexStyleCheck < 0) {
          reportHtmlBefore = reportHtmlBefore.substring(0, indexStyle + seachStr.length())
            + "position:relative;" + reportHtmlBefore.substring(indexStyle + seachStr.length());
        }

        // 画像があるの「v:shape」層は「MARGIN-xxx」を削除します。
        seachStr = "<v:shape";
        int indexVShapeStart = reportHtmlBefore.lastIndexOf(seachStr);
        seachStr = "MARGIN-";
        int indexMarginStart = reportHtmlBefore.indexOf(seachStr, indexVShapeStart);
        do {
          int indexMarginEnd = reportHtmlBefore.indexOf(";", indexMarginStart);
          int indexMarginEndCheck = reportHtmlBefore.indexOf("\"", indexMarginStart);
          if (indexMarginEnd > indexMarginEndCheck) {
            indexMarginEnd = indexMarginEndCheck-1;
          }
          indexMarginEnd = indexMarginEnd + 1;
          String dataMargin = reportHtmlBefore.substring(indexMarginStart, indexMarginEnd);

          int indexMarginCheck = reportHtmlBefore.indexOf(("/*" + dataMargin + "*/"), indexVShapeStart);
          if (indexMarginCheck < 0) {
            reportHtmlBefore = reportHtmlBefore.substring(0, indexMarginStart)
              + "/*" + dataMargin + "*/" + reportHtmlBefore.substring(indexMarginEnd);
          }

          indexMarginStart = reportHtmlBefore.indexOf(seachStr, indexMarginEnd + 4);
        } while(indexMarginStart >= 0);

        // データ合併
        reportHtml = reportHtmlBefore + reportHtmlAfter;

        // 画像を2進データに置き換える
        reportHtml = reportHtml.replace(imagePath, newSrc);
      }
    }
    // add 2021-06-03 #4891："Bitmap"の文字がプレビューの上に表示される wangchen end
    //add IES因島）sql性能試験 後で削除 liuc start
    Date endTime = new Date();
    String sqlTestSign = (String) dataKey.get("sqlTestSign");
    EventLogMessage LogMessage = new EventLogMessage();
    LogMessage.setLogMessage(sqlTestSign + "ReportServiceImpl::getReportHtml 実行時間:" + (endTime.getTime() - beginTime.getTime()) + "ms");
    logService.log(LogLevel.INFO, LogMessage, FUNCTION_CODE.FUNC_REPORT_MENU, SERVICE_NAME.FNSI, null);
    //add IES因島）sql性能試験 後で削除 liuc end

    return reportHtml;
  }

