  @Override
  public List<MstReport> getAllMstFunctionReportForFixedAndNormal(String facilityCd, String funcCd, String printFlag) {
    List<String> facilitySettingNos = new ArrayList<>();
    facilitySettingNos.addAll(getFixedFacilitySettingNoList());
    if(!funcCd.equals("00401") && !funcCd.equals("00601") && !funcCd.equals("00701")){
      facilitySettingNos.remove(CoreConstant.FacilitySettingNo.FIXED_DIALYSIS_REPORT_SETTING);
    }
    if(!funcCd.equals("00401") && !funcCd.equals("00601") && !funcCd.equals("00701")){
      facilitySettingNos.remove(CoreConstant.FacilitySettingNo.FIXED_DIALYSIS_REPORT_HANDWRITTEN_SETTING);
    }
    if(!funcCd.equals("03401")){
      facilitySettingNos.remove(CoreConstant.FacilitySettingNo.FIXED_DAILY_INSPECT_RECORD_BOOK_SETTING);
    }
    if(!funcCd.equals("03301")){
      facilitySettingNos.remove(CoreConstant.FacilitySettingNo.FIXED_PERIODIC_INSPECT_RECORD_BOOK_SETTING);
    }
    // add #12582 固定帳票「水質管理記録簿」が必要 limingzhe start
    if(!funcCd.equals("03201")){
      facilitySettingNos.remove(CoreConstant.FacilitySettingNo.FIXED_WATER_SURVEY_RECORD_BOOK_SETTING);
    }
    // add #12582 固定帳票「水質管理記録簿」が必要 limingzhe end

    List<Long> reportCds = mstFunctionReportDao.selectAllForFixedAndNormal(funcCd, facilityCd, printFlag, facilitySettingNos, "1", "0")
      .stream()
      .map(e -> e.getReportCd())
      .collect(toList());

    List<MstReport> reportInfos = mstReportDao.selectAllForFixedAndNormal(facilityCd, facilitySettingNos, "1", "0");

    // レポートCDをもとに帳票マスタを取得し、返却する
    return reportInfos.stream()
      .filter(e -> reportCds.contains(e.getReportCd()))
      .sorted(Comparator.comparing(r -> reportCds.indexOf(r.getReportCd())))
      .collect(toList());
  }
