  @Override
  public List<MstReport> getMstReportByFacilityCd(String facilityCd) {
    try {
      // mod #11326 帳票メニューの帳票リストの固定項目の表示/非表示・並び順が制御できない limingzhe start
      //Integer reportClass = null;
      //Integer reportType = null;
      //List<MstReport> mstReports = mstReportDao.selectReports(reportClass, reportType, facilityCd);
      List<String> facilitySettingNos = getFixedFacilitySettingNoList();
      List<MstReport> mstReports = mstReportDao.selectAllForFixedAndNormal(facilityCd, facilitySettingNos, "1", "0");
      mstReports = mstReports.stream()
        // 治療経過表 ( reportClass = 1 ) は、名称の先頭に「＊＊」がついているもののみ表示する
        // 装置帳票 ( reportClass = 7 ) の場合、名称の先頭に「＊＊」ついている、又は reportType = 1 (マルチ)のもののみ表示する
        .filter(r -> !((r.getReportClass() == 1 && !r.getReportName().startsWith("＊＊") && r.getReportCd() > 0) || (r.getReportClass() == 7 && !r.getReportName().startsWith("＊＊") && r.getReportType() == 0 && r.getReportCd() > 0)))
        .collect(toList());
      // mod #11326 帳票メニューの帳票リストの固定項目の表示/非表示・並び順が制御できない limingzhe end
      return mstReports;
    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
      EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (!StringUtils.isEmpty(facilityCd)) {
        eventLogMessage.setFacilityCd(facilityCd);
      }
      logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
      return null;
    }
  }

