  /**
   * {@inheritDoc}
   */
  @Override
  public boolean convertHtmlToPdfOutputTmp(String html, String OutputPath, String fileName) {
    Path htmlPath = null;
    Path pdfPath = null;

    try {
      // HTMLデータを一時ファイルに保存
      htmlPath = tmpFileService.createTmpDirectoryAndFile(createTmpDir, "nkk-report", ".html");
      Files.write(htmlPath, html.getBytes(StandardCharsets.UTF_8));

      // fileNameの末尾に .pdf がついていなければ付ける
      if (!fileName.matches(".+\\.pdf$")) {
        fileName += fileName + ".pdf";
      }
      pdfPath = Paths.get(OutputPath, fileName);
      if (!Files.exists(pdfPath)) {
        // 出力先フォルダが存在しない場合は作成
        Files.createDirectories(pdfPath.getParent());
        File file = new File(pdfPath.toString());
        file.createNewFile();
      }

      // PDFを生成
      String[] command = {
          "wkhtmltopdf",
          htmlPath.toString(),
          pdfPath.toString()
      };
      Runtime rt = Runtime.getRuntime();
      int result = rt.exec(command).waitFor();

      if (result == 0) {
        return true;
      } else {
        // wkhtmltopdfの実行に失敗した
        throw new IOException("wkhtmltopdf failed:" + result);
      }
    } catch (IOException | InterruptedException e) {
      throw new NtssException("PDFファイルの出力に失敗しました。");
    } catch (Exception e) {
      throw new NtssException("PDFファイルの出力に失敗しました。：" + e.getMessage());
    } finally {
      // 一時ファイルを削除
      Optional.ofNullable(htmlPath).ifPresent(path -> path.toFile().delete());
    }
  }

