  // mod #5714 紹介状が正しく出力できない 日本指摘対応 鄭爽 start
//  private Integer getWeekDays(String data, String dataFormat){
//    SimpleDateFormat f = new SimpleDateFormat(dataFormat);
  private Integer getWeekDays(String data){
    SimpleDateFormat f = new SimpleDateFormat("yyyy/MM/dd");
    // mod #5714 紹介状が正しく出力できない 日本指摘対応 鄭爽 end
    Calendar cal = Calendar.getInstance();
    Date date;
    try {
      date = f.parse(data);
      cal.setTime(date);
    } catch (ParseException e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
      EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
    }
    int w = cal.get(Calendar.DAY_OF_WEEK) - 1;
    // add #6035 紹介状で曜日単位の投与マトリクスが表示できない 鄭爽 start
    if (w == 0) {
      w = 7;
    }
    // add #6035 紹介状で曜日単位の投与マトリクスが表示できない 鄭爽 end
    if (w < 0) {
      w = 0;
    }
    return w;
  }

  public static String getNextUpEn(String en){
    char lastE = 'a';
    char st = en.toCharArray()[0];
    if(Character.isUpperCase(st)){
      if(en.equals("Z")){
        return "A";
      }
      if(en==null || en.equals("")){
        return "A";
      }
      lastE = 'Z';
    }else{
      if(en.equals("z")){
        return "a";
      }
      if(en==null || en.equals("")){
        return "a";
      }
      lastE = 'z';
    }
    int lastEnglish = (int)lastE;
    char[] c = en.toCharArray();
    if(c.length>1){
      return null;
    }else{
      int now = (int)c[0];
      if(now >= lastEnglish)
        return null;
      char uppercase = (char)(now+1);
      return String.valueOf(uppercase);
    }
  }
