  /**
   * 複数のhtmlを[page-break]で結合する.
   * リストの先頭要素をベースにし、bady部に追加する.
   * 追加する際に[page-break]を設定する.
   * 与えられたリストが<code>null</code>若しくは空リストの場合、空文字を返却する.
   *
   * @param reportHtmlList htmlのリスト（完全なhtmlのリスト）
   *                       ※各リストの要素はhtml要素から始まる完全なhtmlである事
   * @return 結合したhtml文字列
   */
  private String joinReportHtml(List<String> reportHtmlList) {
    if (Objects.isNull(reportHtmlList) || reportHtmlList.isEmpty()) {
      return "";
    }
    org.jsoup.nodes.Document document = Jsoup.parse(reportHtmlList.get(0));
    org.jsoup.nodes.Element baseElement = document.getElementsByTag("body").first();
    for (int index = 1; index < reportHtmlList.size(); index++) {
      org.jsoup.nodes.Document doc = Jsoup.parse(reportHtmlList.get(index));
      org.jsoup.nodes.Element elm = doc.getElementsByTag("body").first();
      baseElement.append(getPageBreakString());
      baseElement.append(elm.html());
    }
    return document.html();
  }

  /**
   * htmlに値を埋め込んだhtmlを取得する.
   *
   * @param reportHtml html文字列
   * @param reportOutputInfoForInTempl 埋込用の値を格納したマップ
   *                                   key : htmlのid、value : 値
   * @return 値を埋め込んだhtml文字列
   */
  private String reflectReportHtml(String reportHtml, Map<String, String> reportOutputInfoForInTempl) {
    // idに変換された値をhtmlに埋め込む
    // 帳票デザインHTMLをパースする
    org.jsoup.nodes.Document document = Jsoup.parse(reportHtml);
    org.jsoup.nodes.Element baseElement = document.getElementsByTag("body").first();
    // 全ページ同じ内容を設定する内容をHTMLへ反映する
    reportOutputInfoForInTempl.entrySet().stream()
      .filter(r -> r.getKey().indexOf(MULTIPLE_PAGES_SEPARATOR) < 0)
      .forEach(r -> Optional.ofNullable(baseElement.getElementById(r.getKey())).ifPresent(e ->{
        // mod #5600 「縮小表示ができない」について、修正する 鄭 start
        // e.text(r.getValue())));
        if (e.children().size() == 0){
          e.text(r.getValue());
        } else {
          e.children().get(0).text(r.getValue());
        }}));
  // mod #5600 「縮小表示ができない」について、修正する 鄭 end
    return document.html();
  }

