          //mod 2022-04-20 6009 パラメータの追加facilityCd 鄭 start
         // html = reflectReportHtml(reportOutputInfoForInTempl, calcResult, formatConditionInfo, chartInfo, resizeFontSizeInfo);
          html = reflectReportHtml("",html, reportOutputInfoForInTempl, calcResult, formatConditionInfo, chartInfo, resizeFontSizeInfo);
