  /**
   * {@inheritDoc}
   */
  @Override
  public String getReportHtmlSchedule(Map<String, Object> dataKey, Long targetPrinter, Long userId) {

    // 出力情報を帳票デザインHTMLへ反映する
    Map<String, String> reportOutputInfo = null;

    // sys_data_setリストのレスポンス生成
    List<Map<String, Object>> res = sysDataSetService.getDataList(SQL_CD_SCHEDULE_LIST, dataKey);
    List<String> rowList = new ArrayList<String>() {
      {
        add("bed_disp_order");
        add("bed_name");
        add("bed_cd");
      }
    };
    List<String> colList = new ArrayList<String>() {
      {
        add("treat_date");
        add("kur_name");
      }
    };
    List<String> valList = new ArrayList<String>() {
      {
        add("pat_id");
      }
    };
    res = sysDataSetService.getMatrixDataList(res, rowList, colList, valList);

    List<Map<String, Object>> res2 = sysDataSetService.getDataList(SQL_CD_SCHEDULE_LIST_RESERVE, dataKey);
    List<String> rowList2 = new ArrayList<String>() {
      {
        add("dummy_bed_name");
      }
    };
    List<String> colList2 = new ArrayList<String>() {
      {
        add("treat_date");
        add("kur_name");
      }
    };
    List<String> valList2 = new ArrayList<String>() {
      {
        add("bed_unreg_count");
        add("count");
      }
    };
    res2 = sysDataSetService.getMatrixDataList(res2, rowList2, colList2, valList2);

    // 出力情報を帳票デザインHTMLへ反映する
    reportOutputInfo = new HashMap<>();

    if (!res.isEmpty()) {
      int bed_pos = 6; // ベッド名は"A6"から"A7","A8"と続く
      boolean isFirstRow = true;

      // 行方向(各 ベッド)にデータをループ
      for (Map<String, Object> resOne : res) {
        // ベッド名を帳票にセット
        reportOutputInfo.put("A" + String.valueOf(bed_pos), resOne.get("bed_name").toString());

        byte[] asciiCodes = null;
        // データ出力開始列の設定
        asciiCodes = "B".getBytes(StandardCharsets.US_ASCII);

        String prevTreatDate = "";
        // 列方向(各 透析日＋クール)にデータをループ
        for (int i = 0; i < (int) resOne.get("field_count"); i++) {
          String idColString = null;
          idColString = new String(new byte[] { (byte) (asciiCodes[0] + i) }, StandardCharsets.US_ASCII);

          final String field_0 = "field_" + String.valueOf(i + 1);

          // 行ヘッダー系は初回の行の場合のみ処理
          if (true == isFirstRow) {
            // <> 日付 行ヘッダー
            String treatDate = ((Map<String, String>) resOne.get(field_0 + "_col")).get("treat_date");

            // 治療日をMM/dd(E)の表示形式とする
            try {
              treatDate = new SimpleDateFormat("MM/dd(E)").format(new SimpleDateFormat("yyyyMMdd").parse(treatDate));
            } catch (ParseException e) {
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
              EventLogMessage eventLogMessage = new EventLogMessage();
              eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
              logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
            }

            // 同じ日付は一番左のものだけ印字して、以降は「―」を表示
            if (prevTreatDate.equals(treatDate)) {
              reportOutputInfo.put(idColString + "2", "―");
            } else {
              reportOutputInfo.put(idColString + "2", treatDate);
            }
            prevTreatDate = treatDate;
            // </>

            // クール 行ヘッダー
            reportOutputInfo.put(idColString + "3",
                ((Map<String, String>) resOne.get(field_0 + "_col")).get("kur_name"));
          }

          // 患者名
          List<Map<String, String>> al = (List<Map<String, String>>) resOne.get(field_0);
          reportOutputInfo.put(idColString + String.valueOf(bed_pos), ((Map<String, String>) al.get(0)).get("pat_id"));
        }

        isFirstRow = false;
        bed_pos++;
      }
    }

    if (res2.size() > 0) {
      byte[] asciiCodes = null;
      // データ出力開始列の設定
      asciiCodes = "B".getBytes(StandardCharsets.US_ASCII);

      // 列単位(各 透析日＋クール)にデータをループ
      for (int i = 0; i < (int) res2.get(0).get("field_count"); i++) {
        String idColString = null;
        idColString = new String(new byte[] { (byte) (asciiCodes[0] + i) }, StandardCharsets.US_ASCII);

        final String field_0 = "field_" + String.valueOf(i + 1);

        List<HashMap<String, String>> al = (List<HashMap<String, String>>) res2.get(0).get(field_0);
        // 予約数
        reportOutputInfo.put(idColString + "4", String.valueOf(((Map<String, String>) al.get(0)).get("count")));
        // ベッド未登録
        reportOutputInfo.put(idColString + "5",
            String.valueOf(((Map<String, String>) al.get(0)).get("bed_unreg_count")));
      }
    }

    // クラスパスから"report/schedule.html"を読み込む
    String reportHtml = getInputStream("report/html/schedule.html");

    Map<String, String> calcResult = new HashMap<>();
    Map<String, String> formatConditionInfo = new HashMap<>();
    Map<String, String> chartInfo = new HashMap<>();
    Map<String, String[]> resizeFontSizeInfo = new HashMap<>();

    //mod 2022-04-20 6009 パラメータの追加facilityCd 鄭 start
    return reflectReportHtml("",reportHtml, reportOutputInfo, calcResult, formatConditionInfo, chartInfo,
        resizeFontSizeInfo);
    //mod 2022-04-20 6009 パラメータの追加facilityCd 鄭 end

  }

  /**
   * クラスパスリソースからファイルを読み込む
   *
   * @param path パス名
   * @return ファイル内文字列
   */
  private String getInputStream(final String path) {
    String reportHtml = null;
    try (InputStream is = new ClassPathResource(path).getInputStream();
        BufferedReader br = new BufferedReader(new InputStreamReader(is))) {

      reportHtml = "";
      String line;
      //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
      EventLogMessage eventLogMessage = new EventLogMessage();
      //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
      while ((line = br.readLine()) != null) {
        //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
        eventLogMessage = new EventLogMessage();
        eventLogMessage.setLogMessage(line);
        logService.log(LogLevel.INFO, eventLogMessage, null, SERVICE_NAME.FNSI, null);
        //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
        reportHtml = reportHtml + line;
      }
    } catch (IOException e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
      EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
    }
    return reportHtml;
  }

  /**
   * {@inheritDoc}
   */
  @Override
  public String getReportHtmlWaterSurvey(Map<String, Object> dataKey, Long targetPrinter, Long userId) {

    // 出力情報を帳票デザインHTMLへ反映する
    Map<String, String> reportOutputInfo = null;

    // 水質調査
    // add #7233 デフォルト帳票について 日本指摘対応 商 start
    if (dataKey.get("machineNos") != null && dataKey.get("machineNo") == null) {
      dataKey.put("machineNo", dataKey.get("machineNos"));
    }
    // add #7233 デフォルト帳票について 日本指摘対応 商 end
    // sys_data_setリストのレスポンス生成
    List<Map<String, Object>> res = sysDataSetService.getDataList(SQL_CD_WATER_SURVEY_LIST, dataKey);
    List<String> rowList = new ArrayList<String>() {
      {
        add("point_disp_order");
        add("machine_name");
        add("point_name");
      }
    };
    List<String> colList = new ArrayList<String>() {
      {
        add("inspection_date_str");
      }
    };
    List<String> valList = new ArrayList<String>() {
      {
        add("result");
      }
    };
    res = sysDataSetService.getMatrixDataList(res, rowList, colList, valList);

    // 出力情報を帳票デザインHTMLへ反映する
    reportOutputInfo = new HashMap<>();

    // 表示期間
    reportOutputInfo.put("C2:E2",
        dataKey.get(ReportConstant.ReportDataKey.DATE_FROM) + "から" + dataKey.get(ReportConstant.ReportDataKey.DATE_TO));

    if (!res.isEmpty()) {
      int row_pos = 5; // 装置名／調査箇所 は "B5:C5"／"D5"から"B6:C6"／"D6","B7:C7"／"D7"と続く
      boolean isFirstRow = true;

      // 行方向(各 装置名／調査箇所)にデータをループ
      for (Map<String, Object> resOne : res) {
        // 装置名を帳票にセット
        reportOutputInfo.put("B" + String.valueOf(row_pos) + ":C" + String.valueOf(row_pos),
            resOne.get("machine_name").toString());
        // 調査個所を帳票にセット
        reportOutputInfo.put("D" + String.valueOf(row_pos), resOne.get("point_name").toString());

        byte[] asciiCodes = null;
        // データ出力開始列の設定
        asciiCodes = "E".getBytes(StandardCharsets.US_ASCII);

        // 列方向(各 透析日＋クール)にデータをループ
        for (int i = 0; i < (int) resOne.get("field_count"); i++) {
          String idColString = null;
          idColString = new String(new byte[] { (byte) (asciiCodes[0] + i) }, StandardCharsets.US_ASCII);

          final String field_0 = "field_" + String.valueOf(i + 1);

          // 行ヘッダー系は初回の行の場合のみ処理
          if (true == isFirstRow) {
            // 検査日 行ヘッダー
            reportOutputInfo.put(idColString + "4",
                ((Map<String, String>) resOne.get(field_0 + "_col")).get("inspection_date_str"));
          }

          // 結果
          List<Map<String, String>> al = (List<Map<String, String>>) resOne.get(field_0);
          reportOutputInfo.put(idColString + String.valueOf(row_pos), ((Map<String, String>) al.get(0)).get("result"));
        }

        isFirstRow = false;
        row_pos++;
      }
    }

    // クラスパスから report/water-survey.html を読み込む
    String reportHtml = getInputStream("report/html/water-survey.html");

    Map<String, String> calcResult = new HashMap<>();
    Map<String, String> formatConditionInfo = new HashMap<>();
    Map<String, String> chartInfo = new HashMap<>();
    Map<String, String[]> resizeFontSizeInfo = new HashMap<>();
    //mod 2022-04-20 6009 パラメータの追加facilityCd 鄭 start
    return reflectReportHtml("",reportHtml, reportOutputInfo, calcResult, formatConditionInfo, chartInfo,
        resizeFontSizeInfo);
    //mod 2022-04-20 6009 パラメータの追加facilityCd 鄭 end
  }

