  private void setCellValueSyohou(Sheet st, String position, String value, String dataType, Optional<ReportXmlTmplRepeat> tmplRepeat) {
    // POIセルオブジェクトの取得(セル範囲の左上)
    Cell targetCell = ReportUtils.getFirstCellSyohou(st, position, tmplRepeat);

    // targetCellがnull以外、positionに「-」が含まれている場合
    if (targetCell != null && position.indexOf("-") != -1) {
      int index = position.indexOf(".");
      String positionold = position.substring(index + 1, position.length());
      // POIセルオブジェクトの取得
      Cell targetCellold = ReportUtils.getFirstCell(st, positionold);
      // セルスタイルをコピーする
      targetCell.setCellStyle(targetCellold.getCellStyle());
    }
    // セルに値を設定します
    setCellValue(targetCell, value, dataType);
  }
