  private void convertDataCodeToIdRepeatTmplSyohou(Map<String, String> result, List<Map<String, Object>> tmpList, ReportXmlParam param,
                                                   List doReportName, Integer groupIdListInTmplCount, int repeatTMax) {
    ReportXmlTmplRepeat tmplRepeat = param.getReportXmlTmplRepeat();
    if (!result.containsKey("Over")){
      Map<String, String> resultCheck = sortByKeyA(result);
      String checkS = "";
      for (String StrDoCheck : resultCheck.keySet()){
        int checkStr = StrDoCheck.lastIndexOf("-");
        if (checkStr >= 0){
          if ("".equals(checkS)){
            checkS = StrDoCheck.substring(0, checkStr);
          } else if (StrDoCheck.startsWith(checkS)){
            result.remove(StrDoCheck);
          } else {
            checkS = StrDoCheck.substring(0, checkStr);
          }
        }
      }
      result.put("Over", "~!~");
    }
    String doValue = "";
    int groupIndex = 1;
    int templateIndex = 0;
    int doCount = 0;
    for (int p = 0; p < tmpList.size(); p++) {
      // del #6346 処方の項目が足りない 王永吉 start
//      String keyDo = "";
      // del #6346 処方の項目が足りない 王永吉 end
      if (groupIdListInTmplCount > 1) {
        if (tmpList.get(p).containsKey("Rp")) {
          if ("".equals(doValue)) {
            doValue = tmpList.get(p).get("Rp").toString();
            groupIndex = 1;
            templateIndex = 1;
          } else if (doValue.equals(tmpList.get(p).get("Rp").toString())) {
            if (doReportName.contains(param.getDataCode())) {
              if (groupIndex == repeatTMax) {
                groupIndex = 1;
                templateIndex++;
              } else {
                groupIndex++;
              }
            } else {
              doCount++;
              // mod Aspose.cells関連問題三回目対応 鄭爽 start
              // if ((doCount % repeatTMax) == 0 && doCount > 0) {
              if (repeatTMax != 0 && (doCount % repeatTMax) == 0 && doCount > 0) {
                // mod Aspose.cells関連問題三回目対応 鄭爽 start
                groupIndex = 1;
                templateIndex++;
              } else {
                continue;
              }
            }
          } else {
            doValue = tmpList.get(p).get("Rp").toString();
            groupIndex = 1;
            doCount = 0;
            templateIndex++;
          }
        }
      } else {
        templateIndex++;
      }

      for (String doStr : tmpList.get(p).keySet()) {
        if (doStr.equals(param.getDataCode())) {
          String keyPage = String.format("%d%s", 1, MULTIPLE_PAGES_SEPARATOR);
          String keyTmpl = String.format("%s-%d", tmplRepeat.getId(), templateIndex);
          String keyParam = String.format("%s%s", param.getId(), StringUtils.isEmpty(param.getGroupId()) ? "" : "-" + groupIndex);
          String key = String.format("%s%s.%s", keyPage, keyTmpl, keyParam);
          String value = tmpList.get(p).get(doStr).toString();
          // del #6346 処方の項目が足りない 王永吉 start
//          if ("Rp".equals(param.getDataCode()) ||
//            "usage_detail".equals(param.getDataCode()) ||
//            "issue_name".equals(param.getDataCode())) {
//            int doIndexOne = key.indexOf("-");
//            int doIndexTwo = key.indexOf(".");
//            if (doIndexOne > 0 && doIndexTwo > 0 && doIndexTwo > doIndexOne) {
//              keyDo = key.substring(doIndexOne + 1, key.length());
//              resultDoCheck.put(keyDo, value);
//            }
//          }
          // del #6346 処方の項目が足りない 王永吉 end
          // mod 9951 縮小表示ONと表示文字列長が併存したとき、後者が機能するのはNG 吉 start
          // result.put(key, addLineBreak(value, param.getDispLength(), param.getDataType()));
          result.put(key, addLineBreak(value, param));
          // mod 9951 縮小表示ONと表示文字列長が併存したとき、後者が機能するのはNG 吉 end
        }
      }
    }
  }
