  /**
   * 列のスタイルをコピーする.
   *
   * @param workbook
   * @param fromStyle
   * @param toStyle
   * @param copyBorderFlg true：罫線のスタイルをコピーします / false：罫線のスタイルをコピーしません
   */
  private void copyCellStyle(Workbook workbook, CellStyle fromStyle, CellStyle toStyle, boolean copyBorderFlg) {
    toStyle.setAlignment(fromStyle.getAlignment());
    toStyle.setVerticalAlignment(fromStyle.getVerticalAlignment());

    if (copyBorderFlg) {
      toStyle.setBorderBottom(fromStyle.getBorderBottom());
      toStyle.setBorderLeft(fromStyle.getBorderLeft());
      toStyle.setBorderRight(fromStyle.getBorderRight());
      toStyle.setBorderTop(fromStyle.getBorderTop());
      toStyle.setTopBorderColor(fromStyle.getTopBorderColor());
      toStyle.setBottomBorderColor(fromStyle.getBottomBorderColor());
      toStyle.setRightBorderColor(fromStyle.getRightBorderColor());
      toStyle.setLeftBorderColor(fromStyle.getLeftBorderColor());
    }

    if(fromStyle instanceof XSSFCellStyle){
      XSSFCellStyle xssfToStyle = (XSSFCellStyle) toStyle;
      xssfToStyle.setFillBackgroundColor(((XSSFCellStyle) fromStyle).getFillBackgroundColorColor());
      xssfToStyle.setFillForegroundColor(((XSSFCellStyle) fromStyle).getFillForegroundColorColor());
    }else {
      toStyle.setFillBackgroundColor(fromStyle.getFillBackgroundColor());
      toStyle.setFillForegroundColor(fromStyle.getFillForegroundColor());
    }

    toStyle.setDataFormat(fromStyle.getDataFormat());
    toStyle.setFillPattern(fromStyle.getFillPattern());
    if (fromStyle instanceof HSSFCellStyle) {
      HSSFCellStyle style = (HSSFCellStyle) fromStyle;
      toStyle.setFont(style.getFont(workbook));
    } else if (fromStyle instanceof XSSFCellStyle) {
      XSSFCellStyle style = (XSSFCellStyle) fromStyle;
      toStyle.setFont(style.getFont());
    }

    toStyle.setHidden(fromStyle.getHidden());
    toStyle.setIndention(fromStyle.getIndention());
    toStyle.setLocked(fromStyle.getLocked());
    toStyle.setRotation(fromStyle.getRotation());
    toStyle.setWrapText(fromStyle.getWrapText());
    toStyle.setShrinkToFit(fromStyle.getShrinkToFit());
  }

  /**
   * 列の値をコピーする (セルのスタイルも合わせてコピーします).
   *
   * @param wb
   * @param srcCell
   * @param distCell
   * @param copyValueFlag true：セル値をコピーします
   * @param copyBorderFlg true：罫線のスタイルをコピーします / false：罫線のスタイルをコピーしません
   */
  // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
  // private void copyCell(Workbook wb, Cell srcCell, Cell distCell, boolean copyValueFlag, boolean copyBorderFlg) {
  private void copyCell(Workbook wb, Cell srcCell, Cell distCell, boolean copyValueFlag, boolean copyBorderFlg,String templAddress) {
    // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
    CellStyle newstyle= wb.createCellStyle();
    copyCellStyle(wb,srcCell.getCellStyle(), newstyle, copyBorderFlg);

    if (!copyBorderFlg) {
      // 罫線のコピーしなかった場合、newstyle は、罫線無しになっているので、コピー先のスタイルを上書きしないようにする
      newstyle.setBorderBottom(distCell.getCellStyle().getBorderBottom());
      newstyle.setBorderLeft(distCell.getCellStyle().getBorderLeft());
      newstyle.setBorderRight(distCell.getCellStyle().getBorderRight());
      newstyle.setBorderTop(distCell.getCellStyle().getBorderTop());
      newstyle.setTopBorderColor(distCell.getCellStyle().getTopBorderColor());
      newstyle.setBottomBorderColor(distCell.getCellStyle().getBottomBorderColor());
      newstyle.setRightBorderColor(distCell.getCellStyle().getRightBorderColor());
      newstyle.setLeftBorderColor(distCell.getCellStyle().getLeftBorderColor());
    }

    distCell.setCellStyle(newstyle);
    if (srcCell.getCellComment() != null) {
      distCell.setCellComment(srcCell.getCellComment());
    }

    CellType srcCellType = srcCell.getCellType();
    if (copyValueFlag) {
      if (srcCellType == CellType.NUMERIC) {
        if (DateUtil.isCellDateFormatted(srcCell)) {
          distCell.setCellValue(srcCell.getDateCellValue());
        } else {
          distCell.setCellValue(srcCell.getNumericCellValue());
        }
      } else if (srcCellType == CellType.STRING) {
        distCell.setCellValue(srcCell.getRichStringCellValue());
      }else if (srcCellType == CellType.BOOLEAN) {
        distCell.setCellValue(srcCell.getBooleanCellValue());
      } else if (srcCellType == CellType.ERROR) {
        distCell.setCellErrorValue(srcCell.getErrorCellValue());
      } else if (srcCellType == CellType.FORMULA) {
        // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
        // distCell.setCellFormula(srcCell.getCellFormula());
        String formula = ExcelCopyWithFormula.changeCell(srcCell,distCell,templAddress);
        distCell.setCellFormula(formula);
        // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
      }
    }
  }

  /**
   * keyを取得する.
   *
   * @param key key
   * @param repeatAddressMap ReplaceKeyMap
   */
  private String getReplaceKey(String key, Map<String, String> repeatAddressMap) {
    String replaceKey = null;
    String[] keyIds = key.split("\\.");
    String keyId = null;
    // add Aspose.cells関連問題対応 商 start
    keyId = keyIds[0];
    // add Aspose.cells関連問題対応 商 end
    if (keyIds.length == 2) {
      keyId = keyIds[1];
    }
    String[] cellAddrs = keyId.split("-");
    String cellAddress = null;
    String repeatAddress = null;
    Integer cellAddrIndex = 0;
    String tempKey = null;
    if (cellAddrs.length == 2) {
      cellAddress = cellAddrs[0];
      cellAddrIndex = Integer.valueOf(cellAddrs[1]);
      for (String cellAddressExcel : repeatAddressMap.keySet()) {
        if (cellAddress.equals(cellAddressExcel)) {
          String[] repeatAddrs = repeatAddressMap.get(cellAddressExcel).split(",");
          if (cellAddrIndex <= repeatAddrs.length) {
            repeatAddress = repeatAddrs[cellAddrIndex - 1];
            tempKey = key.replace(cellAddress,repeatAddress);
            String[] tempKeys = tempKey.split("-");
            if (tempKeys.length == 3) {
              replaceKey = tempKeys[0] + "-" + tempKeys[1];
              break;
            }
          }
        }
      }
    }
    return replaceKey;
  }

  /**
   * keyを取得する(テンプレート繰り返しではない通常の繰り返し処理のデータ割り当て先keyを応答する).
   *
   * @param key key
   * @param repeatAddressMap ReplaceKeyMap
   */
  private String getReplaceKeyforRepeat(String key, Map<String, String> repeatAddressMap) {
    String replaceKey = null;
    // key から、map の key と index を取得
    String indexKey = "";
    Integer cellAddrIndex = 0;
    // add Aspose.cells関連問題8の二回目対応 夏 start
    if(key.indexOf(".") >= 0){
      return replaceKey;
    }
    // add Aspose.cells関連問題8の二回目対応 夏 end
    if (key.indexOf("-") > -1) {
      String[] tmpStr = key.split("-");
      indexKey = tmpStr[0];
      cellAddrIndex = Integer.valueOf(tmpStr[1]) > 0 ? Integer.valueOf(tmpStr[1]) -1 : 0;
    } else {
      indexKey = key;
    }
    // key、index を元に、必要なキーを取得
    String str = repeatAddressMap.get(indexKey);
    //mod 7800 コンバートした施設で、帳票のグラフが表示されない 朴 start
    // if (str.indexOf(",") > -1) {
    if (str != null && str.indexOf(",") > -1) {
    //mod 7800 コンバートした施設で、帳票のグラフが表示されない 朴 end
      String[] repeatAddrs = str.split(",");
      //mod #9012【IES起票】スケジュール表にてテンプレートにシステムエラーが発生した liuc start
      //if (cellAddrIndex <= repeatAddrs.length) {
      if (cellAddrIndex < repeatAddrs.length) {
      //mod #9012【IES起票】スケジュール表にてテンプレートにシステムエラーが発生した liuc end
        replaceKey = repeatAddrs[cellAddrIndex];
        // add Aspose.cells関連問題8の対応 夏 start
      }else{
        int page = cellAddrIndex/repeatAddrs.length;
        //del #9012【IES起票】スケジュール表にてテンプレートにシステムエラーが発生した liuc start
//        if((cellAddrIndex % repeatAddrs.length) == 0){
//          page -=1;
//        }
        //del #9012【IES起票】スケジュール表にてテンプレートにシステムエラーが発生した liuc end
        replaceKey = repeatAddrs[cellAddrIndex - (repeatAddrs.length * page)];
        // add Aspose.cells関連問題8の対応 夏 end
      }
    }
    if (replaceKey == null) {
      // replace不要の場合
      replaceKey = key;
    }
    return replaceKey;
  }

  /**
   * 帳票 繰り返し処理 繰り返し先に縮小表示、結合状態をコピーする.
   *
   * @param st
   * @param srcKey "AG54-2"、"B54:E54-3" の様な文字列が入っている想定です
   * @param destKey "AG55"、"B56:E56" の様な文字列が入っている想定です
   */
  // mod Aspose.cells関連問題対応 商 start
  //private void copyStyleFromCells(Sheet st, String srcKey, String destKey) {
  private void copyStyleFromCells(Sheet st, String srcKey, String destKey, Integer reportClass) {
    // mod Aspose.cells関連問題対応 商 end
    if (StringUtils.isEmpty(srcKey) || StringUtils.isEmpty(destKey)) {
      // コピー元、コピー先どちらかが、空データだった場合は、何もせずに処理を抜ける
      return;
    }

    Workbook wb = st.getWorkbook();
    String shapingSrcKey = "";
    if (srcKey.contains("-")) {
      shapingSrcKey = srcKey.substring(0, srcKey.indexOf("-"));
    } else {
      shapingSrcKey = srcKey;
    }
    String shapingDestKey = "";
    if (destKey.contains("-")) {
      shapingDestKey = destKey.substring(0, destKey.indexOf("-"));
    } else {
      shapingDestKey = destKey;
    }
    if (shapingSrcKey.equals(shapingDestKey)) {
      // コピー元、コピー先が同じ場合、スタイルのコピーは不要なので処理を抜ける
      return;
    }

    if (shapingSrcKey.contains(":")) {
      // 結合セルだった場合、結合の範囲内で一式スタイルのコピーを行い、最後に結合処理を行う
      String[] srcKeyList = shapingSrcKey.split(":");
      String[] destKeyList = shapingDestKey.split(":");
      // shapingSrcKeyの開始行
      int tmplRowFrom = getRowCount(srcKeyList[0]) - 1;
      // shapingSrcKeyの開始Column
      int tmplColFrom = getColumnCount(srcKeyList[0]) - 1;
      // shapingSrcKeyの終了行
      int tmplRowTo = getRowCount(srcKeyList[1]) - 1;
      // shapingSrcKeyの終了Column
      int tmplColTo = getColumnCount(srcKeyList[1]) - 1;
      // shapingDestKeyの開始行
      int destRowFrom = getRowCount(destKeyList[0]) - 1;
      // shapingDestKeyの開始Column
      int destColFrom = getColumnCount(destKeyList[0]) - 1;
      // shapingDestKeyの終了行
      int destRowTo = getRowCount(destKeyList[1]) - 1;
      // shapingDestKeyの終了Column
      int destColTo = getColumnCount(destKeyList[1]) - 1;
      // コピー元(行)
      Row srcRow = null;
      // コピー元(コラム)
      Cell srcCell = null;
      // コピー先(行)
      Row destRow = null;
      // コピー先(コラム)
      Cell destCell = null;

      // style のコピー
      for (int i = tmplRowFrom; i< tmplRowTo; i++) {
        for (int j = tmplColFrom; j < tmplColTo; j++) {
          // コピー元Cellを取得
          if (st.getRow(i) == null) {
            srcRow = st.createRow(i);
          } else {
            srcRow = st.getRow(i);
          }
          if (srcRow.getCell(j) == null) {
            srcCell = srcRow.createCell(j);
          } else {
            srcCell = srcRow.getCell(j);
          }
          // コピー先Cellを取得
          if (st.getRow(destRowFrom + ( i - tmplRowFrom)) == null) {
            destRow = st.createRow(destRowFrom + ( i - tmplRowFrom));
          } else {
            destRow = st.getRow(destRowFrom + ( i - tmplRowFrom));
          }
          if (destRow.getCell(destColFrom + ( j - tmplColFrom)) == null) {
            destCell = destRow.createCell((destColFrom + ( j - tmplColFrom)));
          } else {
            destCell = destRow.getCell((destColFrom + ( j - tmplColFrom)));
          }
          // style のコピーを実施
          CellStyle newstyle= wb.createCellStyle();
          copyCellStyle(wb, srcCell.getCellStyle(), newstyle, false);
          destCell.setCellStyle(newstyle);
          if (srcCell.getCellComment() != null) {
            destCell.setCellComment(srcCell.getCellComment());
          }
        }
      }

      // 結合処理
      try {
        CellRangeAddress newRegion = new CellRangeAddress(destRowFrom, destRowTo, destColFrom, destColTo);
        st.addMergedRegion(newRegion);
      } catch (Exception e) {
        // 結合先が結合状態の場合、エラーになるので、処理をスキップする
      }
    } else {
      // 単体セルだった場、スタイルのコピーのみ実施
      CellStyle newstyle= wb.createCellStyle();
      // shapingSrcKeyの開始行
      int tmplRowFrom = getRowCount(shapingSrcKey) - 1;
      // shapingSrcKeyの開始Column
      int tmplColFrom = getColumnCount(shapingSrcKey) - 1;
      // shapingSrcKeyの終了行
      int tmplRowTo = getRowCount(shapingDestKey) - 1;
      // shapingSrcKeyの終了Column
      int tmplColTo = getColumnCount(shapingDestKey) - 1;
      // コピー元(行)
      Row srcRow = null;
      // コピー元(コラム)
      Cell srcCell = null;
      // コピー先(行)
      Row destRow = null;
      // コピー先(コラム)
      Cell destCell = null;

      // コピー元Cellを取得
      if (st.getRow(tmplRowFrom) == null) {
        srcRow = st.createRow(tmplRowFrom);
      } else {
        srcRow = st.getRow(tmplRowFrom);
      }
      if (srcRow.getCell(tmplColFrom) == null) {
        srcCell = srcRow.createCell(tmplColFrom);
      } else {
        srcCell = srcRow.getCell(tmplColFrom);
      }
      // コピー先Cellを取得
      if (st.getRow(tmplRowTo) == null) {
        destRow = st.createRow(tmplRowTo);
      } else {
        destRow = st.getRow(tmplRowTo);
      }
      if (destRow.getCell(tmplColTo) == null) {
        destCell = destRow.createCell(tmplColTo);
      } else {
        destCell = destRow.getCell(tmplColTo);
      }
      // style のコピーを実施
      // mod Aspose.cells関連問題対応 商 start
      //copyCellStyle(wb, srcCell.getCellStyle(), newstyle, true);
      if (reportClass == ReportConstant.ReportClass.ONE_TOTAL_REPORT) {
        copyCellStyle(wb, srcCell.getCellStyle(), newstyle, false);
        // add #9816 テンプレート設定に関する処理がデザイナと帳票生成時で重複している 高 start
        newstyle.setBorderBottom(destCell.getCellStyle().getBorderBottom());
        newstyle.setBorderLeft(destCell.getCellStyle().getBorderLeft());
        newstyle.setBorderRight(destCell.getCellStyle().getBorderRight());
        newstyle.setBorderTop(destCell.getCellStyle().getBorderTop());
        newstyle.setTopBorderColor(destCell.getCellStyle().getTopBorderColor());
        newstyle.setBottomBorderColor(destCell.getCellStyle().getBottomBorderColor());
        newstyle.setRightBorderColor(destCell.getCellStyle().getRightBorderColor());
        newstyle.setLeftBorderColor(destCell.getCellStyle().getLeftBorderColor());
        // add #9816 テンプレート設定に関する処理がデザイナと帳票生成時で重複している 高 end
      } else {
        copyCellStyle(wb, srcCell.getCellStyle(), newstyle, true);
        // 罫線のコピーしなかった場合、newstyle は、罫線無しになっているので、コピー先のスタイルを上書きしないようにする
        newstyle.setBorderBottom(destCell.getCellStyle().getBorderBottom());
        newstyle.setBorderLeft(destCell.getCellStyle().getBorderLeft());
        newstyle.setBorderRight(destCell.getCellStyle().getBorderRight());
        newstyle.setBorderTop(destCell.getCellStyle().getBorderTop());
        newstyle.setTopBorderColor(destCell.getCellStyle().getTopBorderColor());
        newstyle.setBottomBorderColor(destCell.getCellStyle().getBottomBorderColor());
        newstyle.setRightBorderColor(destCell.getCellStyle().getRightBorderColor());
        newstyle.setLeftBorderColor(destCell.getCellStyle().getLeftBorderColor());
      }
      // mod Aspose.cells関連問題対応 商 end
      destCell.setCellStyle(newstyle);
      if (srcCell.getCellComment() != null) {
        destCell.setCellComment(srcCell.getCellComment());
      }
    }
  }

  /**
   * 帳票の縮小表示を設定する.
   *
   * @param st
   * @param repeatAddressMap
   * @param params
   */
  private void setShrinkToFit(Sheet st, Map<String, String> repeatAddressMap, List<ReportXmlParam> params) {
    for (int index = 0; index < params.size(); index++) {
      String key = params.get(index).getId();
      for (String cellAddressExcel : repeatAddressMap.keySet()) {
        if (key.equals(cellAddressExcel)) {
          String[] repeatAddrs = repeatAddressMap.get(cellAddressExcel).split(",");
          if (repeatAddrs.length > 1) {
            for (int i = 1; i < repeatAddrs.length; i++) {
              copyShrinkToFit(st, repeatAddrs[0], repeatAddrs[i]);
            }
          }
        }
      }
    }
  }

  /**
   * 帳票の縮小表示をコピーする.
   *
   * @param st
   * @param srcKey
   * @param destKey
   */
  private void copyShrinkToFit(Sheet st, String srcKey, String destKey) {
    String[] srcKeys;
    String[] destKeys;
    int srcRowFrom = 0;
    int srcRowTo = 0;
    int srcColFrom = 0;
    int srcColTo = 0;
    int destRowFrom = 0;
    int destRowTo = 0;
    int destColFrom = 0;
    int destColTo = 0;

    if (srcKey.contains(":")) {
      srcKeys = srcKey.split(":");
      if (srcKeys.length == 2) {
        srcRowFrom = getRowCount(srcKeys[0]);
        srcRowTo = getRowCount(srcKeys[1]);

        srcColFrom = getColumnCount(srcKeys[0]);
        srcColTo = getColumnCount(srcKeys[1]);
      }
      // del Aspose.cells関連問題対応 鄭爽 start
//      destKeys = destKey.split(":");
//      if (destKeys.length == 2) {
//        destRowFrom = getRowCount(destKeys[0]);
//        destRowTo = getRowCount(destKeys[1]);
//
//        destColFrom = getColumnCount(destKeys[0]);
//        destColTo = getColumnCount(destKeys[1]);
//      }
      // del Aspose.cells関連問題対応 鄭爽 end
    } else {
      srcRowFrom = getRowCount(srcKey);
      srcRowTo = srcRowFrom;

      srcColFrom = getColumnCount(srcKey);
      srcColTo = srcColFrom;
      // del Aspose.cells関連問題対応 鄭爽 start
//      destRowFrom = getRowCount(destKey);
//      destRowTo = destRowFrom;
//
//      destColFrom = getColumnCount(destKey);
//      destColTo = destColFrom;
      // del Aspose.cells関連問題対応 鄭爽 end
    }
    // add Aspose.cells関連問題対応 鄭爽 start
    // 結合セルを含む
    if (destKey.contains(":")) {
      destKeys = destKey.split(":");
      if (destKeys.length == 2) {
        destRowFrom = getRowCount(destKeys[0]);
        destRowTo = getRowCount(destKeys[1]);

        destColFrom = getColumnCount(destKeys[0]);
        destColTo = getColumnCount(destKeys[1]);
      }
    } else {
      // 結合セルを含まない
      destRowFrom = getRowCount(destKey);
      destRowTo = destRowFrom;

      destColFrom = getColumnCount(destKey);
      destColTo = destColFrom;
    }
    // セルが等しい場合
    if (((srcRowTo - srcRowFrom) == (destRowTo - destRowFrom)) && ((srcColTo - srcColFrom) == (destColTo - destColFrom))) {
      // add Aspose.cells関連問題対応 鄭爽 end
      Row srcRow = null;
      Cell srcCell = null;
      Row destRow = null;
      Cell destCell = null;
      List<Cell> srcCellList = new ArrayList<>();
      List<Cell> destCellList = new ArrayList<>();

      for (int i = srcRowFrom - 1; i< srcRowTo; i++) {
        for (int j = srcColFrom - 1; j < srcColTo; j++) {
          if (st.getRow(i) == null) {
            srcRow = st.createRow(i);
          } else {
            srcRow = st.getRow(i);
          }
          if (srcRow.getCell(j) == null) {
            srcCell = srcRow.createCell(j);
          } else {
            srcCell = srcRow.getCell(j);
          }
          srcCellList.add(srcCell);
        }
      }
      for (int i = destRowFrom - 1; i< destRowTo; i++) {
        for (int j = destColFrom - 1; j < destColTo; j++) {
          if (st.getRow(i) == null) {
            destRow = st.createRow(i);
          } else {
            destRow = st.getRow(i);
          }
          if (destRow.getCell(j) == null) {
            destCell = destRow.createCell(j);
          } else {
            destCell = destRow.getCell(j);
          }
          destCellList.add(destCell);
        }
      }
      if (srcCellList.size() == destCellList.size()) {
        for (int i = 0; i < srcCellList.size(); i++) {
          destCellList.get(i).getCellStyle().setShrinkToFit(srcCellList.get(i).getCellStyle().getShrinkToFit());
        }
      }
      // add Aspose.cells関連問題対応 鄭爽 start
    }
    // add Aspose.cells関連問題対応 鄭爽 end
  }

  /**
   * tmplRepeatのコラム数を取得する.
   *
   * @param idFT id属性
   */
  private int getColumnCount(String idFT) {
    int column = 0;
    char[]c = idFT.toUpperCase().toCharArray();
    int index = 0;
    while (index < c.length) {
      if (c[index] < 'A' || c[index] > 'Z') {
        break;
      }
      column = column * 26 + (c[index] - 'A' + 1);
      index++;
    }
    return column;
  }

  /**
   * tmplRepeatの行数を取得する.
   *
   * @param idFT id属性
   */
  private int getRowCount(String idFT) {
    int row = 0;
    char[]c = idFT.toUpperCase().toCharArray();
    int index = 0;
    int count = 0;
    while (index < c.length) {
      if (c[index] < 'A' || c[index] > 'Z') {
        break;
      } else {
        count++;
      }
      index++;
    }
    row = Integer.valueOf(idFT.substring(count, idFT.length()));
    return row;
  }

  /**
   * テンプレート繰り返し：繰り返し元のスタイル、結合状態をデータの数だけコピーする.
   *
   * @param st
   * @param wb
   * @param tmplRepeat
   */
  // mod #7958 PDFとEXCELのファイル出力の内容が異なる 内部指摘対応 鄭爽 start
  // private void copyFixedValue(Sheet st, Workbook wb, Optional<ReportXmlTmplRepeat> tmplRepeat) {
  // mod by shangkuiwei 2023-02-05 [Variable,CodeOptimization] --start
  // private void copyFixedValue(Sheet st, Workbook wb, Optional<ReportXmlTmplRepeat> tmplRepeat, Integer page) {
  private void copyFixedValue(Sheet st, Workbook wb, Optional<ReportXmlTmplRepeat> tmplRepeat, Integer page, Map<String, Object> dataKey) {
    // mod by shangkuiwei 2023-02-05 [Variable,CodeOptimization] --end
    // mod #7958 PDFとEXCELのファイル出力の内容が異なる 内部指摘対応 鄭爽 end
    String[] idFT = tmplRepeat.get().getId().split(":");
    if(idFT.length==2) {
      // tmplRepeatの開始コラム
      int tmplColFrom = 0;
      // tmplRepeatの終了コラム
      int tmplColTo = 0;
      // tmplRepeatのコラム数
      int tmplColCount = 0;
      // tmplRepeatの開始行
      int tmplRowFrom = 0;
      // tmplRepeatの終了行
      int tmplRowTo = 0;
      // tmplRepeatの行数
      int tmplRowCount = 0;

      // 繰返回数(縦)
      int repeatCount_V = tmplRepeat.get().getRepeatCountV();
      // 繰返回数(横)
      int repeatCount_H = tmplRepeat.get().getRepeatCountH();
      // 余白(縦)
      int marginV = tmplRepeat.get().getMarginV();
      // 余白(横)
      int marginH = tmplRepeat.get().getMarginH();
      // add #7958 PDFとEXCELのファイル出力の内容が異なる 内部指摘対応 鄭爽 start
      int repeatMax = tmplRepeat.get().getRepeatMax();
      // add #7958 PDFとEXCELのファイル出力の内容が異なる 内部指摘対応 鄭爽 end
      tmplRowFrom = getRowCount(idFT[0]);
      tmplRowTo = getRowCount(idFT[1]);
      tmplRowCount = tmplRowTo - tmplRowFrom + 1;

      tmplColFrom = getColumnCount(idFT[0]);
      tmplColTo = getColumnCount(idFT[1]);
      tmplColCount = tmplColTo - tmplColFrom + 1;

      // コピー元(行)
      Row srcRow = null;
      // コピー元(コラム)
      Cell srcCell = null;
      // コピー先(行)
      Row destRow = null;
      // コピー先(コラム)
      Cell destCell = null;

      // add by shangkuiwei 2023-02-05 [Variable,CodeOptimization] --start
      List<Long> patId = (List<Long>) dataKey.get("patIds");
      int multipleOutputCount = patId.size();
      // add by shangkuiwei 2023-02-05 [Variable,CodeOptimization] --end

      // style のコピー
      // add bug#6772 プレビュー表示、ファイル出力が遅い 最適化:循環変数を抽出します。1 liuc start
      int i = tmplRowFrom - 1;
      int j = tmplColFrom - 1;
      for (; i< tmplRowTo; i++) {
        for (; j < tmplColTo; j++) {
          if (st.getRow(i) == null) {
            srcRow = st.createRow(i);
          } else {
            srcRow = st.getRow(i);
          }
          if (srcRow.getCell(j) == null) {
            srcCell = srcRow.createCell(j);
          } else {
            srcCell = srcRow.getCell(j);
          }
          // add #7958 PDFとEXCELのファイル出力の内容が異なる 内部指摘対応 鄭爽 start
          int dataCount = 0;
          if (ReportXmlTmplRepeat.DIRECTION_Z.equals(String.valueOf(tmplRepeat.get().getDirection()))) {
            // Z方向
            // add bug#6772 プレビュー表示、ファイル出力が遅い 最適化:循環変数を抽出します。2 liuc
            int vCount = 1;
            int hCount = 1;
            flgStyleCopyZ :
            for (; vCount <= repeatCount_V; vCount ++) {
              for (; hCount <= repeatCount_H; hCount ++) {
                dataCount = dataCount + 1;
                if (dataCount > multipleOutputCount - (repeatMax * page)) {
                  break flgStyleCopyZ; // ラベル：flgStyleCopyZ の付いたforループ全体を抜ける
                }
                if (hCount == 1 && vCount == 1) {
                  continue;
                }
                if (st.getRow(i + (tmplRowCount + marginV) * (vCount -1)) == null) {
                  destRow = st.createRow(i + (tmplRowCount + marginV) * (vCount - 1));
                } else {
                  destRow = st.getRow(i + (tmplRowCount + marginV) * (vCount - 1));
                }
                destCell = destRow.createCell(j+ (tmplColCount + marginH) * (hCount - 1));
                // 帳票のCellをコピー
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
                // copyCell(wb, srcCell, destCell, true, true);
                copyCell(wb, srcCell, destCell, true, true,tmplRepeat.get().getId());
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
              }
            }
          } else {
            // N方向
            // add bug#6772 プレビュー表示、ファイル出力が遅い 最適化:循環変数を抽出します。3 liuc
            int hCount = 1;
            int vCount = 1;
            flgStyleCopyN :
            for (; hCount <= repeatCount_H; hCount ++) {
              for (; vCount <= repeatCount_V; vCount ++) {
                dataCount = dataCount + 1;
                if (dataCount > multipleOutputCount - (repeatMax * page)) {
                  break flgStyleCopyN; // ラベル：flgStyleCopyN の付いたforループ全体を抜ける
                }
                if (hCount == 1 && vCount == 1) {
                  continue;
                }
                if (st.getRow(i + (tmplRowCount + marginV) * (vCount -1)) == null) {
                  destRow = st.createRow(i + (tmplRowCount + marginV) * (vCount - 1));
                } else {
                  destRow = st.getRow(i + (tmplRowCount + marginV) * (vCount - 1));
                }
                destCell = destRow.createCell(j+ (tmplColCount + marginH) * (hCount - 1));
                // 帳票のCellをコピー
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
                // copyCell(wb, srcCell, destCell, true, true);
                copyCell(wb, srcCell, destCell, true, true,tmplRepeat.get().getId());
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
              }
            }
          }
        }
      }

      // 結合状態のコピー
      int mergedCount = st.getNumMergedRegions(); //
      // add bug#6772 プレビュー表示、ファイル出力が遅い 最適化:循環変数を抽出します。4 liuc end
      i = 0;
      for(; i < mergedCount; i++) {
        // 結合されたセルを取得
        CellRangeAddress region = st.getMergedRegion(i);
        // コピー元範囲内の結合セルだった場合、処理を実施 (getメソッドでのRow/Column数取得は0スタートの為、比較値を-1しておく)
        if (tmplRowFrom - 1 <= region.getFirstRow()
            && tmplColFrom - 1 <= region.getFirstColumn()
            && tmplRowTo - 1 >= region.getLastRow()
            && tmplColTo - 1 >= region.getLastColumn()) {
          int mgDataCount = 0;
          if (ReportXmlTmplRepeat.DIRECTION_Z.equals(String.valueOf(tmplRepeat.get().getDirection()))) {
            // Z方向
            flgMergedCopyZ :
            for (int mgVCount = 1; mgVCount <= repeatCount_V; mgVCount++) {
              for (int mgHCount = 1; mgHCount <= repeatCount_H; mgHCount++) {
                mgDataCount = mgDataCount + 1;
                if (mgDataCount > multipleOutputCount - (repeatMax * page)) {
                  break flgMergedCopyZ; // ラベル：flgMergedCopyZ の付いたforループ全体を抜ける
                }
                if (mgHCount == 1 && mgVCount == 1) { // 1つめはコピー元なので処理不要
                  continue;
                }
                try {
                  CellRangeAddress newRegion = region.copy();
                  newRegion.setFirstRow(region.getFirstRow() + ((tmplRowCount + marginV) * (mgVCount - 1))); // (コピー元縦幅 + 余白縦) * 縦の件数
                  newRegion.setLastRow(region.getLastRow() + ((tmplRowCount + marginV) * (mgVCount - 1)));
                  newRegion.setFirstColumn(region.getFirstColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  newRegion.setLastColumn(region.getLastColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  st.addMergedRegion(newRegion);
                } catch (Exception e) {
                  // 結合先が結合状態の場合、エラーになるので、処理をスキップする
                }
              }
            }
          } else {
            // N方向
            flgMergedCopyN :
            for (int mgHCount = 1; mgHCount <= repeatCount_H; mgHCount++) {
              for (int mgVCount = 1; mgVCount <= repeatCount_V; mgVCount++) {
                mgDataCount = mgDataCount + 1;
                if (mgDataCount > multipleOutputCount - (repeatMax * page)) {
                  break flgMergedCopyN; // ラベル：flgMergedCopyN の付いたforループ全体を抜ける
                }
                if (mgHCount == 1 && mgVCount == 1) { // 1つめはコピー元なので処理不要
                  continue;
                }
                try {
                  CellRangeAddress newRegion = region.copy();
                  newRegion.setFirstRow(region.getFirstRow() + ((tmplRowCount + marginV) * (mgVCount - 1))); // (コピー元縦幅 + 余白縦) * 縦の件数
                  newRegion.setLastRow(region.getLastRow() + ((tmplRowCount + marginV) * (mgVCount - 1)));
                  newRegion.setFirstColumn(region.getFirstColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  newRegion.setLastColumn(region.getLastColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  st.addMergedRegion(newRegion);
                } catch (Exception e) {
                  // 結合先が結合状態の場合、エラーになるので、処理をスキップする
                }
              }
            }
          }
        }
      }
    }
  }
