  /**
   * ラベル帳票出力情報を帳票デザインHTMLへ反映します.
   *
   * @param reportHtml 帳票デザインHTML
   * @param reportOutputInfo 帳票出力情報
   * @return 反映後の帳票デザインHTML
   */
  private String reflectReportHtmlForLabel(String reportHtml, Map<String, String> reportOutputInfo) {
    org.jsoup.nodes.Document document = Jsoup.parse(reportHtml);
    // [td]元素を取得
    Elements elements = document.select("td");
    // mod #7880 帳票：ラベルが正しく表示されない 内部指摘対応 商 start
    //for (org.jsoup.nodes.Element element : elements) {
    //if (element.attr("id") != "") {
    //boolean equalFlg = false;

    //for (String reportKey : reportOutputInfo.keySet()) {
    //if(reportKey.contains(MULTIPLE_PAGES_SEPARATOR)){
    //String [] reportKeys = reportKey.split(MULTIPLE_PAGES_SEPARATOR);
    //if (reportKeys.length == 2) {
    //if (element.attr("id").equals(reportKeys[1])) {
    //equalFlg = true;
    //break;
    //}
    //}
    //}
    //}

    //if (equalFlg == false) {
    // スタイルを削除
    //element.removeAttr("class");
    //element.removeAttr("style");
    //}
    //}
    //}
    Map<String,Integer> htmlIdCountMap = new HashMap<>();
    for (org.jsoup.nodes.Element element : elements) {
      String htmlId = element.attr("id");
      if (htmlId != "") {
        boolean equalFlg = false;
        if (htmlIdCountMap.containsKey(htmlId)) {
          htmlIdCountMap.put(htmlId, htmlIdCountMap.get(htmlId) + 1);
        } else {
          htmlIdCountMap.put(htmlId, 1);
        }
        String newHtmlId = htmlIdCountMap.get(htmlId) + "#" + htmlId;
        for (String reportKey : reportOutputInfo.keySet()) {
          if(reportKey.contains(MULTIPLE_PAGES_SEPARATOR)) {
            if (newHtmlId.equals(reportKey)) {
              equalFlg = true;
              break;
            }
          }
        }
        if (equalFlg == false) {
          // スタイルを削除
          element.removeAttr("class");
          element.removeAttr("style");
        }
      }
    }
    // mod #7880 帳票：ラベルが正しく表示されない 内部指摘対応 商 end
    return document.html();
  }
