  /**
   * セルマージのセル数を取得
   *
   * @param st
   * @param rowIndex
   * @param columnIndex
   */
  private int getCellCount(Sheet st, Integer rowIndex, Integer columnIndex) {
    // セルマージ数
    int mergedCount = st.getNumMergedRegions();
    int firstRow = 0;
    int lastRow = 0;
    int firstColumn = 0;
    int lastColumn = 0;
    int cellCount = 1;
    for(int i = 0; i < mergedCount; i++) {
      CellRangeAddress region = st.getMergedRegion(i);
      firstRow = region.getFirstRow();
      lastRow = region.getLastRow();
      firstColumn = region.getFirstColumn();
      lastColumn = region.getLastColumn();
      if (rowIndex >= firstRow && rowIndex <= lastRow) {
        if (columnIndex >= firstColumn && columnIndex <= lastColumn) {
          cellCount = lastColumn - firstColumn + 1;
          break;
        }
      }
    }
    return cellCount;
  }

  /**
   * HTMLのIDとWidthを取得します.
   *
   * @param mstReport 帳票マスタEntity
   * @param reportZipFile 帳票Zipファイル
   * @return idWidthMap
   */
  private Map<String, String> getIdAndWidth(MstReport mstReport, ReportZipFile reportZipFile) {
    Workbook wb1 = getReportWorkbook(mstReport, reportZipFile);
    Sheet st1 = wb1.getSheetAt(wb1.getActiveSheetIndex());
    Map<String, Integer> nameMap = new HashMap<>();
    Map<String, String> idWidthMap = new HashMap<>();
    for (int rowIndex = 0; rowIndex <= st1.getLastRowNum(); rowIndex++) {
      Row row = st1.getRow(rowIndex);
      if (row == null) {
        continue;
      }
      for (int columnIndex = 0; columnIndex < row.getLastCellNum(); columnIndex++) {
        Cell cell = row.getCell(columnIndex);
        if (cell != null) {
          // mod #7943 帳票レイアウトデザイナーが正しく動作しないの⑪㉒対応 夏 start
//          String cellValue = cell.getStringCellValue();
          String cellValue = "";
          if(cell.getCellType()==CellType.STRING)
            cellValue = cell.getStringCellValue();
          else if(cell.getCellType()==CellType.NUMERIC)
            cellValue = String.valueOf(cell.getNumericCellValue());
          // mod #7943 帳票レイアウトデザイナーが正しく動作しないの⑪㉒対応 夏 end
          if (!StringUtils.isEmpty(cellValue) && !cellValue.startsWith("##")) {
            if (cell.getCellStyle().getShrinkToFit() == true) {
              if (nameMap.containsKey(cellValue)) {
                nameMap.put(cellValue, nameMap.get(cellValue) + 1);
              } else {
                nameMap.put(cellValue, 1);
              }

              int cellCount = 0;
              double colWidth = 0;
              int fontIndex = 0;
              double fontSize = 0;

              cellCount = this.getCellCount(st1, rowIndex, columnIndex);
              if (cellCount > 0) {
                colWidth = (double)st1.getColumnWidth(columnIndex) / 256 * 6 * cellCount;
              }

              fontIndex = cell.getCellStyle().getFontIndexAsInt();
              if (fontIndex > 0) {
                fontSize = wb1.getFontAt(fontIndex).getFontHeightInPoints();
              }

              String colWidthStr = colWidth + "&&" + fontSize;
              String id = String.format("%d%s", nameMap.get(cellValue), MULTIPLE_PAGES_SEPARATOR) + cellValue;
              idWidthMap.put(id, colWidthStr);
            }
          }
        }
      }
    }
    return idWidthMap;
  }

  /**
   * IDを帳票デザインHTMLへ反映します.
   *
   * @param reportHtml 帳票デザインHTML
   * @return 反映後の帳票デザインHTML
   */
  private String addIdForHtml(String reportHtml) {
    org.jsoup.nodes.Document document = Jsoup.parse(reportHtml);
    Elements elements = document.select("td");
    List<String> nameList = new ArrayList<>();
    for (org.jsoup.nodes.Element element : elements) {
      if (!StringUtils.isEmpty(element.text())) {
        String tdName = element.text();
        nameList.add(tdName);
        Long nameCount = nameList.stream().filter(item -> item.equals(tdName)).count();
        element.attr("id", String.format("%d%s", nameCount, MULTIPLE_PAGES_SEPARATOR) + tdName);
      }
    }
    return document.html();
  }

  /**
   * 縮小表示を適用するidとscaleのMapを追加する.
   * @param reportHtml
   * @param idWidthMap
   * @return
   */
  private Map<String, String[]> addResizeFontSizeInfo(String reportHtml, Map<String, String> idWidthMap) {
    Map<String, String[]> resizeFontSizeInfoForDialysis = new HashMap<>();

    for (String key : idWidthMap.keySet()) {
      // 縮小率を算出する
      String[] widths = idWidthMap.get(key).split("&&");
      Double colWidth = Double.valueOf(widths[0]);
      Double fontSize = Double.valueOf(widths[1]);

      // 縮小率算出
      List<Object[]> charInfos = getCharInfos(key);
      Integer outPutInfoCount = charInfos.stream().mapToInt(v -> Integer.valueOf(v[0].toString())).sum();
      if(fontSize > 0 && outPutInfoCount > 0) {
        // 文字カウント
        Double wordCount = colWidth / (fontSize * 0.5);
        // スケールを算出する
        Double scale = wordCount / outPutInfoCount;
        // 倍率補正（0.1以下用）
        Double correctScale = null;
        // スケールが0.1以下の場合は0.1とする
        if(scale < 0.1) {
          // 補正倍率を保持
          correctScale = 0.1 / scale;
          scale = 0.1;
        }
        //スケールが1未満の場合は縮小率Mapにputする
        if(scale < 1) {
          // 文字数列幅（0.1以下は補正しているため、colWidth/scaleとはしない）
          Double colWidthByWordCount = outPutInfoCount * fontSize * 0.75;
          // 文字列幅の半分
          Double halfColWidthByWordCount = colWidthByWordCount / 2;
          // 補正倍率がある場合は文字列幅を補正する
          if(correctScale != null) {
            halfColWidthByWordCount = halfColWidthByWordCount / correctScale;
          }
          // 0: scale, 1:translate
          String[] scaleInfo = {
            String.format("%.2f", scale),
            String.format("%.2f", (halfColWidthByWordCount * scale) - halfColWidthByWordCount)
          };
          resizeFontSizeInfoForDialysis.put(key, scaleInfo);
        }
      }
    }
    return resizeFontSizeInfoForDialysis;
  }

  /**
   * 縮小表示を帳票デザインHTMLへ反映します.
   *
   * @param reportHtml 帳票デザインHTML
   * @param resizeFontSizeInfo 縮小表示情報
   * @return 反映後の帳票デザインHTML
   */
  private String addShrinkForDialysis(String reportHtml, Map<String, String[]> resizeFontSizeInfo) {
    // 帳票デザインHTMLをパースする
    org.jsoup.nodes.Document document = Jsoup.parse(reportHtml);
    org.jsoup.nodes.Element baseElement = document.getElementsByTag("body").first();

    // 帳票デザインHTMLへ縮小表示を反映する（全ページ）
    resizeFontSizeInfo.entrySet().stream()
      .forEach(f -> {
        org.jsoup.nodes.Element element = baseElement.getElementById(f.getKey());
        ReportUtils.appendTagFontSizeScale(element, f.getValue()[0],f.getValue()[1]);
      });

    return document.html();
  }
