  /**
   * 帳票のセルマージ.
   *
   * @param st
   * @param tmplRepeat
   */
  private void reportMergedRegionForOnePatient(Sheet st, Optional<ReportXmlTmplRepeat> tmplRepeat) {
    String[] idFT = tmplRepeat.get().getId().split(":");
    if(idFT.length==2) {
      // tmplRepeatの開始コラム
      int tmplColFrom = 0;
      // tmplRepeatの終了コラム
      int tmplColTo = 0;
      // tmplRepeatのコラム数
      int tmplColCount = 0;
      // tmplRepeatの開始行
      int tmplRowFrom = 0;
      // tmplRepeatの終了行
      int tmplRowTo = 0;
      // tmplRepeatの行数
      int tmplRowCount = 0;

      tmplColFrom = getColumnCount(idFT[0]);
      tmplColTo = getColumnCount(idFT[1]);
      tmplColCount = tmplColTo - tmplColFrom + 1;

      tmplRowFrom = getRowCount(idFT[0]);
      tmplRowTo = getRowCount(idFT[1]);
      tmplRowCount = tmplRowTo - tmplRowFrom + 1;

      // セルマージ数
      int mergedCount = st.getNumMergedRegions();
      int targetFirstRow = 0;
      int targetLastRow = 0;
      int targetFirstColumn = 0;
      int targetLastColumn = 0;
      // 繰返回数(縦)
      int repeatCount_V = tmplRepeat.get().getRepeatCountV();
      // 繰返回数(横)
      int repeatCount_H = tmplRepeat.get().getRepeatCountH();
      // 余白(縦)
      int marginV = tmplRepeat.get().getMarginV();
      // 余白(横)
      int marginH = tmplRepeat.get().getMarginH();
      for(int i = 0; i < mergedCount; i++) {
        CellRangeAddress region = st.getMergedRegion(i);
        targetFirstRow = region.getFirstRow();
        targetLastRow = region.getLastRow();
        targetFirstColumn = region.getFirstColumn();
        targetLastColumn = region.getLastColumn();
        Cell oldCell = st.getRow(targetFirstRow).getCell(targetFirstColumn);
        for (int vCount = 1; vCount <= repeatCount_V; vCount ++) {
          for (int hCount = 1; hCount <= repeatCount_H; hCount ++) {
            if (hCount == 1 && vCount == 1) {
              continue;
            }

            int newFirstRow = 0;
            int newLastRow = 0;
            int newFirstColumn = 0;
            int newLastColumn = 0;

            CellRangeAddress newRegion = region.copy();
            if (vCount == 1) {
              newFirstRow = targetFirstRow;
            } else {
              newFirstRow = targetFirstRow + (tmplRowCount + marginV) * (vCount - 1);
            }
            newLastRow = newFirstRow + (targetLastRow - targetFirstRow);

            if (hCount == 1) {
              newFirstColumn = targetFirstColumn;
            } else {
              newFirstColumn = targetFirstColumn + (tmplColCount + marginH) * (hCount - 1);
            }
            newLastColumn = newFirstColumn + (targetLastColumn - targetFirstColumn);

            newRegion.setFirstRow(newFirstRow);
            newRegion.setLastRow(newLastRow);
            newRegion.setFirstColumn(newFirstColumn);
            newRegion.setLastColumn(newLastColumn);
            // セルマージ
            st.addMergedRegion(newRegion);
            Cell newCell = st.getRow(newFirstRow).getCell(newFirstColumn);
            newCell.setCellStyle(oldCell.getCellStyle());
          }
        }
      }
    }
  }

  /**
   * 帳票の固定値をコピーする.
   *
   * @param st
   * @param wb
   * @param tmplRepeat
   */
  private void copyFixedValueForOnePatient(Sheet st, Workbook wb, Optional<ReportXmlTmplRepeat> tmplRepeat) {
    String[] idFT = tmplRepeat.get().getId().split(":");
    if(idFT.length==2) {
      // tmplRepeatの開始コラム
      int tmplColFrom = 0;
      // tmplRepeatの終了コラム
      int tmplColTo = 0;
      // tmplRepeatのコラム数
      int tmplColCount = 0;
      // tmplRepeatの開始行
      int tmplRowFrom = 0;
      // tmplRepeatの終了行
      int tmplRowTo = 0;
      // tmplRepeatの行数
      int tmplRowCount = 0;

      // 繰返回数(縦)
      int repeatCount_V = tmplRepeat.get().getRepeatCountV();
      // 繰返回数(横)
      int repeatCount_H = tmplRepeat.get().getRepeatCountH();
      // 余白(縦)
      int marginV = tmplRepeat.get().getMarginV();
      // 余白(横)
      int marginH = tmplRepeat.get().getMarginH();
      tmplRowFrom = getRowCount(idFT[0]);
      tmplRowTo = getRowCount(idFT[1]);
      tmplRowCount = tmplRowTo - tmplRowFrom + 1;

      tmplColFrom = getColumnCount(idFT[0]);
      tmplColTo = getColumnCount(idFT[1]);
      tmplColCount = tmplColTo - tmplColFrom + 1;

      // コピー元(行)
      Row srcRow = null;
      // コピー元(コラム)
      Cell srcCell = null;
      // コピー先(行)
      Row destRow = null;
      // コピー先(コラム)
      Cell destCell = null;

      for (int i = tmplRowFrom - 1; i< tmplRowTo; i++) {
        for (int j = tmplColFrom - 1; j < tmplColTo; j++) {
          if (st.getRow(i) == null) {
            srcRow = st.createRow(i);
          } else {
            srcRow = st.getRow(i);
          }
          if (srcRow.getCell(j) == null) {
            srcCell = srcRow.createCell(j);
          } else {
            srcCell = srcRow.getCell(j);
          }
          for (int vCount = 1; vCount <= repeatCount_V; vCount ++) {
            for (int hCount = 1; hCount <= repeatCount_H; hCount ++) {
              if (hCount == 1 && vCount == 1) {
                continue;
              }
              if (st.getRow(i + (tmplRowCount + marginV) * (vCount -1)) == null) {
                destRow = st.createRow(i + (tmplRowCount + marginV) * (vCount - 1));
              } else {
                destRow = st.getRow(i + (tmplRowCount + marginV) * (vCount - 1));
              }
              destCell = destRow.createCell(j+ (tmplColCount + marginH) * (hCount - 1));
              // 帳票のCellをコピー
              // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
              // copyCell(wb, srcCell, destCell, true, true);
              copyCell(wb, srcCell, destCell, true, true,tmplRepeat.get().getId());
              // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
            }
          }
        }
      }
    }
  }

