  /**
   * 天数を取得する
   * @param dataKey データキー
   * @return 天数
   */
  private int getDayspan(Map<String, Object> dataKey){
    int daysSpan = 0;
    if(null != dataKey.get("fromDate") && null != dataKey.get("toDate")) {
      try {
        // fromDateを取得する
        Date fromDated = new SimpleDateFormat("yyyyMMdd").parse(dataKey.get("fromDate").toString().replace("-", "").replace("/", ""));
        // toDateを取得する
        Date toDated = new SimpleDateFormat("yyyyMMdd").parse(dataKey.get("toDate").toString().replace("-", "").replace("/", ""));
        daysSpan = differentDays(fromDated, toDated) + 1;
      }catch(ParseException e ){
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
        EventLogMessage eventLogMessage = new EventLogMessage();
        eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
        logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
      }
    }
    return  daysSpan;
  }

