  private String getLetter(String tmplRepeatId) {
    String letter = "";
    // add Aspose.cells関連問題対応 修正 商 start
    if (tmplRepeatId.contains(":")) {
      String[] tmplRepeatIds = tmplRepeatId.split(":");
      tmplRepeatId = tmplRepeatIds[0];
    }
    // add Aspose.cells関連問題対応 修正 商 end
    for (int i = 0; i < tmplRepeatId.length(); i++) {
      if (Character.isLetter(tmplRepeatId.charAt(i)) == false) {
        letter = tmplRepeatId.substring(0, i);
        break;
      }
    }
    return letter;
  }

  private int getNumber(String tmplRepeatId) {
    int num = 0;
    // add Aspose.cells関連問題対応 修正 商 start
    if (tmplRepeatId.contains(":")) {
      String[] tmplRepeatIds = tmplRepeatId.split(":");
      tmplRepeatId = tmplRepeatIds[0];
    }
    // add Aspose.cells関連問題対応 修正 商 end
    for (int i = 0; i < tmplRepeatId.length(); i++) {
      if (Character.isDigit(tmplRepeatId.charAt(i)) == true) {
        String letter = tmplRepeatId.substring(0, i);
        num = Integer.valueOf(tmplRepeatId.replace(letter, ""));
        break;
      }
    }
    return num;
  }

  private String getDateCode(Map<String, List<ReportXmlParam>> groupedParams, String tmplRepeatId) {
    String dateCode = "";
    loop: for (String key : groupedParams.keySet()) {
      List<ReportXmlParam> paramList = groupedParams.get(key);
      for (int index = 0; index < paramList.size(); index++) {
        ReportXmlParam param = paramList.get(index);
        if (tmplRepeatId.equals(param.getId())) {
          dateCode = param.getDataCode();
          break loop;
        }
      }
    }
    return dateCode;
  }

  /**
   * keyを取得する(テンプレート繰り返しではない通常の繰り返し処理のデータ割り当て先keyを応答する).
   *
   * @param key key
   * @param repeatAddressMap ReplaceKeyMap
   */
  private String getReplaceKeyforRepeat_V(String key, Map<String, String> repeatAddressMap) {
    String replaceKey = null;
    // key から、map の key と index を取得
    String indexKey = "";
    String strV = "";
    Integer cellAddrIndex = 0;
    if (key.indexOf("-") > -1) {
      String[] tmpStr = key.split("-");
      indexKey = tmpStr[0];
      strV = tmpStr[1];
      String[] strVS = strV.split("_V");
      cellAddrIndex = Integer.valueOf(strVS[0]);
    } else {
      indexKey = key;
    }
    // key、index を元に、必要なキーを取得
    String str = repeatAddressMap.get(indexKey);
    if (str != null && str.indexOf(",") > -1) {
      String[] repeatAddrs = str.split(",");
      if (cellAddrIndex <= repeatAddrs.length) {
        replaceKey = repeatAddrs[cellAddrIndex - 1];
      }
    }
    if (replaceKey == null) {
      // replace不要の場合
      replaceKey = key;
    }
    return replaceKey;
  }

