    private void setCellValueForOneTotal(Sheet st, String key, String value, String dataTypeInTmp) {
      // add #10752 装置のレポート表示でVA画像が表示されない sunsy start
      if ("byte[]".equals(dataTypeInTmp)) {
        return;
      }
      // add #10752 装置のレポート表示でVA画像が表示されない sunsy end
      String tempKey = "";
      if (key.contains("-")) {
        tempKey = key.substring(0, key.indexOf("-"));
      } else {
        tempKey = key;
      }
      int tmplRowFrom = 0;
      int tmplColFrom = 0;
      tmplColFrom = getColumnCount(tempKey);
      tmplRowFrom = getRowCount(tempKey);

      Cell cell = st.getRow(tmplRowFrom - 1).getCell(tmplColFrom - 1);
      if (StringUtils.isEmpty(value)) {
        cell.setCellValue("");
      } else {
        // mod Aspose.cells関連問題対応 四回目修正 商 start
        // cell.setCellValue(Double.valueOf(value));
        if (!"".equals(dataTypeInTmp) && !"string".equals(dataTypeInTmp) && isNumeric(value)) {
          cell.setCellValue(Double.valueOf(value));
        } else {
          cell.setCellValue(value);
        }
        // mod Aspose.cells関連問題対応 四回目修正 商 end
      }
    }
