  private List<String> getGroupId(List<ReportXmlParam> params) {
    List<String> groupIdList = new ArrayList<>();
    for (int i = 0; i < params.size(); i++) {
      String groupId = params.get(i).getGroupId();
      String id = params.get(i).getId();
      String [] values = groupId.split("\\.");
      String groupIdLast = values[values.length - 1];
      if (id.equals(groupIdLast)) {
        groupIdList.add(id);
      }
    }
    return groupIdList;
  }

