  /**
   * 帳票のページ情報を設定
   *
   * @param param
   * @param dateCount
   * @param resultTemp
   * @param type
   * @param reportXmlTmplRepeat
   */
  private void setResultTemp (ReportXmlParam param, int dateCount,  Map<String, Integer> resultTemp, String type, ReportXmlTmplRepeat reportXmlTmplRepeat) {
    ReportXmlGroup group = param.getReportXmlGroup();
    int repeatCountH = reportXmlTmplRepeat.getRepeatCountH();
    int repeatCountV = reportXmlTmplRepeat.getRepeatCountV();
    int repeatOfPage;
    if (group != null && group.getIsNewPage() == ReportXmlGroup.IS_NEW_PAGE_YES) {
      repeatOfPage = (dateCount > group.getRepeatMax()) ? group.getRepeatMax() : dateCount;
      // 複数項目のページ数より、単一項目のページ数を設定する
      int addPage = (dateCount % repeatOfPage) > 0 ? 1 : 0;
      if ("V".equals(type)) {
        resultTemp.replace("REPEAT_OF_PAGE_V", repeatOfPage);
        resultTemp.replace("GROUP_DATA_PAGE_COUNT_V", (dateCount / repeatOfPage) + addPage);
      } else if ("H".equals(type)) {
        resultTemp.replace("REPEAT_OF_PAGE_H", repeatOfPage);
        resultTemp.replace("GROUP_DATA_PAGE_COUNT_H", (dateCount / repeatOfPage) + addPage);
      }
    } else {
      if ("V".equals(type)) {
        if (dateCount > repeatCountH) {
          repeatOfPage = repeatCountH;
        } else {
          repeatOfPage = dateCount;
        }
        resultTemp.replace("REPEAT_OF_PAGE_V", repeatOfPage);
        resultTemp.replace("GROUP_DATA_PAGE_COUNT_V", 1);
      } else if ("H".equals(type)) {
        if (dateCount > repeatCountV) {
          repeatOfPage = repeatCountV;
        } else {
          repeatOfPage = dateCount;
        }
        resultTemp.replace("REPEAT_OF_PAGE_H", repeatOfPage);
        resultTemp.replace("GROUP_DATA_PAGE_COUNT_H", 1);
      }
    }
  }

  /**
   * セル間隔数の取得
   *
   * @param tmplRepeatId
   * @param type
   * @return セル間隔数
   */
  private int getSkipNum(String tmplRepeatId, String type) {
    int skipNum = 0;
    if (tmplRepeatId.contains(":")) {
      String[] tmplRepeatIds = tmplRepeatId.split(":");
      if (tmplRepeatIds.length == 2) {
        String fromId = tmplRepeatIds[0];
        String toId = tmplRepeatIds[1];
        int formIdNum = 0;
        int toIdNum = 0;
        if ("Row".equals(type)) {
          formIdNum = getRowCount(fromId);
          toIdNum = getRowCount(toId);
        } else if ("Column".equals(type)) {
          formIdNum = getColumnCount(fromId);
          toIdNum = getColumnCount(toId);
        }
        skipNum = toIdNum - formIdNum;
      }
    }
    return skipNum;
  }
