  /**
   * ラベル出力データのソート処理
   * @param resultList 処理前にデータ
   * @param item 並び替えキー
   * @param dis_order データキー
   * @return ソートのデータ
   */
  private List<Map<String, Object>> getListItemSorted(List<Map<String, Object>> resultList, Map<String, String> item, Integer dis_order) {
    // 並び替えがあるの場合
    String sortId = "";
    String sortName = "";
    String sortIdValue = "";

    sortName = checkSortName(item);
    if (!StringUtils.isEmpty(sortName)) {
      sortIdValue = item.get(sortName);
    }

    sortId = SORT_NAME_MAP.get(sortName);
    if (sortId.equals("medicine_name")) {
      if (dis_order.equals(1)) {
        sortId = "dia_order";
      } else if (dis_order.equals(2)) {
        sortId = "equi_order";
      } else if (dis_order.equals(3)) {
        sortId = "medi_order";
      } else if (dis_order.equals(4)) {
        sortId = "medi_mix_order";
      } else if (dis_order.equals(5)) {
        sortId = "spitz_order";
      }
    } else if (sortId.equals("ind_equip_class")) {
      if (dis_order.equals(2)) {
        sortId = "equic_order";
      } else if (dis_order.equals(3)) {
        sortId = "medic_order";
      }else if (dis_order.equals(4)) {
        sortId = "medic_mix_order";
      }
    }
    if (!"ind_equip_cd".equals(sortId) && !"ind_equip_class".equals(sortId)) {
      String[] sort = new String[]{sortId, sortIdValue};

      Collections.sort(resultList, new Comparator<Map<String, Object>>() {
        public int compare(Map<String, Object> o1, Map<String, Object> o2) {
          Integer result = 0;
          if ("asc".equals(sort[1])) {
            Integer sort1 = Integer.parseInt(o1.get(sort[0]) == null ? "999999" : String.valueOf(o1.get(sort[0])));
            Integer sort2 = Integer.parseInt(o2.get(sort[0]) == null ? "999999" : String.valueOf(o2.get(sort[0])));
            result = sort1.compareTo(sort2);
          }
          if ("desc".equals(sort[1])) {
            Integer sort1 = Integer.parseInt(o1.get(sort[0]) == null ? "0" : String.valueOf(o1.get(sort[0])));
            Integer sort2 = Integer.parseInt(o2.get(sort[0]) == null ? "0" : String.valueOf(o2.get(sort[0])));
            result = sort2.compareTo(sort1);
          }
          return result;
        }
      });
    }
    return resultList;
  }

  /**
   * ラベル出力データのソート処理
   * @param resultList 処理前にデータ
   * @param sortConditions 並び替えキー
   * @return ソートのデータ
   */
  private List<Map<String, Object>> getListPatSorted(List<Map<String, Object>> resultList, List<Map<String, String>> sortConditions) {

    // 並び替えがあるの場合
    if (sortConditions != null && sortConditions.size() > 0) {
      boolean ordFlag = false;
      for (int index = 0; index < sortConditions.size(); index++) {
        String sortId = "";
        String sortName = "";
        String sortIdValue = "";
        Map<String, String> item = sortConditions.get(index);
        sortName = checkSortName(item);
        if (!StringUtils.isEmpty(sortName)) {
          sortIdValue = item.get(sortName);
        }
        sortId = SORT_NAME_MAP.get(sortName);
        String[] sort = new String[]{sortId, sortIdValue};
        // mod #9323 帳票「並び替え」機能のオーバーホール　高 start
//        if ("ind_equip_cd".equals(sortId) || "medicine_name".equals(sortId) || "ind_equip_class".equals(sortId)) {
        if ("ind_equip_cd".equals(sortId)|| "ind_equip_class".equals(sortId)) {
          // mod #9323 帳票「並び替え」機能のオーバーホール　高 end
          // ダイアライザ
          List<Map<String, Object>> dializerList = new ArrayList<>();
          // 採血管
          List<Map<String, Object>> spitzList = new ArrayList<>();
          // 医材
          List<Map<String, Object>> equList = new ArrayList<>();
          // 薬剤
          List<Map<String, Object>> medList = new ArrayList<>();
          // 薬剤
          List<Map<String, Object>> medMixList = new ArrayList<>();

          for (int i = 0; i < resultList.size(); i++) {
            if ("1".equals(String.valueOf(resultList.get(i).get("disp_order")))) {
              dializerList.add(resultList.get(i));
            }  else if ("2".equals(String.valueOf(resultList.get(i).get("disp_order")))) {
              equList.add(resultList.get(i));
            } else if ("3".equals(String.valueOf(resultList.get(i).get("disp_order")))) {
              medList.add(resultList.get(i));
            } else if ("4".equals(String.valueOf(resultList.get(i).get("disp_order")))) {
              medMixList.add(resultList.get(i));
            } else if ("5".equals(String.valueOf(resultList.get(i).get("disp_order")))) {
              spitzList.add(resultList.get(i));
            }
          }

          if (item.keySet().contains(CoreConstant.ReportMenu.MEDICINE_EQUIPMENT_CODE)) {
            if ("desc".equals(item.get(item.keySet().stream().findFirst().get()))) {
              ordFlag = true;
            }
          }
            resultList = new ArrayList<>();
            if (ordFlag) {
              // ダイアライザソート
              List<Map<String, Object>> dializerMap = getListItemSorted(dializerList, item, 1);
              // 医材ソート
              List<Map<String, Object>> equMap = getListItemSorted(equList, item, 2);
              // 薬剤ソート
              List<Map<String, Object>> medMap = getListItemSorted(medList, item, 3);
              // 薬剤ソート
              List<Map<String, Object>> medMixMap = getListItemSorted(medMixList, item, 4);
              // 採血管ソート
              List<Map<String, Object>> spitzMap = getListItemSorted(spitzList, item, 5);
              // 薬剤
              resultList.addAll(medMap);
              // 薬剤
              resultList.addAll(medMixMap);
              // ダイアライザ
              resultList.addAll(dializerMap);
              // 医材
              resultList.addAll(equMap);
              // 採血管
              resultList.addAll(spitzMap);
            } else {
              // ダイアライザソート
              List<Map<String, Object>> dializerMap = getListItemSorted(dializerList, item, 1);
              // 医材ソート
              List<Map<String, Object>> equMap = getListItemSorted(equList, item, 2);
              // 薬剤ソート
              List<Map<String, Object>> medMap = getListItemSorted(medList, item, 3);
              // 薬剤ソート
              List<Map<String, Object>> medMixMap = getListItemSorted(medMixList, item, 4);
              // 採血管ソート
              List<Map<String, Object>> spitzMap = getListItemSorted(spitzList, item, 5);
              // ダイアライザ
              resultList.addAll(dializerMap);
              // 医材
              resultList.addAll(equMap);
              // 薬剤
              resultList.addAll(medMap);
              // 薬剤
              resultList.addAll(medMixMap);
              // 採血管
              resultList.addAll(spitzMap);
            }

        }
        // add #9323 帳票「並び替え」機能のオーバーホール　高 start
        else if("medicine_name".equals(sortId) ){
          String finalSortIdValue = sortIdValue;
          resultList = resultList.stream().sorted((patA, patB) -> {
            if (patA.get("name").toString() != patB.get("name").toString() &&
              patA.get("name").toString() != "" && patB.get("name").toString() != "") {
              if ("asc".equals(finalSortIdValue)) {
                return patA.get("name").toString().compareTo(patB.get("name").toString());
              } else {
                return patA.get("name").toString().compareTo(patB.get("name").toString()) * -1;
              }
            } else{
              if ("asc".equals(finalSortIdValue)) {
                return patA.get("pat_id").toString().compareTo(patB.get("pat_id").toString());
              } else {
                return patA.get("pat_id").toString().compareTo(patB.get("pat_id").toString()) * -1;
              }
            }
          }).collect(Collectors.toList());
        }
        // add #9323 帳票「並び替え」機能のオーバーホール　高 end
        else {
          Collections.sort(resultList, new Comparator<Map<String, Object>>() {
            public int compare(Map<String, Object> o1, Map<String, Object> o2) {
              Integer result = 0;
              if ("asc".equals(sort[1])) {
                // mod #7880 帳票：ラベルが正しく表示されない 姜 start
                // Integer sort1 = new Integer(o1.get(sort[0]) == null ? "999999" : String.valueOf(o1.get(sort[0])));
                // Integer sort2 = new Integer(o2.get(sort[0]) == null ? "999999" : String.valueOf(o2.get(sort[0])));
                Integer sort1 = Integer.parseInt((o1.get(sort[0]) == null || String.valueOf(o1.get(sort[0])).equals("0")) ? "999999" : String.valueOf(o1.get(sort[0])));
                Integer sort2 = Integer.parseInt((o2.get(sort[0]) == null || String.valueOf(o2.get(sort[0])).equals("0")) ? "999999" : String.valueOf(o2.get(sort[0])));
                // mod #7880 帳票：ラベルが正しく表示されない 姜 end
                result = sort1.compareTo(sort2);
              }
              if ("desc".equals(sort[1])) {
                // mod #7880 帳票：ラベルが正しく表示されない 姜 start
                // Integer sort1 = new Integer(o1.get(sort[0]) == null ? "0" : String.valueOf(o1.get(sort[0])));
                // Integer sort2 = new Integer(o2.get(sort[0]) == null ? "0" : String.valueOf(o2.get(sort[0])));
                Integer sort1 = Integer.parseInt((o1.get(sort[0]) == null || String.valueOf(o1.get(sort[0])).equals("0")) ? "0" : String.valueOf(o1.get(sort[0])));
                Integer sort2 = Integer.parseInt((o2.get(sort[0]) == null || String.valueOf(o2.get(sort[0])).equals("0")) ? "0" : String.valueOf(o2.get(sort[0])));
                // mod #7880 帳票：ラベルが正しく表示されない 姜 end
                result = sort2.compareTo(sort1);
              }
              return result;
            }
          });
        }
      }
    }
    return resultList;
  }
