  /**
   * DBデータ再作成
   * @param repeatDataList
   * @param dataCode
   * @return DBデータ
   */
  private List<Map<String, Object>> getNewRepeatDataList(List<Map<String, Object>> repeatDataList, String dataCode) {
    List<Map<String, Object>> newRepeatDataList = new ArrayList<>();
    for (int i = 0; i < repeatDataList.size(); i++) {
      String strWeek = String.valueOf(repeatDataList.get(i).get(dataCode));
      strWeek = strWeek.replace("{", "").replace("}", "").replace("\"", "");
      String[] strWeeks = strWeek.split(",");
      List<String> weekList = new ArrayList<>();
      for (int j = 0; j < strWeeks.length; j++) {
        if (!weekList.contains(strWeeks[j])) {
          weekList.add(strWeeks[j]);
        }
      }
      for (int j = 0; j < weekList.size(); j++) {
        Map<String, Object> tempMap = new HashMap<>();
        for (String key : repeatDataList.get(i).keySet()) {
          if (key.equals(dataCode)) {
            tempMap.put(key, weekList.get(j));
          } else {
            tempMap.put(key, repeatDataList.get(i).get(key));
          }
        }
        newRepeatDataList.add(tempMap);
      }
    }
    return newRepeatDataList;
  }

