  /**
   * 帳票縱列表示用のデータ作成
   * @param unitList
   * @param dateList
   * @param repeatDataList
   * @param total_UnitHList
   * @param total_UnitVList
   * @param isDate
   * @return 帳票表示用のデータ
   */
  private List<String> getNewUnitList(List<String> unitList, List<String> dateList, List<Map<String, Object>> repeatDataList,
                                      // mod Aspose.cells関連問題対応 六回目修正 商 start
                                      // List<String> total_UnitHList, List<String> total_UnitVList) {
                                      List<String> total_UnitHList, List<String> total_UnitVList, boolean isDate) {
                                      // mod Aspose.cells関連問題対応 六回目修正 商 end
    Map<String, Integer> hCountMap = new LinkedHashMap<>();
    List<String> newUnitList = new ArrayList<>();
    for (int i = 0; i < unitList.size(); i++) {
      String hValue = unitList.get(i);
      int maxCount = 0;
      for (int j = 0; j < dateList.size(); j++) {
        String vValue = dateList.get(j);
        int count = 0;
        for (int k = 0; k < repeatDataList.size(); k++) {
          String hTemp = "";
          for (int m = 0; m < total_UnitHList.size(); m++) {
            String temp = String.valueOf(repeatDataList.get(k).get(total_UnitHList.get(m)));
            if (StringUtils.isEmpty(temp)) {
              temp = "null";
            }
            if (hTemp == "") {
              hTemp = temp;
            } else {
              hTemp = hTemp + "," + temp;
            }
          }
          if (hValue.equals(hTemp)) {
            String vTemp = "";
            for (int m = 0; m < total_UnitVList.size(); m++) {
              String temp = String.valueOf(repeatDataList.get(k).get(total_UnitVList.get(m)));
              //#10998 「週間.医材」の出力内容修正 杜 start
              //add #9558 単集計のプレビューに失敗 吉 start
              if(null != temp && temp.contains("-")){
                temp = temp.substring(0,10);
              }else{
                //add #9558 単集計のプレビューに失敗 吉 end
                //#10998 「週間.医材」の出力内容修正 杜 start
                SimpleDateFormat originalFormat =  new SimpleDateFormat("yyyyMMdd");
                SimpleDateFormat targetFormat  =  new SimpleDateFormat("yyyy-MM-dd");
                try {
                  //add #9558 単集計のプレビューに失敗 杜 start
                  if (m == 0 && isDate == true) {
                    Date date = originalFormat.parse(temp);
                    temp = targetFormat.format(date);
                  }
                  //add #9558 単集計のプレビューに失敗 杜 end
                } catch (ParseException e) {
                  // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
                  // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
                  // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
                  EventLogMessage eventLogMessage = new EventLogMessage();
                  eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
                  logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
                  // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
                }
                //add #9558 単集計のプレビューに失敗 吉 start
              }
              //add #9558 単集計のプレビューに失敗 吉 end
              //#10998 「週間.医材」の出力内容修正 杜 end
              if (StringUtils.isEmpty(temp)) {
                temp = "null";
                // mod Aspose.cells関連問題対応 六回目修正 商 start
                // } else if (m == 0) {
              } else if (m == 0 && isDate == true) {
                // mod Aspose.cells関連問題対応 六回目修正 商 end
                temp = temp.substring(0, 10);
              }
              // add Aspose.cells関連問題対応 六回目修正 商 start
              if (isDate == false) {
                temp = temp.replace("{", "").replace("}", "");
              }
              // add Aspose.cells関連問題対応 六回目修正 商 end
              if (vTemp == "") {
                vTemp = temp;
              } else {
                vTemp = vTemp + "," + temp;
              }
            }
            if (vValue.equals(vTemp)) {
              count++;
            }
          }
        }
        if (count > maxCount) {
          maxCount = count;
        }
      }
      hCountMap.put(hValue, maxCount);
    }
    for (String hValue : hCountMap.keySet()) {
      for (int i = 0; i < hCountMap.get(hValue); i++) {
        newUnitList.add(hValue);
      }
    }
    return newUnitList;
  }

  /**
   * 横縱合計値取得
   * @param sumDataList
   * @param vhList
   * @param type
   * @return 横縱合計値
   */
  private List<List<String>> getTotalSumDataList(List<List<String>> sumDataList, List<String> vhList, String type) {
    List<List<String>> totalSumDataList = new ArrayList<>();
    if ("H".equals(type))  {

      for (int i = 0; i < vhList.size(); i++) {
        double total = 0;
        String vValue = vhList.get(i);
        if (!TOTAL_VALUES.equals(vValue)) {
          List<String> totalDataList = new ArrayList<>();
          for (int j = 0; j < sumDataList.size(); j++) {
            List<String> list = sumDataList.get(j);
            if (vValue.equals(list.get(0)) && list.get(2) != null) {
              total = total + Double.valueOf(list.get(2));
            }
          }
          if (total > 0) {
            totalDataList.add(vValue);
            totalDataList.add(TOTAL_VALUES);
            totalDataList.add(String.valueOf(total));
            // add Aspose.cells関連問題対応 五回目修正 商 start
            totalDataList.add("0");
            // add Aspose.cells関連問題対応 五回目修正 商 end
            totalSumDataList.add(totalDataList);
          }
        }
      }
    }
    if ("V".equals(type))  {
      for (int i = 0; i < vhList.size(); i++) {
        double total = 0;
        String hValue = vhList.get(i);
        if (!TOTAL_VALUES.equals(hValue)) {
          List<String> totalDataList = new ArrayList<>();
          for (int j = 0; j < sumDataList.size(); j++) {
            List<String> list = sumDataList.get(j);
            if (hValue.equals(list.get(1)) && list.get(2) != null) {
              total = total + Double.valueOf(list.get(2));
            }
          }
          if (total > 0) {
            totalDataList.add(TOTAL_VALUES);
            totalDataList.add(hValue);
            totalDataList.add(String.valueOf(total));
            // add Aspose.cells関連問題対応 五回目修正 商 start
            totalDataList.add("0");
            // add Aspose.cells関連問題対応 五回目修正 商 end
            totalSumDataList.add(totalDataList);
          }
        }
      }
    }
    return totalSumDataList;
  }

