  private List<List<String>> getTotalSumDataListByDay(List<List<String>> sumDataList, List<String> unitList) {
    List<List<String>> totalSumDataList = new ArrayList<>();
    for (int i = 0; i < unitList.size(); i++) {
      double total = 0;
      String hValue = unitList.get(i);
      if (!TOTAL_VALUES.equals(hValue)) {
        List<String> totalDataList = new ArrayList<>();
        List<String> repeatDateList = new ArrayList<>();
        for (int j = 0; j < sumDataList.size(); j++) {
          List<String> list = sumDataList.get(j);
          if (hValue.equals(list.get(1)) && list.get(2) != null && "0".equals(list.get(3))) {
            if (repeatDateList.contains(list.get(0))) {
              continue;
            }
            total = total + Double.valueOf(list.get(2));
            list.set(3, "1");
            repeatDateList.add(list.get(0));
          }
        }
        if (total > 0) {
          totalDataList.add(TOTAL_VALUES);
          totalDataList.add(hValue);
          totalDataList.add(String.valueOf(total));
          // add Aspose.cells関連問題対応 五回目修正 商 start
          totalDataList.add("0");
          // add Aspose.cells関連問題対応 五回目修正 商 end
          totalSumDataList.add(totalDataList);
        }
      }
    }
    return totalSumDataList;
  }
