  /**
   * dispLength の指定により改行を入れる
   *
   * @param str：処理対象文字列 ( 空欄の場合は、処理をスキップ )
   * @return 改行を含む文字列
   */
  // mod 9951 縮小表示ONと表示文字列長が併存したとき、後者が機能するのはNG 吉 start
  // private String addLineBreak(String str, String dispLength, String dataType) {
  // mod #10887 繰返しでない項目」「グループ改頁OFFの項目」がテンプレート繰返し時に不正 limingzhe start
  //private String addLineBreak(String str, ReportXmlParam param) {
  public String addLineBreak(String str, ReportXmlParam param) {
  // mod #10887 繰返しでない項目」「グループ改頁OFFの項目」がテンプレート繰返し時に不正 limingzhe end
    String dispLength = param.getDispLength();
    String dataType = param.getDataType();
    String isShrink = param.getIsShrink();
    // mod 9951 縮小表示ONと表示文字列長が併存したとき、後者が機能するのはNG 吉 end
    // 引数チェック
    int len = 0;
    // mod 9951 縮小表示ONと表示文字列長が併存したとき、後者が機能するのはNG 吉 start
    // if (StringUtils.isEmpty(dispLength) || !dispLength.matches("[0-9]+")) {
    if (StringUtils.isEmpty(dispLength) || !dispLength.matches("[0-9]+") || "1".equals(isShrink)) {
      // mod 9951 縮小表示ONと表示文字列長が併存したとき、後者が機能するのはNG 吉 end
      return str;
    } else {
      len = Integer.valueOf(dispLength);
    }
    if (StringUtils.isEmpty(str)
        || len < 1
        || !dataType.equals(ReportXmlParam.DATA_TYPE_STRING)) {
      return str;
    }
    // 文字数毎に改行を追加
    StringBuilder sb = new StringBuilder();
    int lenCount = 0;
    for (int i = 0; i < str.length(); i++) {
      char c = str.charAt(i);
      // 改行コードの場合はカウントをリセットして次の行から
      if (c == '\r' || c == '\n') {
        sb.append(c);
        lenCount = 0;
        continue;
      }
      // 1：半角、2：全角
      int cType = 2;

      // add #9397 表示文字列長の設定、およびフリー計算パラメータの書式設定について 李 begin
//      if ((c <= '\u007e') || // 英数字
//        (c == '\u00a5') || // \記号
//        (c == '\u203e') || // ~記号
//        (c >= '\uff61' && c <= '\uff9f') // 半角カナ
//      ) {
//        cType = 1;
//      }

      try {
        cType = String.valueOf(c).getBytes("Shift_JIS").length;
      } catch (UnsupportedEncodingException e) {
        if ((c <= '\u007e') || // 英数字
          (c == '\u00a5') || // \記号
          (c == '\u203e') || // ~記号
          (c >= '\uff61' && c <= '\uff9f') // 半角カナ
        ) {
          cType = 1;
        }
      }
      // add #9397 表示文字列長の設定、およびフリー計算パラメータの書式設定について 李 end

      lenCount += cType;
      if (lenCount <= len) {
        sb.append(c);
      } else {
        // 改行を追加
        sb.append("\n");
        sb.append(c);
        lenCount = 0 + cType;
      }
    }
    return sb.toString();
  }

