  /**
   * 繰り返し処理個所のスタイルコピー：繰り返し先に縮小表示、結合状態をコピーする.
   *
   * @param st 処理対象のシートオブジェクト
   * @param repeatAddressMap 繰り返し範囲のセルリスト
   * ※ 繰り返し先のセルリストにデータが存在する場合、最初のセルから、残り全てのセルへスタイルをコピーする処理を行います。
   * ※ 繰り返し元のセルが結合セルだった場合、結合状態もコピーします。
   * ※ 罫線は帳票レイアウト作成時に適切に設定されている場合が多い為、コピーを行わず、現状を維持します。
   */
  private void stdCopyStyleFromCells(Sheet st, Map<String, String> repeatAddressMap) {

    if (repeatAddressMap.size() > 0) {

      Workbook wb = st.getWorkbook();

      // データ例：D9 = D9,D10,D11,D12,D13,,, のようなデータのリストです
      for (String keyCell : repeatAddressMap.keySet()) {
        String cellListStr = repeatAddressMap.get(keyCell);
        String[] cellList = cellListStr.split(",");

        if (cellList.length <= 1) {
          // リストが空、もしくは1件のみの場合は処理をせず次の処理に飛ばします ( 1件目がkeyCellと同じの為、処理不要 )
          continue;
        }

        // セルのスタイルコピーを実施
        for (int ii = 1; ii < cellList.length; ii++) {

          if (cellList[ii].contains(":")) {
            // 結合セルだった場合、結合の範囲内で一式スタイルのコピーを行い、最後に結合処理を行う

            // コピー元範囲
            CellRangeAddress srcRange = CellRangeAddress.valueOf(keyCell);
            // コピー元セルの開始行
            int tmplRowFrom = srcRange.getFirstRow();
            // コピー元セルの開始Column
            int tmplColFrom = srcRange.getFirstColumn();
            // コピー元セルの終了行
            int tmplRowTo = srcRange.getLastRow();
            // コピー元セルの終了Column
            int tmplColTo = srcRange.getLastColumn();

            // コピー先範囲
            CellRangeAddress destRange = CellRangeAddress.valueOf(cellList[ii]);
            // コピー先セルの開始行
            int destRowFrom = destRange.getFirstRow();
            // コピー先セルの開始Column
            int destColFrom = destRange.getFirstColumn();
            // コピー先セルの終了行
            int destRowTo = destRange.getLastRow();
            // コピー先セルの終了Column
            int destColTo = destRange.getLastColumn();

            // コピー元(行)
            Row srcRow = null;
            // コピー元(コラム)
            Cell srcCell = null;
            // コピー先(行)
            Row destRow = null;
            // コピー先(コラム)
            Cell destCell = null;

            // style のコピー
            for (int i = tmplRowFrom; i <= tmplRowTo; i++) {
              for (int j = tmplColFrom; j <= tmplColTo; j++) {
                // コピー元Cellを取得
                if (st.getRow(i) == null) {
                  srcRow = st.createRow(i);
                } else {
                  srcRow = st.getRow(i);
                }
                if (srcRow.getCell(j) == null) {
                  srcCell = srcRow.createCell(j);
                } else {
                  srcCell = srcRow.getCell(j);
                }
                // コピー先Cellを取得
                if (st.getRow(destRowFrom + ( i - tmplRowFrom)) == null) {
                  destRow = st.createRow(destRowFrom + ( i - tmplRowFrom));
                } else {
                  destRow = st.getRow(destRowFrom + ( i - tmplRowFrom));
                }
                if (destRow.getCell(destColFrom + ( j - tmplColFrom)) == null) {
                  destCell = destRow.createCell((destColFrom + ( j - tmplColFrom)));
                } else {
                  destCell = destRow.getCell((destColFrom + ( j - tmplColFrom)));
                }
                // style のコピーを実施
                CellStyle newstyle= wb.createCellStyle();
                copyCellStyle(wb, srcCell.getCellStyle(), newstyle, false);
                // 罫線のコピーしなかった場合、newstyle は、罫線無しになっているので、コピー先のスタイルを上書きしないようにする
                newstyle.setBorderBottom(destCell.getCellStyle().getBorderBottom());
                newstyle.setBorderLeft(destCell.getCellStyle().getBorderLeft());
                newstyle.setBorderRight(destCell.getCellStyle().getBorderRight());
                newstyle.setBorderTop(destCell.getCellStyle().getBorderTop());
                newstyle.setTopBorderColor(destCell.getCellStyle().getTopBorderColor());
                newstyle.setBottomBorderColor(destCell.getCellStyle().getBottomBorderColor());
                newstyle.setRightBorderColor(destCell.getCellStyle().getRightBorderColor());
                newstyle.setLeftBorderColor(destCell.getCellStyle().getLeftBorderColor());
                destCell.setCellStyle(newstyle);
                if (srcCell.getCellComment() != null) {
                  destCell.setCellComment(srcCell.getCellComment());
                }
              }
            }

            // 結合処理
            try {
              CellRangeAddress newRegion = new CellRangeAddress(destRowFrom, destRowTo, destColFrom, destColTo);
              st.addMergedRegion(newRegion);
            } catch (Exception e) {
              // 結合先が結合状態の場合、エラーになるので、処理をスキップする
            }

          } else {
            // 単体セルだった場合、スタイルのコピーのみ実施

            if (!cellList[ii].matches("^[A-Z]+\\d+$")) {
              // コピー先セルがA1参照形式(A1等の指定方式)になっていなければ処理をスキップ
              continue;
            }

            CellStyle newstyle= wb.createCellStyle();

            // コピー元セル取得
            CellReference srcCellObj = new CellReference(keyCell);
            Row srcRow = null;
            if (st.getRow(srcCellObj.getRow()) == null) {
              srcRow = st.createRow(srcCellObj.getRow());
            } else {
              srcRow = st.getRow(srcCellObj.getRow());
            }
            Cell srcCell = null;
            if (srcRow.getCell(srcCellObj.getCol()) == null) {
              srcCell = srcRow.createCell(srcCellObj.getCol());
            } else {
              srcCell = srcRow.getCell(srcCellObj.getCol());
            }

            // コピー先セル取得
            CellReference destCellObj = new CellReference(cellList[ii]);
            Row destRow = null;
            if (st.getRow(destCellObj.getRow()) == null) {
              destRow = st.createRow(destCellObj.getRow());
            } else {
              destRow = st.getRow(destCellObj.getRow());
            }
            Cell destCell = null;
            if (destRow.getCell(destCellObj.getCol()) == null) {
              destCell = destRow.createCell(destCellObj.getCol());
            } else {
              destCell = destRow.getCell(destCellObj.getCol());
            }
            // style のコピーを実施
            copyCellStyle(wb, srcCell.getCellStyle(), newstyle, true);
            // 罫線のコピーしなかった場合、newstyle は、罫線無しになっているので、コピー先のスタイルを上書きしないようにする
            newstyle.setBorderBottom(destCell.getCellStyle().getBorderBottom());
            newstyle.setBorderLeft(destCell.getCellStyle().getBorderLeft());
            newstyle.setBorderRight(destCell.getCellStyle().getBorderRight());
            newstyle.setBorderTop(destCell.getCellStyle().getBorderTop());
            newstyle.setTopBorderColor(destCell.getCellStyle().getTopBorderColor());
            newstyle.setBottomBorderColor(destCell.getCellStyle().getBottomBorderColor());
            newstyle.setRightBorderColor(destCell.getCellStyle().getRightBorderColor());
            newstyle.setLeftBorderColor(destCell.getCellStyle().getLeftBorderColor());
            destCell.setCellStyle(newstyle);
            if (srcCell.getCellComment() != null) {
              destCell.setCellComment(srcCell.getCellComment());
            }
          }
        }
      }
      return;
    }
  }

  /**
   * テンプレート繰り返し個所の値、スタイルコピー：繰り返し元のセルの値、スタイル、結合状態をテンプレート繰り返しの回数分コピーする.
   *
   * @param st 処理対象のシートオブジェクト
   * @param wb 処理対象のワークブックオブジェクト
   * @param tmplRepeat テンプレート設定
   * ※ テンプレート繰り返しの範囲のスタイルを、テンプレート繰り返しの回数分コピーします
   * ※ テンプレート対象個所のみ、1ページ分実施します。ページ遷移分は遷移後にもう一度この処理を呼んでください
   */
  private void stdCopyFromTmpl(Sheet st, Workbook wb, Optional<ReportXmlTmplRepeat> tmplRepeat) {

    // テンプレート文字列が空の場合は処理をスキップ
    if (StringUtils.isEmpty(tmplRepeat.get().getId())) {
      return;
    }
    // テンプレート設定を取得
    // 繰返回数(縦)
    int repeatCount_V = tmplRepeat.get().getRepeatCountV();
    // 繰返回数(横)
    int repeatCount_H = tmplRepeat.get().getRepeatCountH();

    if (repeatCount_V <= 1 && repeatCount_H <= 1) {
      // 繰り返し回数がどちらも1回の場合は実施不要
      return;
    }

    // テンプレート範囲を取得
    String[] idFT = tmplRepeat.get().getId().split(":");
    if (idFT.length == 2) {
      // テンプレート範囲の取得
      CellRangeAddress tmplRange = CellRangeAddress.valueOf(tmplRepeat.get().getId());
      // テンプレート範囲の開始Column
      int tmplColFrom = tmplRange.getFirstColumn();
      // テンプレート範囲の終了Column
      int tmplColTo = tmplRange.getLastColumn();
      // テンプレート範囲のColumn数
      // int tmplColCount = tmplColTo - tmplColFrom;
      int tmplColCount = tmplColTo - tmplColFrom + 1;
      // テンプレート範囲の開始Row
      int tmplRowFrom = tmplRange.getFirstRow();
      // テンプレート範囲の終了Row
      int tmplRowTo = tmplRange.getLastRow();
      // テンプレート範囲のRow数
      // int tmplRowCount = tmplRowTo - tmplRowFrom;
      int tmplRowCount = tmplRowTo - tmplRowFrom + 1;

      // 余白(縦)
      int marginV = tmplRepeat.get().getMarginV();
      // 余白(横)
      int marginH = tmplRepeat.get().getMarginH();

      // コピー元(Row)
      Row srcRow = null;
      // コピー元(Column)
      Cell srcCell = null;
      // コピー先(Row)
      Row destRow = null;
      // コピー先(Column)
      Cell destCell = null;

      // style、value のコピー
      for (int rCount = tmplRowFrom; rCount <= tmplRowTo; rCount++) {
        for (int cCount = tmplColFrom; cCount <= tmplColTo; cCount++) {
          // スタイルコピー元セル取得
          if (st.getRow(rCount) == null) {
            srcRow = st.createRow(rCount);
          } else {
            srcRow = st.getRow(rCount);
          }
          if (srcRow.getCell(cCount) == null) {
            srcCell = srcRow.createCell(cCount);
          } else {
            srcCell = srcRow.getCell(cCount);
          }

          if (ReportXmlTmplRepeat.DIRECTION_Z.equals(String.valueOf(tmplRepeat.get().getDirection()))) {
            // Z方向

            for (int vCount = 1; vCount <= repeatCount_V; vCount ++) {
              for (int hCount = 1; hCount <= repeatCount_H; hCount ++) {

                if (hCount == 1 && vCount == 1) {
                  // コピー先が同じテンプレート範囲の為除外
                  continue;
                }
                // コピー先セルを取得
                int tmpRowNo = rCount + (tmplRowCount + marginV) * (vCount -1);
                if (st.getRow(tmpRowNo) == null) {
                  destRow = st.createRow(tmpRowNo);
                } else {
                  destRow = st.getRow(tmpRowNo);
                }
                int tmpColNo = cCount + (tmplColCount + marginH) * (hCount - 1);
                if (destRow.getCell(tmpColNo) == null) {
                  destCell = destRow.createCell(tmpColNo);
                } else {
                  destCell = destRow.getCell(tmpColNo);
                }
                // srcCell の style、value をコピー
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
                // copyCell(wb, srcCell, destCell, true, false);
                copyCell(wb, srcCell, destCell, true, false,tmplRepeat.get().getId());
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
              }
            }
          } else {
            // N方向

            for (int hCount = 1; hCount <= repeatCount_H; hCount ++) {
              for (int vCount = 1; vCount <= repeatCount_V; vCount ++) {

                if (hCount == 1 && vCount == 1) {
                  // コピー先が同じテンプレート範囲の為除外
                  continue;
                }
                // コピー先セルを取得
                int tmpRowNo = rCount + (tmplRowCount + marginV) * (vCount -1);
                if (st.getRow(tmpRowNo) == null) {
                  destRow = st.createRow(tmpRowNo);
                } else {
                  destRow = st.getRow(tmpRowNo);
                }
                int tmpColNo = cCount + (tmplColCount + marginH) * (hCount - 1);
                if (destRow.getCell(tmpColNo) == null) {
                  destCell = destRow.createCell(tmpColNo);
                } else {
                  destCell = destRow.getCell(tmpColNo);
                }
                // srcCell の style、value をコピー
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
                // copyCell(wb, srcCell, destCell, true, false);
                copyCell(wb, srcCell, destCell, true, false,tmplRepeat.get().getId());
                // mod 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 end
              }
            }
          }
        }
      }

      // 結合状態のコピー
      int mergedCount = st.getNumMergedRegions();
      for(int mCount = 0; mCount < mergedCount; mCount++) {
        // 結合されたセルを取得
        CellRangeAddress region = st.getMergedRegion(mCount);
        // コピー元範囲内の結合セルだった場合、処理を実施
        if (tmplRowFrom <= region.getFirstRow()
            && tmplColFrom <= region.getFirstColumn()
            && tmplRowTo >= region.getLastRow()
            && tmplColTo >= region.getLastColumn()) {

          if (ReportXmlTmplRepeat.DIRECTION_Z.equals(String.valueOf(tmplRepeat.get().getDirection()))) {
            // Z方向

            for (int mgVCount = 1; mgVCount <= repeatCount_V; mgVCount++) {
              for (int mgHCount = 1; mgHCount <= repeatCount_H; mgHCount++) {

                if (mgHCount == 1 && mgVCount == 1) {
                  // 1つめはコピー元なので処理不要
                  continue;
                }
                try {
                  CellRangeAddress newRegion = region.copy();
                  newRegion.setFirstRow(region.getFirstRow() + ((tmplRowCount + marginV) * (mgVCount - 1))); // (コピー元縦幅 + 余白縦) * 縦の件数
                  newRegion.setLastRow(region.getLastRow() + ((tmplRowCount + marginV) * (mgVCount - 1)));
                  newRegion.setFirstColumn(region.getFirstColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  newRegion.setLastColumn(region.getLastColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  st.addMergedRegion(newRegion);
                } catch (Exception e) {
                  // 結合先が結合状態の場合、エラーになるので、処理をスキップする
                }
              }
            }
          } else {
            // N方向

            for (int mgHCount = 1; mgHCount <= repeatCount_H; mgHCount++) {
              for (int mgVCount = 1; mgVCount <= repeatCount_V; mgVCount++) {

                if (mgHCount == 1 && mgVCount == 1) {
                  // 1つめはコピー元なので処理不要
                  continue;
                }
                try {
                  CellRangeAddress newRegion = region.copy();
                  newRegion.setFirstRow(region.getFirstRow() + ((tmplRowCount + marginV) * (mgVCount - 1))); // (コピー元縦幅 + 余白縦) * 縦の件数
                  newRegion.setLastRow(region.getLastRow() + ((tmplRowCount + marginV) * (mgVCount - 1)));
                  newRegion.setFirstColumn(region.getFirstColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  newRegion.setLastColumn(region.getLastColumn() + ((tmplColCount + marginH) * (mgHCount - 1)));
                  st.addMergedRegion(newRegion);
                } catch (Exception e) {
                  // 結合先が結合状態の場合、エラーになるので、処理をスキップする
                }
              }
            }
          }
        }
      }

    } // if (idFT.length == 2) の終端

  } // stdCopyFromTmpl メソッド枠の終端

