  /**
   * 再帰の処理
   * @param resultLines
   * @param currentlineValues
   * @param itemsInfo
   */
  private void changeLine(List<Map<String, Object>> resultLines, Map<String, Object> currentlineValues, List<ReportXmlParam> itemsInfo) {

    Map<String, Object> nextLineValues = new HashMap<String, Object>();
    for (ReportXmlParam itemInfo : itemsInfo) {
      // mod 10089 クラス「透析条件」の出力不正（指示、実績）sunsy start
      //String itemValue = (String)currentlineValues.get(itemInfo.getDataCode());
      String itemValue = String.valueOf(currentlineValues.get(itemInfo.getDataCode()));
      // mod 10089 クラス「透析条件」の出力不正（指示、実績）sunsy end
      // mod 9397 表示文字列長の設定、およびフリー計算パラメータの書式設定について jiang start
      // int maxLength = Integer.parseInt(itemInfo.getDispLength());
      int maxLength = Integer.parseInt(itemInfo.getDispLength()) * Integer.parseInt(null != itemInfo.getRowCount() && !itemInfo.getRowCount().equals("") && Integer.valueOf(itemInfo.getRowCount()) > 0 ? itemInfo.getRowCount() : "1");
      // mod 9397 表示文字列長の設定、およびフリー計算パラメータの書式設定について jiang end
      if (itemValue != null && itemValue.getBytes().length > maxLength) {
        String currentLineValaue = itemValue.substring(0, strLentgh(itemValue, maxLength));
        String nextLineValaue = itemValue.substring(strLentgh(itemValue, maxLength));
        currentlineValues.put(itemInfo.getDataCode(), currentLineValaue);
        if (!nextLineValaue.isEmpty()) {
          nextLineValues.put(itemInfo.getDataCode(), nextLineValaue);
        }
      }
    }
    resultLines.add(currentlineValues);
    if (nextLineValues.size() > 0) {
      changeLine(resultLines, nextLineValues, itemsInfo);
    }
  }

