  private static int CountSubstringRegex(String text, String regex) {
    Pattern pattern = Pattern.compile(regex);
    Matcher matcher = pattern.matcher(text);
    int count = 0;

    while (matcher.find()) {
      count++;
    }
    return count;
  }
