  private int strLentgh(String str, int dispLength) {
    if (StringUtils.isEmpty(str)) {
      return 0;
    }
    // add 10375 患者イベント(テキストエリア)の出力が不正 吉 start
    if (str != null && str.contains("\uFEFF")) {
      str = str.replace("\uFEFF", "");
    }
    // add 10375 患者イベント(テキストエリア)の出力が不正 吉 end
    // 文字数毎に改行を追加
    int lenCount = 0;
    int index = 0;
    for (int i = 0; i < str.length(); i++) {
      char c = str.charAt(i);
      // 1：半角、2：全角
      int cType = 2;
      if ((c <= '\u007e') || // 英数字
        (c == '\u00a5') || // \記号
        (c == '\u203e') || // ~記号
        (c >= '\uff61' && c <= '\uff9f') // 半角カナ
      ) {
        cType = 1;
      }
      lenCount += cType;
      if (lenCount > dispLength) {

        break;
      } else {
        index = i + 1;
      }
    }
    return index;
  }
  private int byteLength(String str) {
    if (StringUtils.isEmpty(str)) {
      return 0;
    }
    // add 10375 患者イベント(テキストエリア)の出力が不正 吉 start
    if (str != null && str.contains("\uFEFF")) {
      str = str.replace("\uFEFF", "");
    }
    // add 10375 患者イベント(テキストエリア)の出力が不正 吉 end
    // 文字数毎に改行を追加
    int lenCount = 0;
    for (int i = 0; i < str.length(); i++) {
      char c = str.charAt(i);
      // 1：半角、2：全角
      int cType = 2;
      if ((c <= '\u007e') || // 英数字
        (c == '\u00a5') || // \記号
        (c == '\u203e') || // ~記号
        (c >= '\uff61' && c <= '\uff9f') // 半角カナ
      ) {
        cType = 1;
      }
      lenCount += cType;
    }
    return lenCount;
  }
