  public static <K, V extends Serializable> Map<K, List<Map<String, Object>>> deepCopy(
    Map<K, List<Map<String, Object>>> original) throws IOException, ClassNotFoundException {
    Map<K, List<Map<String, Object>>> copy = new HashMap<>();

    for (Map.Entry<K, List<Map<String, Object>>> entry : original.entrySet()) {
      K key = entry.getKey();
      List<Map<String, Object>> value = entry.getValue();
      List<Map<String, Object>> valueCopy = deepCopyList(value);
      copy.put(key, valueCopy);
    }

    return copy;
  }

