  public boolean  isHave(String formula){
    String jumpFormula = formula;
    if(jumpFormula.contains("$")){
      jumpFormula = jumpFormula.replaceAll("\\$","");
    }
    Pattern pattern = Pattern.compile("[A-Z]+\\d+");
    if(pattern.matcher(jumpFormula).find()){
      return false;
    }
    return  true;
  }
  // add #11558 「##=」のデータ項目出力で空白になったり「#VALUE!」になったりする 吉 end
  // add 9423 テンプレート繰返し時に元々値があるセルは上書きしないようにすること　吉 start
  public String excelConvert(String formula){
    // del #11558 「##=」のデータ項目出力で空白になったり「#VALUE!」になったりする 吉 start
//    String jumpFormula = formula;
//    if(jumpFormula.contains("$")){
//      jumpFormula = jumpFormula.replaceAll("\\$","");
//    }
//    Pattern pattern = Pattern.compile("[A-Z]+\\d+");
//    if(pattern.matcher(jumpFormula).find()){
//      return " ";
//    }
    // del #11558 「##=」のデータ項目出力で空白になったり「#VALUE!」になったりする 吉 end
    Workbook workbook = new XSSFWorkbook();
    Sheet sheet = workbook.createSheet("Sheet1");
    Row row = sheet.createRow(0);
    Cell cell = row.createCell(0);
    try {
      cell.setCellFormula(formula);
    }catch (Exception ex) {
      return " ";
    }
    CellValue cellValue = workbook.getCreationHelper().createFormulaEvaluator().evaluate(cell);
    String cellType = cellValue.getCellType().toString();
    if(cellType.equals("STRING")){
      String formulaResult = cellValue.getStringValue();
      return String.valueOf(formulaResult);
    }else if(cellType.equals("NUMERIC")){
      double formulaResult = cellValue.getNumberValue();
      return String.valueOf(formulaResult);
    }else if(cellType.equals("BOOLEAN")){
      boolean formulaResult = cellValue.getBooleanValue();
      return String.valueOf(formulaResult);
    }
    // mod #11755 「##=」でstring型を参照すると空値のときにnullと出る start
    else if (cellType.equals("ERROR")) {
      return "";
    }
    // mod #11755 「##=」でstring型を参照すると空値のときにnullと出る end
    else{
      byte formulaResult = cellValue.getErrorValue();
      return String.valueOf(formulaResult);
    }
  }
