  /**
   * セルがマージされたセルであるかどうかを判定します。
   *
   * @param sheet  シート
   * @param cell   対象のセル
   * @return       セルがマージされたセルである場合は true、そうでない場合は false
   */
  private static boolean isMergedCell(Sheet sheet, Cell cell) {
    // シート内のマージされた領域の数だけループします
    for (CellRangeAddress mergedRegion : sheet.getMergedRegions()) {
      // セルがマージされた領域に含まれているかをチェックします
      // mod #9577 「？？？？」患者は表示されません（複数患者帳票）。 2024/03/18 高 start
//      if (mergedRegion.isInRange(cell.getRowIndex(), cell.getColumnIndex())) {
      if (null != cell && mergedRegion.isInRange(cell.getRowIndex(), cell.getColumnIndex())) {
        // mod #9577 「？？？？」患者は表示されません（複数患者帳票）。 2024/03/18 高 end
        // マージされたセルである場合は true を返します
        return true;
      }
    }
    // マージされたセルでない場合は false を返します
    return false;
  }

  /**
   * セルが含まれるマージされた領域を解除します。
   *
   * @param sheet  シート
   * @param cell   対象のセル
   */
  private static void unmergeCell(Sheet sheet, Cell cell) {
    // シート内のマージされた領域の数だけループします
    for (int i = sheet.getNumMergedRegions() - 1; i >= 0; i--) {
      // マージされた領域を取得します
      CellRangeAddress mergedRegion = sheet.getMergedRegion(i);
      // セルがマージされた領域に含まれているかをチェックします
      // mod #10613 【デグレ】複数患者帳票(先行施設)でシステムエラー 高　start
//      if (mergedRegion.isInRange(cell.getRowIndex(), cell.getColumnIndex())) {
      if (null != cell &&mergedRegion.isInRange(cell.getRowIndex(), cell.getColumnIndex())) {
        // mod #10613 【デグレ】複数患者帳票(先行施設)でシステムエラー 高　end
        // マージされた領域を解除します
        sheet.removeMergedRegion(i);
        // マージされた領域が見つかればループを終了します
        break;
      }
    }
  }

  // add #11232 #10515で入れた制限の見直し 房 start
  private void copyStyleFromCells(Sheet st, Map<String, String> repeatAddressMap) {
    copyStyleFromCells(st, repeatAddressMap, null);
  }
  // add #11232 #10515で入れた制限の見直し 房 end

  // mod #11232 #10515で入れた制限の見直し 房 start
  /**
   * 指定されたシートのセルスタイルをコピーします。
   *
   * @param st                シート
   * @param repeatAddressMap  繰り返しアドレスのマップ
   */
  private void copyStyleFromCells(Sheet st, Map<String, String> repeatAddressMap, Map<String, CellStyle> baseMap) {
    // mod #11232 #10515で入れた制限の見直し 房 end

    if (repeatAddressMap.size() > 0) {
      // ワークブックを取得します
      Workbook wb = st.getWorkbook();

      // データ例：D9 = D9,D10,D11,D12,D13,,, のようなデータのリストです
      for (String keyCell : repeatAddressMap.keySet()) {
        // セルリストを取得します
        String cellListStr = repeatAddressMap.get(keyCell);
        // セルリストを分割します
        String[] cellList = cellListStr.split(",");

        if (cellList.length <= 1) {
          // リストが空、もしくは1件のみの場合は処理をせず次の処理に飛ばします ( 1件目がkeyCellと同じの為、処理不要 )
          continue;
        }

        // セルのスタイルコピーを実施
        for (int ii = 1; ii < cellList.length; ii++) {

          if (cellList[0].contains(":")) {
            // 結合セルだった場合、結合の範囲内で一式スタイルのコピーを行い、最後に結合処理を行う

            // コピー元範囲
            CellRangeAddress srcRange = CellRangeAddress.valueOf(keyCell);
            // コピー元セルの開始行
            int tmplRowFrom = srcRange.getFirstRow();
            // コピー元セルの開始Column
            int tmplColFrom = srcRange.getFirstColumn();
            // コピー元セルの終了行
            int tmplRowTo = srcRange.getLastRow();
            // コピー元セルの終了Column
            int tmplColTo = srcRange.getLastColumn();

            // コピー先範囲
            CellRangeAddress destRange = CellRangeAddress.valueOf(cellList[ii]);
            // コピー先セルの開始行
            int destRowFrom = destRange.getFirstRow();
            // コピー先セルの開始Column
            int destColFrom = destRange.getFirstColumn();
            // コピー先セルの終了行
            int destRowTo = destRange.getLastRow();
            // コピー先セルの終了Column
            int destColTo = destRange.getLastColumn();

            // コピー元(行)
            Row srcRow = null;
            // コピー元(コラム)
            Cell srcCell = null;
            // コピー先(行)
            Row destRow = null;
            // コピー先(コラム)
            Cell destCell = null;

            // style のコピー
            for (int i = tmplRowFrom; i <= tmplRowTo; i++) {
              for (int j = tmplColFrom; j <= tmplColTo; j++) {
                // コピー元Cellを取得
                if (st.getRow(tmplRowFrom) == null) {
                  srcRow = st.createRow(tmplRowFrom);
                } else {
                  srcRow = st.getRow(tmplRowFrom);
                }
                if (srcRow.getCell(tmplColFrom) == null) {
                  srcCell = srcRow.createCell(tmplColFrom);
                } else {
                  srcCell = srcRow.getCell(tmplColFrom);
                }
                // コピー先Cellを取得
                if (st.getRow(destRowFrom + ( i - tmplRowFrom)) == null) {
                  destRow = st.createRow(destRowFrom + ( i - tmplRowFrom));
                } else {
                  destRow = st.getRow(destRowFrom + ( i - tmplRowFrom));
                }
                if (destRow.getCell(destColFrom + ( j - tmplColFrom)) == null) {
                  destCell = destRow.createCell((destColFrom + ( j - tmplColFrom)));
                } else {
                  destCell = destRow.getCell((destColFrom + ( j - tmplColFrom)));
                }
                // style のコピーを実施
                // mod #11232 #10515で入れた制限の見直し 房 start
                copyStyleExceptLines(wb, srcCell, destCell, ii + "-" + i + "-" + j, baseMap);
                // mod #11232 #10515で入れた制限の見直し 房 end
                // コメントのコピーを実施
                if (srcCell.getCellComment() != null) {
                  destCell.setCellComment(srcCell.getCellComment());
                }
              }
            }

          } else {
            // 単体セルだった場合、スタイルのコピーのみ実施

            if (!cellList[ii].matches("^[A-Z]+\\d+$")) {
              // コピー先セルがA1参照形式(A1等の指定方式)になっていなければ処理をスキップ
              continue;
            }

            // コピー元セル取得
            CellReference srcCellObj = new CellReference(keyCell);
            Row srcRow = null;
            if (st.getRow(srcCellObj.getRow()) == null) {
              srcRow = st.createRow(srcCellObj.getRow());
            } else {
              srcRow = st.getRow(srcCellObj.getRow());
            }
            Cell srcCell = null;
            if (srcRow.getCell(srcCellObj.getCol()) == null) {
              srcCell = srcRow.createCell(srcCellObj.getCol());
            } else {
              srcCell = srcRow.getCell(srcCellObj.getCol());
            }

            // コピー先セル取得
            CellReference destCellObj = new CellReference(cellList[ii]);
            Row destRow = null;
            if (st.getRow(destCellObj.getRow()) == null) {
              destRow = st.createRow(destCellObj.getRow());
            } else {
              destRow = st.getRow(destCellObj.getRow());
            }
            Cell destCell = null;
            if (destRow.getCell(destCellObj.getCol()) == null) {
              destCell = destRow.createCell(destCellObj.getCol());
            } else {
              destCell = destRow.getCell(destCellObj.getCol());
            }
            // style のコピーを実施
            // mod #11232 #10515で入れた制限の見直し 房 start
            copyStyleExceptLines(wb,srcCell,destCell, "" + ii, baseMap);
            // mod #11232 #10515で入れた制限の見直し 房 end
            if (srcCell.getCellComment() != null) {
              destCell.setCellComment(srcCell.getCellComment());
            }
          }
        }
      }
      return;
    }
  }

  /**
   * ソースとなるマージされたセルのスタイルを取得します。
   *
   * @param sheet               シート
   * @param mergedRegionIndex   マージされた領域のインデックス
   * @return                    セルのスタイル
   */
  private static CellStyle getSourceMergedCellStyles(Sheet sheet, int mergedRegionIndex) {
    // マージされた領域を取得します
    CellRangeAddress mergedRegion = sheet.getMergedRegion(mergedRegionIndex);
    // 開始行インデックスを取得します
    int rowIndex = mergedRegion.getFirstRow();
    // 開始列インデックスを取得します
    int colIndex = mergedRegion.getFirstColumn();
    // 行を取得します
    Row row = sheet.getRow(rowIndex);
    // セルを取得します
    Cell cell = row.getCell(colIndex);
    // セルのスタイルを返します
    return cell.getCellStyle();
  }

  /**
   * 対象のマージされたセルにスタイルを設定します。
   *
   * @param sheet         シート
   * @param targetRegion  対象の領域
   * @param sourceStyle   ソースとなるスタイル
   */
  private static void setTargetMergedCellStyles(Sheet sheet, CellRangeAddress targetRegion, CellStyle sourceStyle) {
    // 対象の領域内の各行について処理します
    for (int rowIndex = targetRegion.getFirstRow(); rowIndex <= targetRegion.getLastRow(); rowIndex++) {
      // 行を取得します
      Row row = sheet.getRow(rowIndex);
      // 行が存在しない場合、新しい行を作成します
      if (row == null) {
        row = sheet.createRow(rowIndex);
      }
      // 対象の領域内の各列について処理します
      for (int colIndex = targetRegion.getFirstColumn(); colIndex <= targetRegion.getLastColumn(); colIndex++) {
        // セルを取得します
        Cell cell = row.getCell(colIndex);
        // セルが存在しない場合、新しいセルを作成します
        if (cell == null) {
          cell = row.createCell(colIndex);
        }
        // セルにソースとなるスタイルを設定します
        cell.setCellStyle(sourceStyle);
      }
    }
  }

  /**
   * 指定されたマージされたセルが空かどうかを判定します。
   *
   * @param sheet         シート
   * @param targetRegion  対象の領域
   * @return              マージされたセルが空の場合は true、そうでない場合は false
   */
  private static boolean isMergedCellEmpty(Sheet sheet, CellRangeAddress targetRegion) {
    // マージされた領域内の各行について処理します
    for (int rowIndex = targetRegion.getFirstRow(); rowIndex <= targetRegion.getLastRow(); rowIndex++) {
      // 行を取得します
      Row row = sheet.getRow(rowIndex);
      // 行が存在する場合の処理
      if (row != null) {
        // マージされた領域内の各列について処理します
        for (int colIndex = targetRegion.getFirstColumn(); colIndex <= targetRegion.getLastColumn(); colIndex++) {
          // セルを取得します
          Cell cell = row.getCell(colIndex);
          // セルが空でない場合、またはセルのタイプが空白でない場合、trueを返します
          if (!StringUtils.isEmpty(cell) && cell.getCellType() != CellType.BLANK) {
            return true;
          }
        }
      }
    }
    // マージされたセルが空の場合は false を返します
    return false;
  }

  /**
   * 指定された領域内のセルの値を取得します。
   *
   * @param sheet         シート
   * @param startRow      開始行インデックス
   * @param endRow        終了行インデックス
   * @param startColumn   開始列インデックス
   * @param endColumn     終了列インデックス
   * @return              領域内のセルの値のリスト
   */
  private static List<String> getValuesInRegion(Sheet sheet, int startRow, int endRow, int startColumn, int endColumn) {
    // セルの値を格納するリストを作成します
    List<String> cellValues = new ArrayList<>();
    // 開始行から終了行までループします
    for (int rowIndex = startRow; rowIndex <= endRow; rowIndex++) {
      // 行を取得します
      Row row = sheet.getRow(rowIndex);
      // 行が存在する場合の処理
      if (row != null) {
        // 開始列から終了列までループします
        for (int columnIndex = startColumn; columnIndex <= endColumn; columnIndex++) {
          // セルを取得します
          Cell cell = row.getCell(columnIndex);
          // セルが存在する場合の処理
          if (cell != null) {
            // セルのタイプに応じて値を取得します
            switch (cell.getCellType()) {
              case STRING:
                // 文字列型の場合、値を取得します
                String value = cell.getStringCellValue();
                // 値が空でない場合、リストに追加します
                if (!value.isEmpty()) {
                  cellValues.add(value);
                }
                break;
              case NUMERIC:
                // 数値型の場合、値を取得します
                cellValues.add(String.valueOf(cell.getNumericCellValue()));
                break;
              case BOOLEAN:
                // ブール型の場合、値を取得します
                cellValues.add(String.valueOf(cell.getBooleanCellValue()));
                break;
              case FORMULA:
                // フォーミュラ型の場合、値を取得します
                cellValues.add(cell.getCellFormula());
                break;
            }
          }
        }
      }
    }
    // セルの値のリストを返します
    return cellValues;
  }

  /**
   * マージされたセルに値を設定します。
   *
   * @param sheet         シート
   * @param mergedRegion  マージされた領域
   * @param cellValues    セルの値のリスト
   */
  private static void setValuesToMergedCells(Sheet sheet, CellRangeAddress mergedRegion, List<String> cellValues) {
    // インデックスを初期化します
    int valueIndex = 0;
    // マージされた領域内の各行に対して処理を行います
    for (int rowIndex = mergedRegion.getFirstRow(); rowIndex <= mergedRegion.getLastRow(); rowIndex++) {
      // 行を取得します
      Row row = sheet.getRow(rowIndex);
      // 行が存在しない場合、新しい行を作成します
      if (row == null) {
        row = sheet.createRow(rowIndex);
      }
      // マージされた領域内の各列に対して処理を行います
      for (int colIndex = mergedRegion.getFirstColumn(); colIndex <= mergedRegion.getLastColumn(); colIndex++) {
        // セルを取得します
        Cell cell = row.getCell(colIndex);
        // セルが存在しない場合、新しいセルを作成します
        if (cell == null) {
          cell = row.createCell(colIndex);
        }
        // セルに値を設定します
        if (valueIndex < cellValues.size()) {
          cell.setCellValue(cellValues.get(valueIndex));
          // インデックスをインクリメントします
          valueIndex++;
        } else {
          // 値が切れたらループを飛び出します
          break;
        }
      }
    }
  }

  // mod #11232 #10515で入れた制限の見直し 房 start
  /**
   * 元のセルのパターンをコピーします(目的のセルの境界線はそのままにします)
   * @param wb ワークブックオブジェクト
   * @param sourceCell コピー元のセルオブジェクト
   * @param targetCell コピー先のセルオブジェクト
   *
   * */
  private void copyStyleExceptLines(Workbook wb,Cell sourceCell,Cell targetCell,String index, Map<String, CellStyle> baseMap) {
    String key = "newCellStyle" + index;
    // 新しいセルスタイルを作成します
    CellStyle newstyle = null;
    if(baseMap != null && baseMap.containsKey(key)) {
      newstyle = baseMap.get(key);
    } else {
      newstyle= wb.createCellStyle();
    }
    // mod #11232 #10515で入れた制限の見直し 房 end
    // 罫線を除いてソースセルのスタイルを新しいスタイルにコピーします
    copyCellStyle(wb, sourceCell.getCellStyle(), newstyle, false);
    // 罫線をコピーしない場合、新しいスタイルが目標セルのスタイルを上書きしないようにします
    newstyle.setBorderBottom(targetCell.getCellStyle().getBorderBottom());
    newstyle.setBorderLeft(targetCell.getCellStyle().getBorderLeft());
    newstyle.setBorderRight(targetCell.getCellStyle().getBorderRight());
    newstyle.setBorderTop(targetCell.getCellStyle().getBorderTop());
    newstyle.setTopBorderColor(targetCell.getCellStyle().getTopBorderColor());
    newstyle.setBottomBorderColor(targetCell.getCellStyle().getBottomBorderColor());
    newstyle.setRightBorderColor(targetCell.getCellStyle().getRightBorderColor());
    newstyle.setLeftBorderColor(targetCell.getCellStyle().getLeftBorderColor());
    // add #11232 #10515で入れた制限の見直し 房 start
    if(baseMap != null && !baseMap.containsKey(key)) {
      baseMap.put(key, newstyle);
    }
    // add #11232 #10515で入れた制限の見直し 房 end
    // 新しいスタイルを目標セルに設定します
    targetCell.setCellStyle(newstyle);
  }
  // add #9816 テンプレート設定に関する処理がデザイナと帳票生成時で重複している 高 end

  private List<Map<String, Object>> MultiplePatientCompare133(List<Map<String, Object>> midList133,List sortKey,List tmpSortKey,List sortDirection,String sortKeyOne, String sortKeyTwo,List sortKeyName) {
    // tmpSortKey が null または空の場合はそのまま返す
    if (tmpSortKey == null || tmpSortKey.isEmpty()) return midList133;

    // 血液型用の2つのフィールドを保持
    String finalSortKeyOne = sortKeyOne;
    String finalSortKeyTwo = sortKeyTwo;

    // Comparator を作成
    Comparator<Map<String, Object>> comparator = (a, b) -> {
      // sortKey の優先順位に従って比較
      for (int i = 0; i < sortKey.size(); i++) {
        String key = String.valueOf(sortKey.get(i));
        // sortDirection が存在すれば取得、なければ "asc" をデフォルト
        String direction = (sortDirection != null && i < sortDirection.size()) ? String.valueOf(sortDirection.get(i)) : "asc";

        // 血液型の場合は特殊処理: finalSortKeyOne, finalSortKeyTwo を順に比較
        if (sortKeyName.contains(CoreConstant.ReportMenu.BLOOD_TYPE) && "pat_blood_type_abo".equals(key)) {
          String va = safeString(a.get(finalSortKeyOne));
          String vb = safeString(b.get(finalSortKeyOne));
          if (!va.equalsIgnoreCase(vb)) {
            int cmp = va.compareToIgnoreCase(vb);
            return "asc".equalsIgnoreCase(direction) ? cmp : -cmp;
          }

          va = safeString(a.get(finalSortKeyTwo));
          vb = safeString(b.get(finalSortKeyTwo));
          if (!va.equalsIgnoreCase(vb)) {
            int cmp = va.compareToIgnoreCase(vb);
            return "asc".equalsIgnoreCase(direction) ? cmp : -cmp;
          }

          // 両方のフィールドが同じ場合は次の sortKey へ
          continue;
        }

        // 血液型以外の通常フィールドの処理
        String va = safeString(a.get(key));
        String vb = safeString(b.get(key));

        // 値が同じ場合は次の優先キーへ
        if (va.equalsIgnoreCase(vb)) continue;

        int cmp;
        // hosp_pat_id は専用の比較ルールを使用
        if ("hosp_pat_id".equals(key)) {
          cmp = comparePatientId(va, vb);
        } else {
          // その他の文字列は大文字小文字を区別せず辞書順で比較
          cmp = va.compareToIgnoreCase(vb);
        }

        // 昇順・降順を適用
        return "asc".equalsIgnoreCase(direction) ? cmp : -cmp;
      }

      // 全ての優先フィールドが同じ場合は、pat_id で tie-breaker
      // これによりソートの安定性と決定性を保証
      return comparePatientId(safeString(a.get("pat_id")), safeString(b.get("pat_id")));
    };

    // Comparator に従ってソートしたリストを返す
    return midList133.stream().sorted(comparator).collect(Collectors.toList());
  }
