  // add #10857 １帳票内に同項目が複数あると設定値を取り違える 高 start
  public static List<String> findDuplicatesSqlCode(List<ReportXmlParam> params) {
    Set<String> seen = new HashSet<>();
    Set<String> duplicates = new HashSet<>();
    for (ReportXmlParam item : params) {
      if (!seen.add(item.getDataCode()) && !StringUtils.isEmpty(item.getSqlCode())) {
        duplicates.add(item.getSqlCode());
      }
    }
    return new ArrayList<>(duplicates);
  }

  public static List<String> findDuplicatesDateCode(List<ReportXmlParam> params) {
    Set<String> seen = new HashSet<>();
    Set<String> duplicates = new HashSet<>();
    for (ReportXmlParam item : params) {
      if (!seen.add(item.getDataCode()) && !StringUtils.isEmpty(item.getDataCode())) {
        duplicates.add(item.getDataCode());
      }
    }
    return new ArrayList<>(duplicates);
  }

