  // add #11127 グループ除外処理の残対応（モニタ、身体情報）　高　start
  /**
   * 入力文字列から、最後の "99999" を見つけ、
   * その直後に "11111" または "22222" があればスキップし、
   * その後ろの部分を返す。
   */
  public static String extractFinalSuffix(String input) {
    if (input == null || input.length() < 5) {
      return null;
    }

    try {
      // 最後の "99999" を探す
      int baseIndex = input.lastIndexOf("99999");
      if (baseIndex == -1) return null;

      int suffixStart = baseIndex + 5;

      // optional fixed values
      String[] optionalFixed = { "11111", "22222" };

      for (String fixed : optionalFixed) {
        int end = suffixStart + fixed.length();
        if (input.length() >= end && input.substring(suffixStart, end).equals(fixed)) {
          suffixStart = end;
          break;
        }
      }

      return suffixStart < input.length() ? input.substring(suffixStart) : "";

    } catch (Exception e) {
      return null;
    }
  }
