  private void lableReomoveStartCell(Sheet st, Workbook wb, Optional<ReportXmlTmplRepeat> tmplRepeat, Integer stPos){
    // テンプレート範囲を取得
    String[] idFT = tmplRepeat.get().getId().split(":");
    if (idFT.length == 2) {
      // tmplRepeatの開始コラム
      int tmplColFrom = 0;
      // tmplRepeatの終了コラム
      int tmplColTo = 0;
      // tmplRepeatの開始行
      int tmplRowFrom = 0;
      // tmplRepeatの終了行
      int tmplRowTo = 0;

      tmplRowFrom = getRowCount(idFT[0]);
      tmplRowTo = getRowCount(idFT[1]);

      tmplColFrom = getColumnCount(idFT[0]);
      tmplColTo = getColumnCount(idFT[1]);

      // コピー元(行)
      Row srcRow = null;
      // コピー元(コラム)
      Cell srcCell = null;

      // style、value のコピー
      if (stPos > 1 && String.format("%s%d", SHEET_NAME_PREFIX, 1).equals(st.getSheetName())) {
        for (int i = tmplRowFrom - 1; i< tmplRowTo; i++) {
          for (int j = tmplColFrom - 1; j < tmplColTo; j++) {
            if (st.getRow(i) == null) {
              srcRow = st.createRow(i);
            } else {
              srcRow = st.getRow(i);
            }
            if (srcRow.getCell(j) == null) {
              srcCell = srcRow.createCell(j);
            } else {
              srcCell = srcRow.getCell(j);
            }
            CellStyle cellStyle = wb.createCellStyle();
            srcCell.setCellStyle(cellStyle);
            srcCell.setCellValue("");
            cellStyle.setBorderBottom(BorderStyle.NONE);
          }
        }
      }
    }
  }
