  public boolean isHaveInfotoShow(Map<String, String> reportOutputInfo)
  // mod #12400 配布リスト、ラベルのテンプレート処理不正 limingzhe end
  {
    if(reportOutputInfo == null || reportOutputInfo.size() == 0) return false;
    for(String key : reportOutputInfo.keySet()){
      if(reportOutputInfo.get(key).length()>0)
        return true;
    }
    return false;
  }
