  /**
   * パラメータリストを基にMongoDBクエリに関連するデータを取得し、
   * テンプレートの有無に応じて結果を分類するメソッド。
   *
   * @param params            全てのレポートパラメータのリスト
   * @param paramsMongoNoTmpl テンプレートに含まれていないパラメータのリスト
   * @param paramsMongoYesTmplIN テンプレートに含まれているパラメータのリスト（IN）
   * @param paramsMongoYesTmplOUT テンプレートに含まれているパラメータのリスト（OUT）
   */
  // mod #10887 繰返しでない項目」「グループ改頁OFFの項目」がテンプレート繰返し時に不正 limingzhe start
  //private void paramsByMongoHistory(List<ReportXmlParam> params,
  public void paramsByMongoHistory(List<ReportXmlParam> params,
  // mod #10887 繰返しでない項目」「グループ改頁OFFの項目」がテンプレート繰返し時に不正 limingzhe end
                                    List<ReportXmlParam> paramsMongoNoTmpl,
                                    List<ReportXmlParam> paramsMongoYesTmplIN,
                                    List<ReportXmlParam> paramsMongoYesTmplOUT,
                                    List<ReportXmlParam> paramsNoMongo) {
    // 提供されたパラメータリストからSQLコードを取得する
    List<String> sqlCodes = getSqlCode(params);
    // MongoDBクエリに関連するユニークなSQLコードを格納するリスト
    List<Long> sqlCodeMongo = new ArrayList<>();
    List<Long> sqlCodeNoMongo = new ArrayList<>();

    // 各SQLコードを繰り返し処理し、MongoDBクエリに対応するかどうかを判断する
    for (int index = 0; index < sqlCodes.size(); index++) {
      // SQLコマンドがMongoDBコレクションを示しているかどうかを確認する
      if (sysDataSetService.isMongDBSqlSearch(Long.parseLong(sqlCodes.get(index)))) {
        // MongoDBのSQLコードがリストにまだ存在しない場合、リストに追加する
        if (!sqlCodeMongo.contains(Long.parseLong(sqlCodes.get(index)))) {
          sqlCodeMongo.add(Long.parseLong(sqlCodes.get(index)));
        }
      }
      // add #11494 データセットにカテゴリ「レセプト」を追加 limingzhe start
      else if(sqlCodes.get(index).equals("239")){
        if (!sqlCodeMongo.contains(Long.parseLong(sqlCodes.get(index)))) {
          sqlCodeMongo.add(Long.parseLong(sqlCodes.get(index)));
        }
      }
      // add #11494 データセットにカテゴリ「レセプト」を追加 limingzhe end
      else {
        if (!sqlCodeNoMongo.contains(Long.parseLong(sqlCodes.get(index)))) {
          sqlCodeNoMongo.add(Long.parseLong(sqlCodes.get(index)));
        }
      }
    }

    // MongoDBリスト内の各SQLコードを繰り返し処理する
    for (int indexNum = 0; indexNum < sqlCodeMongo.size(); indexNum++) {
      // 元のパラメータリストの各パラメータと照合する
      for (int index = 0; index < params.size(); index++) {
        ReportXmlParam param = params.get(index);
        // MongoDBのSQLコードとパラメータのSQLコードを比較する
        if (String.valueOf(sqlCodeMongo.get(indexNum)).equals(param.getSqlCode())) {
          // "isInTmpl"の値に基づいて、パラメータを適切な出力リストに分類する
          if ("0".equals(param.getIsInTmpl())) {
            // "isInTmpl"が"0"の場合はparamsMongoYesTmplOUTに追加
            paramsMongoYesTmplOUT.add(params.get(index));
          } else if ("1".equals(param.getIsInTmpl())) {
            // "isInTmpl"が"1"の場合はparamsMongoYesTmplINに追加
            paramsMongoYesTmplIN.add(params.get(index));
          } else {
            // "isInTmpl"が"0"でも"1"でもない場合はparamsMongoNoTmplに追加
            paramsMongoNoTmpl.add(params.get(index));
          }
        }
      }
    }
    for (int indexNum = 0; indexNum < sqlCodeNoMongo.size(); indexNum++) {
      // 元のパラメータリストの各パラメータと照合する
      for (int index = 0; index < params.size(); index++) {
        ReportXmlParam param = params.get(index);
        // MongoDBのSQLコードとパラメータのSQLコードを比較する
        if (String.valueOf(sqlCodeNoMongo.get(indexNum)).equals(param.getSqlCode())) {
          // "isInTmpl"の値に基づいて、パラメータを適切な出力リストに分類する
          paramsNoMongo.add(params.get(index));
        }
      }
    }
    // del #11226 患者情報系historyの取得条件見直し② (複数患者帳票) 高　start
//    for (int indexNum = 0; indexNum < paramsMongoYesTmplIN.size(); indexNum++) {
//      paramsNoMongo.add(paramsMongoYesTmplIN.get(indexNum));
//    }
    // del #11226 患者情報系historyの取得条件見直し② (複数患者帳票) 高　end
  }

