  public List<ReportXmlParam> paramsReplaceTmpMongo(List<ReportXmlParam> params, String tmpValue, ReportXmlParam paramPrescription){
    for (int indexP = 0; indexP < params.size();indexP++) {
      if (params.get(indexP).getSqlCode().equals(paramPrescription.getSqlCode()) && params.get(indexP).getIsInTmpl().equals(paramPrescription.getIsInTmpl()) ) {
        ReportXmlParam param = params.get(indexP);
        params.set(indexP, new ReportXmlParam(
          param.getIsImage(),
          param.getRepeatAddress(),
          param.getId(),
          param.getDispType(),
          param.getDataCode(),
          tmpValue + param.getSqlCode(),
          param.getDataType(),
          param.getIsShrink(),
          param.getDispLength(),
          param.getFilterType(),
          param.getDispFormat(),
          param.getFormula(),
          param.getGroupId(),
          param.getIsInTmpl(),
          param.getIsNewPage(),
          param.getColWidth(),
          param.getRowHeight(),
          // add #11276 キー日付に対するデータ引き当て仕様対応 高　start
          param.getDataPath(),
          // add #11276 キー日付に対するデータ引き当て仕様対応 高　end
          param.getRowCount(),
          param.getReportXmlFilters(),
          // add #12549 現状の設定仕様では装置点検帳票の要求を満たせない limingzhe start
          param.getReportXmlFiltersForMainte(),
          // add #12549 現状の設定仕様では装置点検帳票の要求を満たせない limingzhe end
          param.getReportXmlConvs(),
          param.getReportXmlGroup(),
          param.getReportXmlFormatConditions(),
          param.getFunction(),
          param.getTargetCells(),
          param.getReportXmlTmplRepeat(),
          param.getReportXmlTotalTable(),
          param.getParticular(),
          param.getReportXmlClassificationDataCodes(),
          // add #11535 帳票の汎用バーコード出力対応 吉 start
          param.getBarCode()
  // add #11535 帳票の汎用バーコード出力対応 吉 end
        ));
      }
    }
    return params;
  }

