  public Map<String, String> getSortKey(String tmplKey){
  // mod #10887 繰返しでない項目」「グループ改頁OFFの項目」がテンプレート繰返し時に不正 limingzhe end
    String tmplSortKey = "treat_date";
    String sortDb = "ord_main";
    switch(tmplKey) {
      case "ord_no":
        tmplSortKey = "treat_date";
        sortDb = "ord_main";
        break;
      case "exam_main_cd":
        tmplSortKey = "reg_exam_date";
        sortDb = "pat_exam_main";
        break;
      case "ord_prescription_no":
        tmplSortKey = "issue_date";
        sortDb = "ord_prescription";
        break;
      case "rad_result_cd":
        tmplSortKey = "reg_rad_date";
        sortDb = "pat_rad_main";
        break;
      case "mainte_no":
        tmplSortKey = "mainte_date";
        sortDb = "mnt_mainte_main";
        break;
      case "pat_event_cd":
        tmplSortKey = "event_start_date";
        sortDb = "pat_event";
        break;
    }
    Map<String, String> result = new HashMap<>();
    result.put("tmplKey", tmplKey);
    result.put("tmplSortKey", tmplSortKey);
    result.put("sortDb", sortDb);
    return result;
  }
