  // add #11679 複数患者帳票で「透析条件.補液量」が出ない limingzhe start
  public List<Map<String, Object>> getGroupKeyNoList(String tmplKey, Map<String, Object> dataKey, String sortDirection){
    Map<String, String> sortKey = getSortKey(tmplKey);
    List<Map<String, Object>> results = new ArrayList<>();
    if(tmplKey.length()>0){
      StringBuilder sqlBuilder = new StringBuilder();
      sqlBuilder.append("select ").append(sortKey.get("tmplKey")).append(",").append(sortKey.get("tmplSortKey"));
      sqlBuilder.append(" from ").append(sortKey.get("sortDb"));
      // mod #12206 【デグレード】帳票画面で透析予測でのソートが機能しない 高 start
      if (String.valueOf(dataKey.get("patId")).contains("-")) {
        sqlBuilder.append(" where pat_id is null ");
      } else {
        sqlBuilder.append(" where pat_id = ").append(dataKey.get("patId"));
      }
      sqlBuilder.append(" and facility_cd = '").append(dataKey.get("facilityCd")).append("'");
//      sqlBuilder.append(" where pat_id = ").append(dataKey.get("patId")).append(" and facility_cd = '").append(dataKey.get("facilityCd")).append("'");
      // mod #12206 【デグレード】帳票画面で透析予測でのソートが機能しない 高 end
      sqlBuilder.append(" and ").append(sortKey.get("tmplSortKey")).append(" between '");
      sqlBuilder.append(String.valueOf(dataKey.get("fromDate")).replace("/","").replace("-",""));
      sqlBuilder.append("' and '").append(String.valueOf(dataKey.get("toDate")).replace("/","").replace("-","")).append(" 235959'");
      if(tmplKey.equals("ord_prescription_no")){
        sqlBuilder.append(" and prescription_type in (");
        List<String> prescriptionTypeList = new ArrayList<>();
        if(dataKey.get("prescriptionClassList") != null){
          prescriptionTypeList = (List<String>) dataKey.get("prescriptionClassList");
        } else {
          prescriptionTypeList = new ArrayList<String>(Arrays.asList("1", "2"));
        }
        for(String t : prescriptionTypeList){
          sqlBuilder.append("'").append(t).append("',");
        }
        sqlBuilder.deleteCharAt(sqlBuilder.length() - 1);
        sqlBuilder.append(")");
      }
      else if(tmplKey.equals("exam_main_cd")){
        sqlBuilder.append(" and reg_order_class in (");
        List<String> regOrderClassList = new ArrayList<>();
        if(dataKey.get("regOrderClassList") != null){
          regOrderClassList = (List<String>) dataKey.get("regOrderClassList");
        } else {
          regOrderClassList = new ArrayList<String>(Arrays.asList("1", "2", "0"));
        }
        for(String t : regOrderClassList){
          sqlBuilder.append("'").append(t).append("',");
        }
        sqlBuilder.deleteCharAt(sqlBuilder.length() - 1);
        sqlBuilder.append(")");
      }
      sqlBuilder.append(" and is_del = '0'");
      sqlBuilder.append(" order by ").append(sortKey.get("tmplSortKey"));
      if (!StringUtils.isEmpty(sortDirection)) {
        sqlBuilder.append(" ").append(sortDirection);
      }
      sqlBuilder.append(",").append(sortKey.get("tmplKey"));
      results = sysDataSetService.sqlDB5Search(sqlBuilder.toString());
    }
    return results;
  }

  public String getContainsGroupKey(List<Map<String, Object>> reportInfo){
    String strKey = "";
    if(reportInfo == null || reportInfo.size() == 0) return strKey;
    String groupKeyArr[] = {"ord_no", "exam_main_cd", "ord_prescription_no", "rad_result_cd", "mainte_no", "pat_event_cd", "pat_info_date_key"};
    // mod #12157 帳票のデータ項目でpat_eventの内部ファイルパスが出力される limingzhe start
//    for (String element : groupKeyArr) {
//      if (reportInfo.get(0).containsKey(element)) {
//        strKey = element;
//        break;
//      }
//    }
    List<String> groupKeyList = List.of(groupKeyArr);
    for (String key : reportInfo.get(0).keySet()) {
      if (groupKeyList.contains(key)) {
        strKey = key;
        break;
      }
    }
    // mod #12157 帳票のデータ項目でpat_eventの内部ファイルパスが出力される limingzhe end
    return strKey;
  }

  public String getGroupKeybyDateType(String tmplSortKey){
    String strKey = Stream.of(tmplSortKey)
      .filter(Objects::nonNull)
      .map(Object::toString)
      .map(date -> date.replaceAll("[-/]", ""))
      .filter(date -> date.length() >= 8)
      .map(date -> date.substring(0, 8))
      .findFirst()
      .orElse("");
    return strKey;
  }
