  public List<String> getFacilitySettingOrderListToEquipment(String facilityCd, String settingNo){
    // 施設設定マスタNo.106 医材表示順 設定値
    List<FacilitySettingNoDisplayOrder> listDisplayOrder = new ArrayList<>();
    listDisplayOrder = ordMainDao.selectMedEquipDisplayOrder(facilityCd);
    String displayValue = null;
    String[] keyList = new String[]{};
    List<String> displayOrderList = new ArrayList<>();
    for (int x = 0; x < listDisplayOrder.size(); x++) {
      if (settingNo.equals(listDisplayOrder.get(x).getFacilitySettingNo())) {
        displayValue = listDisplayOrder.get(x).getValue();
      }
    }
    if (displayValue != null) {
      keyList = displayValue.replace("[","").replace("]","").replace("\"","").split(",");
    }
    for(int x = 0; x < keyList.length; x++){
      switch (keyList[x]){
        // 登録順
        case "0":
          displayOrderList.add("reg_order");
          break;
        // 医材分類順
        case "1":
          displayOrderList.add("class_order");
          break;
        // 医材マスタ表示順
        case "2":
          displayOrderList.add("code_order");
          // add #11623 ord_material_saveに薬剤や医材の登録順情報がない sunsy start
          displayOrderList.add("code_dia_order");
          // add #11623 ord_material_saveに薬剤や医材の登録順情報がない sunsy end
          break;
        default:
          break;
      }
    }
    return displayOrderList;
  }

