  private Map<String, Object> getLogTragetClass() {
    Map<String, Object> logTarget = new HashMap<>();

    // LogTargetClassに全ての対象値を取得
    Field[] fields = ReportConstant.LogTargetClass.class.getDeclaredFields();

    int index = 0; // Key 从 0 开始累加　デザイナーと合わせ、各対象値を数値0からkeyとする
    for (Field field : fields) {
      try {
        // static final の常数のみを処理する
        if (java.lang.reflect.Modifier.isStatic(field.getModifiers()) &&
          java.lang.reflect.Modifier.isFinal(field.getModifiers())) {
          Object value = field.get(null);  // 常数に対する値を取得
          logTarget.put(String.valueOf(index++), value);
        }
      } catch (IllegalAccessException e) {
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
        EventLogMessage eventLogMessage = new EventLogMessage();
        eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
        logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
      }
    }
    return logTarget;
  }
