  public void replaceMap(Map<String, Object> map, String facilityCd) {
    if (map == null || facilityCd == null) {
      return;
    }

    Map<String, String[]> keyMapping = Map.of(
      "ord_no", new String[]{"treat_date", "ord_main"},
      "exam_main_cd", new String[]{"reg_exam_date", "pat_exam_main"},
      "ord_prescription_no", new String[]{"issue_date", "ord_prescription"},
      "rad_result_cd", new String[]{"reg_rad_date", "pat_rad_main"},
      "mainte_no", new String[]{"mainte_date", "mnt_mainte_main"},
      "pat_event_cd", new String[]{"event_start_date", "pat_event"}
    );

    String tmplKey = "ord_no";
    String tmplSortKey = "treat_date";
    String sortDb = "ord_main";

    for (Map.Entry<String, String[]> entry : keyMapping.entrySet()) {
      if (map.containsKey(entry.getKey())) {
        tmplKey = entry.getKey();
        tmplSortKey = entry.getValue()[0];
        sortDb = entry.getValue()[1];
        break;
      }
    }

    Object tmplValue = map.get(tmplKey);
    if (tmplValue == null) {
      return;
    }

    String tmplValueStr = (tmplValue instanceof String) ? "'" + tmplValue + "'" : String.valueOf(tmplValue);
    String facilityCdStr = "'" + facilityCd + "'";

    String sql = String.format(
      "SELECT %s, %s FROM %s WHERE %s = %s AND facility_cd = %s AND is_del != '1' ORDER BY %s",
      tmplKey, tmplSortKey, sortDb, tmplKey, tmplValueStr, facilityCdStr, tmplSortKey
    );

    Config config = defaultDbConfig;
    SelectBuilder builder = SelectBuilder.newInstance(config);
    builder.sql(sql);

    List<Map<String, Object>> results = baseEntityDao.executeSql(builder);

    for (Map<String, Object> result : results) {
      if (tmplValue.equals(result.get(tmplKey))) {
        map.put(tmplSortKey, result.get(tmplSortKey));
        break;
      }
    }
  }
