  public static String getKeyValue(Map<Long, List<Map<String, Object>>> dataMap, long key, long offset) {
    String modifiedKey = new StringBuilder().append(key).append(offset).toString();

    for (Long keyOne : new HashSet<>(dataMap.keySet())) {
      if (String.valueOf(keyOne).indexOf(modifiedKey) != -1) {
        return String.valueOf(keyOne);
      }
    }
    return String.valueOf(offset);
  }
