  public List<Map<String, Object>> getPatHistory(Map<String, Object> dataKeyParamsMongoYesTmplIN,List<Map<String, Object>> results,String tmplSortKey) {
    List<Map<String, Object>> finalList = new ArrayList<>();
    if (results.size() != 0) {
      String originalStart = String.valueOf(results.get(0).get(tmplSortKey));
      String originalEnd = String.valueOf(results.get(results.size()-1).get(tmplSortKey));
      DateTimeFormatter inputFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.S");
      LocalDateTime dateTimeStart = LocalDateTime.parse(originalStart, inputFormat);
      LocalDateTime dateTimeEnd = LocalDateTime.parse(originalEnd, inputFormat);
      LocalDateTime startOfDay = dateTimeStart.toLocalDate().atStartOfDay();
      LocalDateTime endOfDay = dateTimeEnd.toLocalDate().atTime(23,59,59);
      DateTimeFormatter outputFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
      String resultStart = startOfDay.format(outputFormat);
      String resultEnd = endOfDay.format(outputFormat);

      MatchOperation match = Aggregation.match(Criteria.where("pat_id").is(String.valueOf(dataKeyParamsMongoYesTmplIN.get("patId")))
        .and("facility_cd").is(dataKeyParamsMongoYesTmplIN.get("facilityCd"))
        .and("is_del").is("0")
        .and("up_date")
        .lt(resultEnd));

      SortOperation sort = Aggregation.sort(Sort.by(Sort.Direction.DESC, "up_date"));

      Aggregation aggregation = Aggregation.newAggregation(match, sort);

      AggregationResults<Map> resultsOtherPat = mongoTemplate.aggregate(aggregation, "pat_personal_main_history", Map.class);

      for (Map result : resultsOtherPat.getMappedResults()) {
        finalList.add(new HashMap<>(result));
      }

    }
    return finalList;
  }

