  /**
   * バイタルサイズを取得
   * @param mstReport
   * @param reportZipFile
   * @param id
   * @return
   */
  private List<String> computeRangeSize(MstReport mstReport, ReportZipFile reportZipFile, String id) {
    List<String> sizeList = new ArrayList<>();
    com.aspose.cells.Workbook baseWorkbook = this.getReportAsposeWorkbook(mstReport, reportZipFile);
    WorksheetCollection workSheets = baseWorkbook.getWorksheets();
    Worksheet destSheet = workSheets.get(workSheets.getActiveSheetIndex());
    CellRangeAddress cellRange = AsposeExcelUtil.getCellRange(destSheet, id);
    String rangeHeight = computeRangeHeightAndWidth(cellRange, destSheet, true);
    String rangeWidth = computeRangeHeightAndWidth(cellRange, destSheet, false);
    sizeList.add(rangeHeight);
    sizeList.add(rangeWidth);
    return sizeList;
  }

  /**
   * asposeでExcelのWorkbookを取得
   * @param mstReport
   * @param reportZipFile
   * @return
   */
  private com.aspose.cells.Workbook getReportAsposeWorkbook(MstReport mstReport, ReportZipFile reportZipFile) {
    // エクセルファイルを取得
    byte[] excelData = reportZipFile.getFile(mstReport.getReportPath().getXlsxFilename());
    if (excelData != null && excelData.length > 0) {
      try (InputStream is = new ByteArrayInputStream(excelData)) {
        return new com.aspose.cells.Workbook(is);
      } catch (Exception e) {
        // エラーメッセージ
        EventLogMessage eventLogMessage = new EventLogMessage();
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang start
        eventLogMessage.setLogMessage("帳票デザインExcelファイルを取得できません:" + ExcetionStackTraceToString(e));
        // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang end
        logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
        throw new NtssException("帳票デザインExcelファイルを取得できません。", e);
      }
    } else {
      throw new NotExistException("帳票デザインExcelファイルを取得できません。");
    }
  }

  /**
   * バイタルのサイズを計算
   * @param range
   * @param worksheet
   * @param isRow
   * @return
   */
  private String computeRangeHeightAndWidth(CellRangeAddress range, Worksheet worksheet, boolean isRow) {
    BigDecimal result = new BigDecimal(0);
    if(isRow) {
      for(int i = range.getFirstRow(); i <= range.getLastRow(); i++) {
        result = result.add(new BigDecimal(worksheet.getCells().getRowHeight(i, false, CellsUnitType.POINT)));
      }
    } else {
      for(int i = range.getFirstColumn(); i <= range.getLastColumn(); i++) {
        result = result.add(new BigDecimal(worksheet.getCells().getColumnWidth(i, false, CellsUnitType.POINT)));
      }
    }
    // Excelのセルの範囲がオバーないように、サイズは小さくなる。
    return result.setScale(0, RoundingMode.DOWN).toString();
  }
