  // add #11106 集計帳票で集計範囲外のグループ項目が出力されない limingzhe start
  public static String[] getStartAndEndDayByDate(String yyyyMMdd){
    String mondayStr = null;
    String sundayStr = null;
    DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMdd");
    try{
      LocalDate date = LocalDate.parse(yyyyMMdd.replace("/","").replace("-",""), formatter);
      LocalDate monday = date.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));
      LocalDate sunday = date.with(TemporalAdjusters.nextOrSame(DayOfWeek.SUNDAY));
      DateTimeFormatter outputFormatter = DateTimeFormatter.ofPattern("yyyyMMdd");
      mondayStr = monday.format(outputFormatter);
      sundayStr = sunday.format(outputFormatter);
    } catch (Exception ignored) {}

    return new String[]{mondayStr, sundayStr};
  }

  public List<Map<String, Object>> getOrdNosbyDataKey(
    String facilityCd,
    List<Long> patIdList,
    String fromDate,
    String toDate
  ){
    List<Map<String, Object>> paramList = new ArrayList<>();
    Map<Long, List<Long>> patMapOrdNos = new HashMap<>();
    List<OrdMain> ordMainList = ordMainDao.selectAllByPatIdAndTreatDate(
      facilityCd,
      patIdList,
      fromDate,
      toDate
    );
    for (Long patId : patIdList) {
      List<Long> ordNos = new ArrayList<>();
      if(ordMainList != null){
        ordNos = ordMainList.stream().filter(el -> String.valueOf(el.getPatId()).equals(String.valueOf(patId))).map(el -> el.getOrdNo()).collect(toList());
      }
      if(ordNos == null || ordNos.size() == 0) ordNos.add(-1l);
      patMapOrdNos.put(patId, ordNos);
    }
    for(int i = 0; i < patIdList.size(); i++){
      Map<String, Object> paramMap = new HashMap<>();
      paramMap.put(ReportConstant.ReportDataKey.ORD_NO, patMapOrdNos.get(patIdList.get(i)).get(0));
      paramMap.put(ReportConstant.ReportDataKey.PAT_ID, patIdList.get(i));
      paramMap.put(ReportConstant.ReportDataKey.ORD_NOS, patMapOrdNos.get(patIdList.get(i)));
      paramList.add(paramMap);
    }
    return paramList;
  }
