  /**
   * パラメータ(フィルタ含む)のデータ
   *
   * @param params 帳票に定義されたパラメータリスト。ページ情報を含むものを処理対象とする。
   */
  public Map<String, Map<String, List<ReportXmlParam>>> getParamFilter(
    List<ReportXmlParam> params
  ){
    List<String> sqlCodes = getSqlCode(params);
    Map<String, List<ReportXmlParam>> groupedParamsbySqlCd = params.stream()
      .filter(p -> !StringUtils.isEmpty(p.getSqlCode()) && sqlCodes.contains(p.getSqlCode()))
      .collect(Collectors.groupingBy(p -> p.getSqlCode()))
      ;
    Map<String, Map<String, List<ReportXmlParam>>> groupedParams = new HashMap<>();
    for(String sqlCode : groupedParamsbySqlCd.keySet()) {
      Map<String, List<ReportXmlParam>> groupedParamsbyFilter = groupedParamsbySqlCd.get(sqlCode).stream()
        .filter(p -> !StringUtils.isEmpty(p.getFilterType()))
        .collect(Collectors.groupingBy(p -> p.getFilterType()));

      if(groupedParamsbyFilter.size() == 0) continue;
      groupedParams.put(sqlCode, groupedParamsbyFilter);
    }
    return groupedParams;
  }

