  private void sortListbyOriList(List<Map<String, Object>> list, List<Map<String, Object>> original) {
    list.sort(new Comparator<Map<String, Object>>() {
      @Override
      public int compare(Map<String, Object> o1, Map<String, Object> o2) {
        int index1 = getIndexInList(original, o1);
        int index2 = getIndexInList(original, o2);
        return Integer.compare(index1, index2);
      }
    });
  }

  private static int getIndexInList(List<Map<String, Object>> list, Map<String, Object> map) {
    for (int i = 0; i < list.size(); i++) {
      if (isSameMap(list.get(i), map)) {
        return i;
      }
    }
    return -1;
  }

  private static boolean isSameMap(Map<String, Object> map1, Map<String, Object> map2) {
    if (map1.size() != map2.size()) {
      return false;
    }
    for (Map.Entry<String, Object> entry : map1.entrySet()) {
      if(entry.getValue() == null && map2.get(entry.getKey()) == null) continue;
      if(entry.getValue() == null && map2.get(entry.getKey()) != null) return false;
      if (!entry.getValue().equals(map2.get(entry.getKey()))) {
        return false;
      }
    }
    return true;
  }

  public List<Map<String, Object>> getUniqueInfobyKey(
    String uniqueKey,
    List<Map<String, Object>> reportInfo
  ){
    if(uniqueKey.length() == 0) return reportInfo;

    List<Map<String, Object>> uniqueList = new ArrayList<>();
    final String fKey = uniqueKey;
    if(!StringUtils.isEmpty(uniqueKey)){
      String[] uniqKeyArr = uniqueKey.split(",");
      if(uniqKeyArr.length > 1){
        Set<String> seen = new HashSet<>();
        List<Map<String, Object>> result = new ArrayList<>();

        for (Map<String, Object> row : reportInfo) {
          StringBuilder sqlBuilder = new StringBuilder();
          for(int i = 0; i < uniqKeyArr.length; i++){
            Object key = row.containsKey(uniqKeyArr[i]) ? row.get(uniqKeyArr[i]) : null;
            sqlBuilder.append(String.valueOf(key));
            sqlBuilder.append(",");
          }

          if (seen.add(sqlBuilder.toString())) {
            result.add(row);
          }
        }
        uniqueList = result;
      }
      else if(uniqKeyArr.length == 1){
        uniqueList = reportInfo.stream()
          .collect(Collectors.toMap(
            map -> map.get(fKey),
            Function.identity(),
            (existing, replacement) -> existing,
            LinkedHashMap::new
          ))
          .values()
          .stream()
          .collect(Collectors.toList());
      }
    }
    return uniqueList;
  }

