  private List<Map<String, Object>> paramFilterReportInfo(
    ReportXmlParam param,
    List<Map<String, Object>> reportInfo
  ) {
    String filterType = param.getFilterType();
    if (StringUtils.isEmpty(filterType)) return reportInfo;
    // フィルタ設定が存在しない場合は、そのまま返却する
    if (param.getReportXmlFilters() == null || CollectionUtils.isEmpty(param.getReportXmlFilters())) return reportInfo;

    String targetCdName = getTargetCdName(filterType);

    List<Map<String, Object>> filtered = new ArrayList<>();

    for (ReportXmlFilterTable filter : param.getReportXmlFilters()) {
      // フィルタ定義に基づき、対象データを取得する
      String itemCd = filter.getCode();
      Stream<Map<String, Object>> tmpStream = reportInfo.stream();
      tmpStream = tmpStream.filter(r -> r.get(targetCdName) != null && itemCd.equals(r.get(targetCdName).toString()));

      if (filterType.equals("Examin") || filterType.equals("ExamSet")) {
        // 検査項目、検査セットのフィルタ処理

        // 透析前、後、その他のフィルタ条件を適用 ( 登録時検査区分：reg_order_class →  1:透析前 2:透析後 0:その他 ( string ) )
        boolean isBefore = filter.getBefore().equals("1") ? true : false; // 透析前のチェックが有効か
        boolean isAfter = filter.getAfter().equals("1") ? true : false;   // 透析後のチェックが有効か
        boolean isOther = filter.getOther().equals("1") ? true : false;   // その他のチェックが有効か

        tmpStream = tmpStream.filter(r -> r.get("reg_order_class") != null && (
            (r.get("reg_order_class").toString().equals("1") && isBefore) ||
            (r.get("reg_order_class").toString().equals("2") && isAfter) ||
            (r.get("reg_order_class").toString().equals("0") && isOther)));
      }

      filtered.addAll(tmpStream.collect(toList()));
    }

    // 順序を保証するために元の情報に対してフィルタする(元のデータは変更しません/フィルタされたデータを応答)
    return reportInfo.stream().filter(r -> filtered.contains(r)).collect(toList());
  }

  private List<Map<String, Object>> getParamFilterReportInfo(
    ReportXmlParam param,
    List<Map<String, Object>> reportInfo
  ){
    // フィルタ設定が存在しない場合は、そのまま返却する
    String filterType = param.getFilterType();
    if (StringUtils.isEmpty(filterType)) return reportInfo;
    if (param.getReportXmlFilters() == null || CollectionUtils.isEmpty(param.getReportXmlFilters())) return reportInfo;

	  String targetCdName = getTargetCdName(filterType);

    List<Map<String, Object>> filtered = new ArrayList<>();
    for (ReportXmlFilterTable filter : param.getReportXmlFilters()) {
      // フィルタ定義に基づき、対象データを取得する
      String itemCd = filter.getCode();
      Stream<Map<String, Object>> tmpStream = reportInfo.stream();
      tmpStream = tmpStream.filter(r -> r.get(targetCdName) != null && itemCd.equals(r.get(targetCdName).toString()));

      filtered.addAll(tmpStream.collect(toList()));
    }

    List<Map<String, Object>> filteredList = reportInfo.stream().filter(r -> filtered.contains(r)).collect(toList());

    String uniqueKey = getuniqueCdName(filterType);
    List<Map<String, Object>> reportInfobyKey = getUniqueInfobyKey(uniqueKey, reportInfo);
    List<String> examCdList = new ArrayList<>();
    List<String> examCdfilterList = new ArrayList<>();
    List<Map<String, Object>> tempList = new ArrayList<>();
    if(!StringUtils.isEmpty(uniqueKey)){
      String[] uniqKeyArr = uniqueKey.split(",");
      if(uniqKeyArr.length > 1){
        examCdList = reportInfobyKey.stream().map(p -> String.valueOf(p.get(uniqKeyArr[0])) + "," + String.valueOf(p.get(uniqKeyArr[1]))).collect(toList());
        examCdfilterList = filteredList.stream().map(p -> String.valueOf(p.get(uniqKeyArr[0])) + "," + String.valueOf(p.get(uniqKeyArr[1]))).collect(toList());

        if(examCdList.size() > 0 && examCdList.size() != examCdfilterList.size()){
          int index = 0;
          for(String cd : examCdList){
            if(examCdfilterList.contains(cd)){
              tempList.add(filteredList.get(index));
              index++;
            }
            else {
              String[] cdArr = cd.split(",");
              // add #10629 検査.検査予定の出力不正 高　start
              if (cdArr.length > 1)
              // add #10629 検査.検査予定の出力不正 高　end
              tempList.add(reportInfo.stream().filter(p -> String.valueOf(p.get(uniqKeyArr[0])).equals(cdArr[0]) && String.valueOf(p.get(uniqKeyArr[1])).equals(cdArr[1])).findFirst().get());
            }
          }
        }
      }
      else if(uniqKeyArr.length == 1){
        examCdList = reportInfobyKey.stream().map(p -> String.valueOf(p.get(uniqueKey))).collect(toList());
        examCdfilterList = filteredList.stream().map(p -> String.valueOf(p.get(uniqueKey))).collect(toList());

        if(examCdList.size() > 0 && examCdList.size() != examCdfilterList.size()){
          int index = 0;
          for(String cd : examCdList){
            if(examCdfilterList.contains(cd)){
              tempList.add(filteredList.get(index));
              index++;
            }
            else {
              tempList.add(reportInfo.stream().filter(p -> String.valueOf(p.get(uniqueKey)).equals(cd)).findFirst().get());
            }
          }
        }
      }
    }

    if (filterType.equals("Examin") || filterType.equals("ExamSet")){
      filtered.clear();
      for (ReportXmlFilterTable filter : param.getReportXmlFilters()) {
        // フィルタ定義に基づき、対象データを取得する
        Stream<Map<String, Object>> tmpStream = filteredList.stream();

        // 透析前、後、その他のフィルタ条件を適用 ( 登録時検査区分：reg_order_class →  1:透析前 2:透析後 0:その他 ( string ) )
        boolean isBefore = filter.getBefore().equals("1") ? true : false; // 透析前のチェックが有効か
        boolean isAfter = filter.getAfter().equals("1") ? true : false;   // 透析後のチェックが有効か
        boolean isOther = filter.getOther().equals("1") ? true : false;   // その他のチェックが有効か

        tmpStream = tmpStream.filter(r -> r.get("reg_order_class") != null && (
          (r.get("reg_order_class").toString().equals("1") && isBefore) ||
            (r.get("reg_order_class").toString().equals("2") && isAfter) ||
            (r.get("reg_order_class").toString().equals("0") && isOther)));

        filtered.addAll(tmpStream.collect(toList()));
      }
    }

    if(examCdList.size() > 0 && examCdList.size() != examCdfilterList.size()) {
      filteredList = tempList;
    }
    for (Map<String, Object> info : filteredList) {
      if (!filtered.contains(info)) {
        info.put(param.getDataCode(), "");
      }
    }
    return filteredList;
  }
