  private static List<String> findDuplicatesGroupId(Set<String> groupKeySet) {
    Set<String> seen = new HashSet<>();
    Set<String> duplicates = new HashSet<>();
    for (String key : groupKeySet) {
      String GroupId = "";
      if(!StringUtils.isEmpty(key)) {
        int index2 = key.indexOf(".", key.indexOf(".") + 1);
        GroupId = key.substring(0, index2);
      }
      if (!seen.add(GroupId)) {
        duplicates.add(GroupId);
      }
    }
    return new ArrayList<>(duplicates);
  }

  public List<ReportXmlParam> paramsReplaceSqlCodebyGroup(List<ReportXmlParam> params, Map<Long, List<Map<String, Object>>> reportInfo){
    List<String> paramTmp = findDuplicatesParamId(params);

    List<ReportXmlParam> paramsNew = new ArrayList<>();
    paramsNew = params.stream().filter(p -> p.getDataCode().equals("result_exam_output_base_date")).collect(toList());
    if(paramsNew.size() != 0) {
      if (!paramTmp.contains(paramsNew.get(0).getId())) paramTmp.add(paramsNew.get(0).getId());
    }

    Map<String, Set<String>> groupParamId = new HashMap<>();
    Map<String, Set<String>> sameGroupParamId = new HashMap<>();
    for (int index = 0; index < params.size();index++) {
      ReportXmlParam param = params.get(index);
      if(param == null) continue;

      String GroupId = "";
      if(!StringUtils.isEmpty(param.getGroupId())){
        GroupId = param.getGroupId().substring(0, param.getGroupId().lastIndexOf("."));
        Set<String> ids = new HashSet<>();
        if(groupParamId.containsKey(GroupId)){
          ids = groupParamId.get(GroupId);
        }
        ids.add(param.getId());
        groupParamId.put(GroupId, ids);
      }
    }
    List<String> groupTmp = findDuplicatesGroupId(groupParamId.keySet());
    for(String groupKey : groupParamId.keySet()){
      if(StringUtils.isEmpty(groupKey)) continue;
      int index2 = groupKey.indexOf(".", groupKey.indexOf(".") + 1);
      String GroupId = groupKey.substring(0, index2);
      if(!groupTmp.contains(GroupId)) continue;
      sameGroupParamId.put(groupKey, groupParamId.get(groupKey));
    }

    int index = 0;
    for (String sameGroupKey : sameGroupParamId.keySet()) {
      for (int indexP = 0; indexP < params.size();indexP++) {
        if (sameGroupParamId.get(sameGroupKey).contains(params.get(indexP).getId())) {
          ReportXmlParam param = params.get(indexP);
          try {
            if (!StringUtils.isEmpty(param.getSqlCode()) && reportInfo.get(Long.parseLong(param.getSqlCode())) != null) {
              Map<Long, List<Map<String, Object>>> reportInfoTmp = new HashMap<>();
              reportInfoTmp = filterReportInfoByXmlFilter(reportInfo,param);
              reportInfoTmp = reportInfoTmp.size() == 0 ? reportInfo : reportInfoTmp;
              reportInfo.put(Long.parseLong(String.valueOf(index+1) + SUFFIX + param.getSqlCode()),deepCopyList(reportInfoTmp.get(Long.parseLong(param.getSqlCode()))));
            }
          } catch (IOException e) {
            throw new RuntimeException(e);
          } catch (ClassNotFoundException e) {
            throw new RuntimeException(e);
          }
          params.set(indexP, new ReportXmlParam(
            param.getIsImage(),
            param.getRepeatAddress(),
            param.getId(),
            param.getDispType(),
            param.getDataCode(),
            String.valueOf(index+1) + SUFFIX + param.getSqlCode(),
            param.getDataType(),
            param.getIsShrink(),
            param.getDispLength(),
            param.getFilterType(),
            param.getDispFormat(),
            param.getFormula(),
            param.getGroupId(),
            param.getIsInTmpl(),
            param.getIsNewPage(),
            param.getColWidth(),
            param.getRowHeight(),
            param.getDataPath(),
            param.getRowCount(),
            param.getReportXmlFilters(),
            param.getReportXmlFiltersForMainte(),
            param.getReportXmlConvs(),
            param.getReportXmlGroup(),
            param.getReportXmlFormatConditions(),
            param.getFunction(),
            param.getTargetCells(),
            param.getReportXmlTmplRepeat(),
            param.getReportXmlTotalTable(),
            param.getParticular(),
            param.getReportXmlClassificationDataCodes(),
            param.getBarCode()
          ));
        }
      }
      index++;
    }
    return params;
  }

  private static String getuniqueCdNameForMainte(Set<String> reportInfoKeySet){
    String key = "machine_no";
    Set<String> keysbyDate = Set.of("mainte_date");
    Set<String> keysbyLayoutGroup = Set.of("mainte_layout_group_cd", "layout_group_name");
    Set<String> keysbyLayout = Set.of("mainte_layout_cd", "layout_name", "layout_header");
    Set<String> keysbyCategory = Set.of("category_cd", "category_name");
    Set<String> keysbyDetail = Set.of("mainte_detail_cd", "mainte_content_1", "mainte_content_2", "mainte_content_3");
    Set<String> keysbyMainte = Set.of("rec_no", "mainte_ans_1", "checker_id_1", "up_date", "judge", "mainte_comment", "user_id", "comment", "date");
    if(reportInfoKeySet.stream().filter(k -> keysbyDate.contains(k)).findFirst().isPresent()) {
      key = key.concat(",mainte_date");
    }
    if(reportInfoKeySet.stream().filter(k -> keysbyLayoutGroup.contains(k)).findFirst().isPresent()) {
      key = key.concat(",mainte_layout_group_cd");
    }
    if(reportInfoKeySet.stream().filter(k -> keysbyLayout.contains(k)).findFirst().isPresent()) {
      key = key.concat(",mainte_layout_cd");
    }
    if(reportInfoKeySet.stream().filter(k -> keysbyCategory.contains(k)).findFirst().isPresent()) {
      key = key.concat(",category_cd");
    }
    if(reportInfoKeySet.stream().filter(k -> keysbyDetail.contains(k)).findFirst().isPresent()) {
      key = key.concat(",mainte_detail_cd");
    }
    if(reportInfoKeySet.stream().filter(k -> keysbyMainte.contains(k)).findFirst().isPresent()) {
      key = key.concat(",mainte_no");
    }
    return key;
  }

  private List<Map<String, Object>> paramFilterReportInfoForMainte(
    ReportXmlParam param,
    List<Map<String, Object>> reportInfo
  ){
    String filterType = param.getFilterType();
    if (StringUtils.isEmpty(filterType)) return reportInfo;
    // フィルタ設定が存在しない場合は、そのまま返却する
    if (param.getReportXmlFiltersForMainte() == null || CollectionUtils.isEmpty(param.getReportXmlFiltersForMainte())) return reportInfo;

    List<Map<String, Object>> filtered = new ArrayList<>();

    for (ReportXmlFilter filter : param.getReportXmlFiltersForMainte()) {

      // フィルタ定義を取得する
      String[] items = filter.getItem().split(Pattern.quote("."));
      String[] cols =filter.getCol().split(Pattern.quote("."));
      if (items.length != cols.length) {
        continue;
      }

      // フィルタ定義に基づき、対象データを取得する
      Stream<Map<String, Object>> tmpStream = reportInfo.stream();
      for (int i = 0; i < items.length; i++) {
        String item = items[i];
        String col = cols[i];
        if (item.matches("-?\\d+")) {
          tmpStream = tmpStream.filter(r -> r.get(col) != null && item.equals(r.get(col).toString()));
        } else {
          tmpStream = tmpStream.filter(r -> r.get(col) != null);
        }
      }
      filtered.addAll(tmpStream.collect(toList()));
    }

    // 順序を保証するために元の情報に対してフィルタする(元のデータは変更しません/フィルタされたデータを応答)
    return reportInfo.stream().filter(r -> filtered.contains(r)).collect(toList());
  }

  private List<Map<String, Object>> getParamFilterReportInfoForMainte(
    ReportXmlParam param,
    List<Map<String, Object>> reportInfo
  ){
    String filterType = param.getFilterType();
    if (StringUtils.isEmpty(filterType)) return reportInfo;
    // フィルタ設定が存在しない場合は、そのまま返却する
    if (param.getReportXmlFiltersForMainte() == null || CollectionUtils.isEmpty(param.getReportXmlFiltersForMainte())) return reportInfo;

    List<Map<String, Object>> filtered = paramFilterReportInfoForMainte(param, reportInfo);
    List<Map<String, Object>> filteredList = new ArrayList<>(filtered);

    String uniqueKey = getuniqueCdName(filterType);

    List<Map<String, Object>> reportInfobyKey = getUniqueInfobyKey(uniqueKey, reportInfo);
    List<String> examCdList = new ArrayList<>();
    List<String> examCdfilterList = new ArrayList<>();
    List<Map<String, Object>> tempList = new ArrayList<>();
    if(!StringUtils.isEmpty(uniqueKey)){
      String[] uniqKeyArr = uniqueKey.split(",");
      if(uniqKeyArr.length > 1){
        examCdList = reportInfobyKey.stream().map(p -> {
          String appendKey = "";
          for(int i = 0; i < uniqKeyArr.length; i++){
            appendKey = appendKey.concat(String.valueOf(p.get(uniqKeyArr[i])));
            if(i < uniqKeyArr.length-1) appendKey = appendKey.concat(",");
          }
          return appendKey;
        }).collect(toList());
        examCdfilterList = filteredList.stream().map(p -> {
          String appendKey = "";
          for(int i = 0; i < uniqKeyArr.length; i++){
            appendKey = appendKey.concat(String.valueOf(p.get(uniqKeyArr[i])));
            if(i < uniqKeyArr.length-1) appendKey = appendKey.concat(",");
          }
          return appendKey;
        }).collect(toList());

        if(examCdList.size() > 0 && examCdList.size() != examCdfilterList.size()){
          int index = 0;
          for(String cd : examCdList){
            if(examCdfilterList.contains(cd)){
              tempList.add(filteredList.get(index));
              index++;
            }
            else {
              String[] cdArr = cd.split(",");
              tempList.add(reportInfo.stream().filter(p -> {
                boolean bHave = true;
                for(int i = 0; i < uniqKeyArr.length; i++){
                  if(!String.valueOf(p.get(uniqKeyArr[i])).equals(cdArr[i])) bHave = false;
                }
                return bHave;
              }).findFirst().get());
            }
          }
        }
      }
      else if(uniqKeyArr.length == 1){
        String key = uniqueKey;
        examCdList = reportInfobyKey.stream().map(p -> String.valueOf(p.get(key))).collect(toList());
        examCdfilterList = filteredList.stream().map(p -> String.valueOf(p.get(key))).collect(toList());

        if(examCdList.size() > 0 && examCdList.size() != examCdfilterList.size()){
          int index = 0;
          for(String cd : examCdList){
            if(examCdfilterList.contains(cd)){
              tempList.add(filteredList.get(index));
              index++;
            }
            else {
              tempList.add(reportInfo.stream().filter(p -> String.valueOf(p.get(key)).equals(cd)).findFirst().get());
            }
          }
        }
      }
    }

    if(examCdList.size() > 0 && examCdList.size() != examCdfilterList.size()) {
      filteredList = tempList;
    }
    for (Map<String, Object> info : filteredList) {
      if (!filtered.contains(info)) {
        info.put(param.getDataCode(), "");
      }
    }
    return filteredList;
  }
