  /**
   * reportInfoIndexMap をフィルタリングする共通処理
   *
   * ■ データ構造
   *   Map<患者ID, Map<sqlCd, List<帳票明細>>>
   *
   * ■ 処理対象
   *   ・sqlCd = 247 または 31 の明細のみ
   *
   * ■ フィルタ条件
   *   同一患者内で、同一 item_cd に対して
   *   sqlCd = 247 / 31 に存在するすべてのレコードの
   *   real_reg_order_class が
   *     ・null
   *     ・空文字 ("")
   *   のみで構成されている場合、
   *   その item_cd に紐づく全レコードを削除する
   *
   * ■ 注意点
   *   ・患者IDごとに独立して判定を行う
   *   ・247 / 31 以外の sqlCd のデータには影響しない
   *   ・処理は Map を直接書き換える（in-place）
   */
  public static void filterReportInfoIndexMap(
    Map<Long, Map<Long, List<Map<String, Object>>>> reportInfoIndexMap) {

    // ===============================
    // フィルタ対象となる sqlCd
    // ===============================
    Set<Long> targetSqlCds = Set.of(247L, 31L);

    // ===============================
    // 患者ID（patId）単位で処理
    // ===============================
    for (Map.Entry<Long, Map<Long, List<Map<String, Object>>>> patEntry
      : reportInfoIndexMap.entrySet()) {

      // 患者に紐づく sqlCd -> 明細リスト
      Map<Long, List<Map<String, Object>>> sqlMap = patEntry.getValue();

      // -------------------------------
      // 247 / 31 のデータのみ抽出
      // -------------------------------
      Map<Long, List<Map<String, Object>>> targetSqlMap = new HashMap<>();
      for (Long sqlCd : targetSqlCds) {
        if (sqlMap.containsKey(sqlCd)) {
          // 参照のみ保持（コピーはしない）
          targetSqlMap.put(sqlCd, sqlMap.get(sqlCd));
        }
      }

      // 対象 sqlCd が存在しない場合はスキップ
      if (targetSqlMap.isEmpty()) {
        continue;
      }

      // ===============================
      // item_cd 単位で明細をグルーピング
      // ===============================
      // key   : item_cd
      // value : 該当 item_cd の全レコード（247 / 31 混在）
      Map<Object, List<Map<String, Object>>> itemGroup = new HashMap<>();

      for (List<Map<String, Object>> list : targetSqlMap.values()) {
        for (Map<String, Object> row : list) {

          // 帳票明細から item_cd を取得
          Object itemCd = row.get("item_cd");

          // item_cd ごとにレコードを集約
          itemGroup
            .computeIfAbsent(itemCd, k -> new ArrayList<>())
            .add(row);
        }
      }

      // ===============================
      // 削除対象となる item_cd を判定
      // ===============================
      Set<Object> removeItemCds = new HashSet<>();

      for (Map.Entry<Object, List<Map<String, Object>>> entry
        : itemGroup.entrySet()) {

        // real_reg_order_class に有効値が存在するか
        boolean hasValidClass = false;

        for (Map<String, Object> row : entry.getValue()) {

          // オーダー区分（実オーダークラス）
          Object v = row.get("real_reg_order_class");

          // null でも空文字でもない場合は「有効」と判定
          if (v != null && !"".equals(v.toString())) {
            hasValidClass = true;
            break;
          }
        }

        // 全件が null / 空文字 の場合は削除対象
        if (!hasValidClass) {
          removeItemCds.add(entry.getKey());
        }
      }

      // ===============================
      // 実データから削除処理を実行
      // ===============================
      if (!removeItemCds.isEmpty()) {

        // sqlCd = 247 / 31 の両方に対して削除を行う
        for (Long sqlCd : targetSqlMap.keySet()) {

          // 元のリストを直接操作する
          List<Map<String, Object>> list = sqlMap.get(sqlCd);

          if (list != null) {
            // 削除対象 item_cd を持つ明細を除外
            list.removeIf(
              row -> removeItemCds.contains(row.get("item_cd"))
            );
          }
        }
      }
    }
  }

  /**
   * ReportInfo を XML フィルタ条件に基づいて絞り込む
   *
   * 処理内容：
   * 1. 指定された sqlCd（247 / 31 / 314）のみを対象にする
   * 2. item_cd によるフィルタリングを行う
   * 3. dataCode が result_exam_date の場合、患者ごとに最新日付のデータのみを取得する
   *
   * @param reportInfo SQLコード別の帳票データ
   * @param param      XML 帳票パラメータ
   * @return フィルタ後の帳票データ
   */
  public static Map<Long, List<Map<String, Object>>> filterReportInfoByXmlFilter(
    Map<Long, List<Map<String, Object>>> reportInfo,
    ReportXmlParam param) {

    // XML フィルタで指定された item_cd（先頭1件のみ使用）
    Object filterItemCd = null;
    List<String> classOrder = new ArrayList<>();
    if (param.getReportXmlFilters() != null
      && !param.getReportXmlFilters().isEmpty()) {
      filterItemCd = param.getReportXmlFilters().get(0).getCode();
      ReportXmlFilterTable filter = param.getReportXmlFilters().get(0);

      Stream.of(
          Map.entry(filter.getBefore(), "1"),
          Map.entry(filter.getAfter(),  "2"),
          Map.entry(filter.getOther(),  "0")
        )
        .filter(e -> "1".equals(e.getKey()))
        .map(Map.Entry::getValue)
        .forEach(classOrder::add);
    }

    // フィルタ対象となる SQL コード
    Set<Long> targetSqlCds = Set.of(247L, 31L, 314L);

    // 最終結果日付（result_exam_date）かどうかの判定
    // del #10650 検査結果（指定日以前）の仕様課題 2025/02/26 高 start
//    boolean isFinalResultDate =
//      "result_exam_output_base_date".equals(param.getDataCode());
    // del #10650 検査結果（指定日以前）の仕様課題 2025/02/26 高 end

    // 返却用結果マップ
    Map<Long, List<Map<String, Object>>> result = new HashMap<>();

    // SQLコード単位で処理
    for (Map.Entry<Long, List<Map<String, Object>>> entry : reportInfo.entrySet()) {

      Long sqlCd = entry.getKey();
      List<Map<String, Object>> originalList = entry.getValue();

      // データが空の場合はそのまま返却
      if (originalList == null || originalList.isEmpty()) {
        result.put(sqlCd, originalList);
        continue;
      }

      // 対象外の SQL コードは加工せずコピー
      if (!targetSqlCds.contains(sqlCd)) {
        result.put(sqlCd, new ArrayList<>(originalList));
        continue;
      }

      // ---------------------------------
      // item_cd によるフィルタ処理
      // ---------------------------------
      List<Map<String, Object>> filteredList = new ArrayList<>();

      for (Map<String, Object> row : originalList) {
        Object itemCd = row.get("item_cd");
        Object regOrderClass = row.get("reg_order_class");

        // XML フィルタで指定された item_cd と一致するもののみ抽出
        if (filterItemCd != null && Objects.equals(itemCd, filterItemCd) && classOrder.contains(regOrderClass)) {
          filteredList.add(row);
        }
      }

      // ---------------------------------
      // result_exam_date：
      // 患者（pat_id）ごとに最新日付のデータを1件取得
      // ---------------------------------
      // del #10650 検査結果（指定日以前）の仕様課題 2025/02/26 高 start
//      if (isFinalResultDate && !originalList.isEmpty()) {
//
//        Map<Object, Map<String, Object>> latestByPatient =
//          originalList.stream()
//            // 患者IDと検査日が存在するデータのみ対象
//            .filter(r ->
//              r.get("pat_id") != null
//                && !StringUtils.isEmpty(r.get("result_exam_output_base_date"))
//            )
//            .collect(Collectors.toMap(
//              // キー：患者ID
//              r -> r.get("pat_id"),
//              // 値：帳票1行
//              r -> r,
//              // 同一患者IDが存在する場合、検査日が新しい方を採用
//              (r1, r2) -> {
//                LocalDateTime d1 = toLocalDateTime(r1.get("result_exam_output_base_date"));
//                LocalDateTime d2 = toLocalDateTime(r2.get("result_exam_output_base_date"));
//                return d1.isAfter(d2) ? r1 : r2;
//              },
//              // 順序保持
//              LinkedHashMap::new
//            ));
//
//        // 最新データのみを結果として設定
//        result.put(sqlCd, new ArrayList<>(latestByPatient.values()));
//      } else {
//        // 通常時は item_cd フィルタ結果を設定
//        result.put(sqlCd, filteredList);
//      }
      // del #10650 検査結果（指定日以前）の仕様課題 2025/02/26 高 end
      // add #10650 検査結果（指定日以前）の仕様課題 2025/02/26 高 start
      // 通常時は item_cd フィルタ結果を設定
      result.put(sqlCd, filteredList);
      // add #10650 検査結果（指定日以前）の仕様課題 2025/02/26 高 end
    }

    return result;
  }

  /**
   * Object 型の日付データを LocalDateTime に変換する
   *
   * 対応型：
   * - LocalDateTime
   * - java.sql.Timestamp
   * - java.sql.Date
   * - String（ISO-8601形式）
   *
   * @param value 日付オブジェクト
   * @return LocalDateTime
   */
  private static LocalDateTime toLocalDateTime(Object value) {

    if (value instanceof LocalDateTime) {
      return (LocalDateTime) value;
    }
    if (value instanceof java.sql.Timestamp) {
      return ((java.sql.Timestamp) value).toLocalDateTime();
    }
    if (value instanceof java.sql.Date) {
      return ((java.sql.Date) value).toLocalDate().atStartOfDay();
    }
    if (value instanceof String) {
      return LocalDateTime.parse((String) value);
    }

    // 未対応型は例外
    throw new IllegalArgumentException(
      "Unsupported date type: " + value.getClass()
    );
  }

