  public String convertValue(List<Map<String, String>> convTableList, String value) {
    if(convTableList == null || convTableList.isEmpty()) {
      return value;
    }

    if(StringUtils.isEmpty(value)) {
      return value;
    }

    // 変換処理
    Optional<Map<String, String>> reportXmlConv = convTableList.stream()
      .filter(e -> value.equals(e.getOrDefault("code", null)))
      .findFirst();

    return reportXmlConv.isPresent() ? reportXmlConv.get().getOrDefault("disp", null) : value;
  }
