  /**
   * 計算項目
   *
   * @param params Param要素情報
   * @param reportInfo テンプレート外の単位項目の値を埋め込む処理
   * @param reportInTmplInfo 集計帳票でテンプレート内の単位項目の値を埋め込む処理
   * @param reportOutputInfo 帳票出力情報
   * @param calcResult 計算式をもとに算出した結果を適用するidとclassのMapを作成する
   */
  public void formulaCalculateForParams(
    List<ReportXmlParam> params,
    Map<Long, List<Map<String, Object>>> reportInfo,
    Map<Long, List<Map<String, Object>>> reportInTmplInfo,
    Map<String, String> reportOutputInfo,
    Map<String, String> calcResult
  ) {
    // Excel帳票のページ情報（総ページ数・現在ページ数）を処理し、
    getPagesForExcel(reportOutputInfo,params);

    // テンプレート繰り返しに対する処理を行う
    Map<String, String> calcResultTmpl = params.stream()
      .filter(p -> p.isFormulaToCalc() && null != p.getFunction() && p.getFunction().contains("##") && p.isTmplRepeat())
      .collect(Collectors.toMap(p -> p.getId(), p -> p.getFormula()));
    if(null != calcResultTmpl && calcResultTmpl.size()>0 && null != reportInTmplInfo){
      String tmplId = params.get(0).getReportXmlTmplRepeat().getId();
      Integer tmplRepeatMax = params.get(0).getReportXmlTmplRepeat().getRepeatMax();

      Map<String, String> reportOutputInfoInTmpl = reportOutputInfo.entrySet().stream()
        .filter(entry -> entry.getKey().indexOf(MULTIPLE_PAGES_SEPARATOR) >= 0 && entry.getKey().contains(tmplId))
        .collect(Collectors.toMap(entry -> entry.getKey(), entry -> entry.getValue()));

      Map<Long, List<Map<String, Object>>> reportInTmplInfoForCalculate = new HashMap<>(reportInTmplInfo);
      for (Long key : reportInfo.keySet()) {
        if (!reportInTmplInfoForCalculate.containsKey(key)) {
          reportInTmplInfoForCalculate.put(key, reportInfo.get(key));
        }
      }

      Integer endPage = getTmplPageCount(reportOutputInfoInTmpl);
      for (Integer pageIndex = 0; pageIndex < endPage; pageIndex++) {
        Integer endTmplbyKeyNo = getTmplCount(reportOutputInfoInTmpl, pageIndex + 1);
        for(Integer tmplLoopCount = 0 ; tmplLoopCount < endTmplbyKeyNo ; tmplLoopCount++){
          Map<String, String> tempcalcResult = getCalcResultForMultiPatient(params, reportInTmplInfoForCalculate, reportOutputInfoInTmpl,tmplLoopCount + (tmplRepeatMax * pageIndex));
          for(Map.Entry<String,String> entry : calcResultTmpl.entrySet().stream().filter(c -> !(c.getValue().contains(ReportConstant.ReportPrintedInfo.TOTALPAGES)
            && c.getValue().contains(ReportConstant.ReportPrintedInfo.CURRENTPAGE))).collect(toList())){
            String value = entry.getValue();
            if(isHave(entry.getValue())){
              for(Map.Entry<String,String> repkey : tempcalcResult.entrySet()){
                if(null == repkey.getValue() || "".equals(repkey.getValue())){
                  value = value.replace(repkey.getKey(),'"' +""+ '"');
                }else if(!isNumeric(repkey.getValue())){
                  value = value.replace(repkey.getKey(),'"' + repkey.getValue().replace("\"", "\"\"") + '"');
                }else{
                  value = value.replace(repkey.getKey(), repkey.getValue());
                }
              }
              value = excelConvert(value);
            }
            // add #10447 テンプレート繰返しでの計算式繰返しの制限事項対応③（項目指定とセル指定の混在）高 start
            // 数式内に「セル参照と他要素（数値・プレースホルダ等）の演算（連結）」が含まれている場合
            // 例：A1+1、B2&"text"、[X]*C3 など
            // → そのままでは評価できないため、プレースホルダを実際の値に置換する
            else if (hasConcatCellReference(entry.getValue())) {
              value = replaceFormulaValue(value, tempcalcResult);
            }
            // add #10447 テンプレート繰返しでの計算式繰返しの制限事項対応③（項目指定とセル指定の混在）高 end
            else{
              value = "";
            }
            String pageStr = String.format("%d%s", pageIndex + 1, MULTIPLE_PAGES_SEPARATOR);
            String keyTmpl = String.format("%s-%d", tmplId, tmplLoopCount + 1);
            String keyParam = entry.getKey();
            String key = String.format("%s%s.%s",pageStr, keyTmpl, keyParam);
            reportOutputInfo.put(key, value);
          }
        }
      }
    }

    // テンプレート外の計算式をもとに算出した結果を取得します.
    for (Long key : reportInTmplInfo.keySet()) {
      if (!reportInfo.containsKey(key)) {
        reportInfo.put(key, reportInTmplInfo.get(key));
      }
    }
    List<ReportXmlParam> paramsOther = params.stream()
      .filter(p -> !calcResultTmpl.keySet().contains(p.getId()))
      .collect(toList());
    calcResult = getCalcResult(paramsOther, reportInfo, reportOutputInfo);

    List<ReportXmlParam> paramsNew = new ArrayList<>();
    paramsNew.addAll(paramsOther);
    for (int i = 0; i < params.size(); i++) {
      ReportXmlParam value = params.get(i);
      ReportXmlParam newParam = paramsNew.stream().filter(p -> p.getId().equals(value.getId())).findFirst().orElse(null);
      if (newParam != null) {
        params.set(i, newParam);
      }
    }
  }

